window.__D("text/zohar-hebrew-translation/c013",{"p":[[9522011576,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה אֱמֹר אֶל אַהֲרֹן קַח מַטְּךְ וּנְטֵה יָדְךְ עַל מֵימֵי מִצְרַיִם עַל נַהֲרֹתָם עַל יְאֹרֵיהֶם וְעַל אַגְמֵיהֶם וְעַל כָּל מִקְוֵה מֵימֵיהֶם וְיִהְיוּ דָם וְגוֹ'. אָמַר רַבִּי יְהוּדָה, יֵשׁ לְהִסְתַּכֵּל בַּפָּסוּק הַזֶּה, וְאֵיךְ יָכוֹל לָלֶכֶת לְכָל הַמְּקוֹמוֹת הַלָּלוּ? (ולא עוד, אלא) וְעוֹד, שֶׁהֲרֵי כָּתוּב וַיִּמָּלֵא שִׁבְעַת יָמִים אַחֲרֵי הַכּוֹת ה' אֶת הַיְאֹר. אֶת הַיְאֹר כָּתוּב, וְאַתָּה אָמַרְתָּ עַל מֵימֵי מִצְרַיִם עַל נַהֲרֹתָם עַל יְאֹרֵיהֶם וְעַל אַגְמֵיהֶם?</p>\n<p>אֶלָּא, מֵימֵי מִצְרַיִם הָיָה הַנִּילוּס, וּמִשָּׁם מִתְמַלְּאִים כָּל אוֹתָם שְׁאָר אֲגַמִּים וִיאוֹרִים וּמַעְיָנוֹת וְכָל מֵימֵיהֶם, וְעַל זֶה אַהֲרֹן לֹא נָטָה לְהַכּוֹת, רַק אֶת הַנִּילוּס לְבַדּוֹ. וּבֹא רְאֵה שֶׁכָּכָה זֶה, שֶׁכָּתוּב וְלֹא יָכְלוּ מִצְרַיִם לִשְׁתּוֹת מַיִם מִן הַיְאֹר.</p>\n<p>אָמַר רַבִּי אַבָּא, בֹּא רְאֵה, מַיִם תַּחְתּוֹנִים נִפְרָדִים לְכַמָּה צְדָדִים, (ומים עליונים על אחת כמה וכמה וגו') (עליונים שהרי) וּמַיִם עֶלְיוֹנִים מִתְכַּנְּסִים לְבֵית כִּנּוּס הַמַּיִם, שֶׁכָּתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד, וְכָתוּב וּלְמִקְוֵה הַמַּיִם קָרָא יַמִּים. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ, וּבֹא רְאֵה, אוֹתוֹ רָקִיעַ שֶׁיֵּשׁ בּוֹ שֶׁמֶשׁ וּלְבָנָה, כּוֹכָבִים וּמַזָּלוֹת, זֶהוּ בֵּית כִּנּוּס לַמַּיִם הָרַבִּים, שֶׁהוּא נוֹטֵל כָּל הַמַּיִם וּמַשְׁקֶה אֶת הָאָרֶץ, שֶׁהוּא עוֹלָם תַּחְתּוֹן, כֵּיוָן שֶׁנּוֹטֵל אֶת הַמַּיִם, מְפַזֵּר אוֹתָם וּמְחַלֵּק אוֹתָם לְכָל עֵבֶר, וּמִשָּׁם הוּא מַשְׁקֶה אֶת כֻּלָּם.</p>\n<p>וּבִזְמַן שֶׁדִּין שׁוֹרֶה, הָעוֹלָם הַתַּחְתּוֹן לֹא יוֹנֵק מֵאוֹתוֹ רָקִיעַ, וְיוֹנֵק מִצַּד הַשְּׂמֹאל, וְאָז נִקְרָא (ישעיה לד) חֶרֶב לַה' מָלְאָה דָם. אוֹי לְאוֹתָם שֶׁיּוֹנְקִים מִמֶּנָּה אָז וּמֻשְׁקִים מִמֶּנָּה, שֶׁבְּאוֹתוֹ זְמַן הַיָּם יוֹנֵק מִשְּׁנֵי צְדָדִים, הָיָה מִתְחַלֵּק לִשְׁנֵי חֲלָקִים, לָבָן וְאָדם, וְאָז שׁוֹפֵךְ לַיְאֹר אֶת הַחֵלֶק שֶׁל מִצְרַיִם, וּמַלְקֶה לְמַעְלָה וּמַלְקֶה לְמַטָּה, וְלָכֵן יִשְׂרָאֵל שׁוֹתִים מַיִם וְהַמִּצְרִים דָּם.</p>\n<p>אִם תֹּאמַר שֶׁזֶּה הָיָה מִשּׁוּם הַגֹּעַל וְלֹא יוֹתֵר - בֹּא רְאֵה, שׁוֹתִים אֶת הַדָּם וְנִכְנָס לִמְעֵיהֶם וּמִתְעַלֶּה וּבוֹקֵעַ, עַד שֶׁהָיוּ יִשְׂרָאֵל מוֹכְרִים לָהֶם מַיִם בְּמָמוֹן, וְאָז שׁוֹתִים מַיִם, וּמִשּׁוּם כָּךְ רֵאשִׁית הַלְקָאָתָם הָיְתָה דָם.</p>\n<p>רַבִּי יִצְחָק פָּתַח פָּסוּק זֶה, (תהלים קמה) אֲרוֹמִמְךְ אֱלֹהַי הַמֶּלֶךְ וַאֲבָרְכָה שִׁמְךְ לְעוֹלָם וָעֶד. בֹּא רְאֵה, דָּוִד כְּנֶגֶד דַּרְגָּתוֹ אוֹמֵר, שֶׁכָּתַב אֱלֹהַי, שֶׁלִּי. מִשּׁוּם שֶׁרָצָה לְהַעֲלוֹת שִׁבְחוֹ וּלְהַכְנִיס אוֹתוֹ לְאוֹר עֶלְיוֹן לְהִתְעָרֵב זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד, מִשּׁוּם כָּךְ אֲרוֹמִמְךְ אֱלֹהַי הַמֶּלֶךְ וְגוֹ'.</p>\n<p>שֶׁשָּׁנִינוּ, כָּל יְמוֹת דָּוִד הִשְׁתַּדֵּל לְתַקֵּן אֶת הַכִּסֵּא וּלְהָאִיר פָּנֶיהָ כְּדֵי שֶׁתָּגֵן עָלָיו, וְיוֹאַר תָּמִיד הָאוֹר הַתַּחְתּוֹן בָּאוֹר הָעֶלְיוֹן לִהְיוֹת הַכֹּל אֶחָד. וּכְשֶׁבָּא שְׁלֹמֹה, מָצָא הָעוֹלָם שָׁלֵם, וְהַלְּבָנָה הִתְמַלְּאָה, וְלֹא צָרִיךְ לִטְרֹחַ עָלֶיהָ לַהֲאִירָהּ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָקַחַת נְקָמוֹת מֵעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, הִתְעוֹרֵר הַשְּׂמֹאל, וְהִתְמַלְּאָה הַלְּבָנָה מֵאוֹתוֹ הַצַּד דָּם. וְאָז נָבְעוּ מַעְיָנוֹת וּנְחָלִים שֶׁל מַטָּה, כָּל אוֹתָם שֶׁל צַד שְׂמֹאל בְּדָם, וְלָכֵן הַדִּין שֶׁלָּהֶם דָּם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁהַדָּם הַזֶּה מִתְעוֹרֵר (כשהדין מתעורר על העולם בגלל אותו דם של ההרוגים, הקדוש ברוך הוא מתעורר) עַל הָעָם, אוֹתוֹ דָם שֶׁל הַהֲרוּגִים הוּא שֶׁיִּתְעוֹרֵר עֲלֵיהֶם עַם אַחֵר וְהוֹרֵג אוֹתָם, אֲבָל (כעת) בְּמִצְרַיִם לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָבִיא עֲלֵיהֶם עַם אַחֵר לְעוֹרֵר עֲלֵיהֶם דָּם, מִשּׁוּם שֶׁיִּשְׂרָאֵל הָיוּ בֵינֵיהֶם וְלֹא יִצְטַעֲרוּ מִשּׁוּם שֶׁדָּרִים בְּאַרְצָם, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא הִכָּה אוֹתָם בְּדָם בַּנְּהָרוֹת שֶׁלָּהֶם, שֶׁלֹּא הָיוּ יְכוֹלִים לִשְׁתּוֹת.</p>\n<p>וּמִשּׁוּם שֶׁהַשִּׁלְטוֹן שֶׁלָּהֶם שׁוֹלֵט בְּאוֹתוֹ נָהָר, צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לַשַּׁלִּיט שֶׁלָּהֶם בָּרִאשׁוֹנָה, כְּדֵי שֶׁתִּלְקֶה יִרְאָתָם בָּרִאשׁוֹנָה, מִשּׁוּם שֶׁהַנִּילוּס הָיָה אֶחָד מִיִּרְאוֹתֵיהֶם, וְכֵן שְׁאָר הַיִּרְאוֹת שֶׁלָּהֶם נָבְעוּ דָם. זֶהוּ שֶׁכָּתוּב וְהָיָה דָם בְּכָל אֶרֶץ מִצְרַיִם וּבָעֵצִים וּבָאֲבָנִים.</p>\n<p>רַבִּי חִיָּיא קָם לַיְלָה אֶחָד לַעֲסֹק בַּתּוֹרָה, וְהָיָה עִמּוֹ רַבִּי יוֹסֵי הַקָּטָן, שֶׁהָיָה תִּינוֹק. פָּתַח רַבִּי חִיָּיא וְאָמַר, (קהלת ט) לֵךְ אֱכֹל בְּשִׂמְחָה לַחְמֶךְ וּשְׁתֵה בְלֶב טוֹב יֵינֶךְ כִּי כְבָר רָצָה הָאֱלֹהִים אֶת מַעֲשֶׂיךְ. מָה רָאָה שְׁלֹמֹה הַמֶּלֶךְ שֶׁאָמַר פָּסוּק זֶה?</p>\n<p>אֶלָּא שְׁלֹמֹה, כָּל דְּבָרָיו הָיוּ בְּחָכְמָה, וְזֶה שֶׁאָמַר לֵךְ אֱכֹל בְּשִׂמְחָה לַחְמֶךְ. בְּשָׁעָה שֶׁאָדָם הוֹלֵךְ בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקָרֵב אוֹתוֹ אֵלָיו וְנוֹתֵן לוֹ שַׁלְוָה וּמְנוּחָה, וְאָז הַלֶּחֶם וְהַיַּיִן שֶׁאוֹכֵל וְשׁוֹתֶה בְּשִׂמְחַת הַלֵּב, בִּגְלַל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה בְּמַעֲשָׂיו.</p>\n<p>אָמַר לוֹ אוֹתוֹ תִּינוֹק, אִם כָּךְ, הֲרֵי אָמַרְתָּ שֶׁכָּל דִּבְרֵי שְׁלֹמֹה הָיוּ בְּחָכְמָה, אֵיפֹה כָּאן הַחָכְמָה? אָמַר לוֹ, בְּנִי, בַּשֵּׁל אֶת בִּשּׁוּלְךְ וְתִרְאֶה אֶת הַפָּסוּק הַזֶּה. אָמַר לוֹ, בְּטֶרֶם בִּשַּׁלְתִּי יָדַעְתִּי. אָמַר לוֹ, מִנַּיִן לְךְ?</p>\n<p>אָמַר לוֹ, קוֹל אֶחָד שָׁמַעְתִּי מֵאָבִי שֶׁהָיָה אוֹמֵר בַּפָּסוּק הַזֶּה, שֶׁשְּׁלֹמֹה מַזְהִיר אֶת הָאָדָם לְעַטֵּר אֶת כְּנֶסֶת יִשְׂרָאֵל בְּשִׂמְחָה, שֶׁהוּא צַד יָמִין, וְהוּא רָצוֹן, וְהוּא לֶחֶם שֶׁיִּתְעַטֵּר בְּחֶדְוָה. וְאַחַר כָּךְ יִתְעַטֵּר בְּיַיִן, שֶׁהוּא שְׂמֹאל, כְּדֵי שֶׁתִּמָּצֵא בָּאֱמוּנָה שֶׁל הַכֹּל חֶדְוָה שְׁלֵמָה, בְּיָמִין וּשְׂמֹאל, וְכַאֲשֶׁר תִּהְיֶה בֵּין שְׁנֵיהֶם, וְאָז כָּל הַבְּרָכוֹת שׁוֹרוֹת בָּעוֹלָם. וְכָל זֶה כְּשֶׁמִּתְרַצֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂי בְּנֵי אָדָם. זֶהוּ שֶׁכָּתוּב כִּי כְבָר רָצָה הָאֱלֹהִים אֶת מַעֲשֶׂיךְ. בָּא רַבִּי חִיָּיא וּנְשָׁקוֹ. אָמַר, חַיֶּיךְ בְּנֵי, דָּבָר זֶה הִשְׁאַרְתִּי בִּשְׁבִילְךְ, וְעַכְשָׁו יָדַעְתִּי שֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְעַטֵּר אוֹתְךְ בַּתּוֹרָה.</p>\n<p>עוֹד פָּתַח רַבִּי חִיָּיא וְאָמַר, אֱמֹר אֶל אַהֲרֹן קַח מַטְּךְ וּנְטֵה יָדְךְ עַל מֵימֵי מִצְרַיִם. מָה הַטַּעַם אַהֲרֹן וְלֹא מֹשֶׁה? אֶלָּא, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַהֲרֹן הַמַּיִם עוֹמְדִים בִּמְקוֹמוֹ, וְהַשְּׂמֹאל רוֹצֶה לְהַשְׁפִּיעַ מַיִם מִשָּׁם. אַהֲרֹן שֶׁבָּא מֵאוֹתוֹ צַד יְעוֹרֵר אוֹתוֹ, וּכְשֶׁשְּׂמֹאל לוֹקֵחַ אוֹתָם, הֵם חוֹזְרִים לִהְיוֹת דָּם.</p>\n<p>בֹּא רְאֵה, הַתַּחְתּוֹן שֶׁבְּכָל הַדְּרָגוֹת הוּא הִכָּה בַּתְּחִלָּה. אָמַר רַבִּי שִׁמְעוֹן, מֵהַתַּחְתּוֹן מַתְחִיל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיָדוֹ מַכָּה בְּכָל אֶצְבַּע וְאֶצְבַּע, וּכְשֶׁמַּגִּיעַ לַדַּרְגָּה הָעֶלְיוֹנָה שֶׁבְּכָל הַדְּרָגוֹת, הוּא עוֹשֶׂה אֶת שֶׁלּוֹ וְעוֹבֵר בְּאֶרֶץ מִצְרַיִם וְהוֹרֵג אֶת הַכֹּל, וּבִגְלַל כָּךְ הָרַג אֶת כָּל הַבְּכוֹרוֹת בְּאֶרֶץ מִצְרַיִם, מִשּׁוּם שֶׁהִיא הַדַּרְגָּה הָעֶלְיוֹנָה וּבְכוֹרַת הַכֹּל.</p>\n<p>וּבֹא רְאֵה, פַּרְעֹה הָיָה שִׁלְטוֹנוֹ בַּמַּיִם, (בראשונה ומהתחתונה התחיל הקדוש ברוך הוא, וכאשר הגיע לדרגתם העליונה, שהיא הבכורה שבדרגות, הרג כל בכור בארץ מצרים, משום שהיא מדרגה עליונה והבכורה של הכל. ובא ראה, פרעה היה בכור, ושלטונו במים) שֶׁכָּתוּב (יחזקאל כט) הַתַּנִּים הַגָּדוֹל הָרֹבֵץ בְּתוֹךְ יְאֹרָיו. מִשּׁוּם כָּךְ הִתְהַפֵּךְ נְהָרוֹ לְדָם בַּתְּחִלָּה. אַחַר כָּךְ הַצְּפַרְדְּעִים שֶׁהָיוּ נוֹגְפִים בָּהֶם בְּקוֹלוֹת, רוֹעֲדִים וּמְקַרְקְרִים בְּתוֹךְ מְעֵיהֶם, (מקרקרים בתוך היאור) וְיוֹצְאִים מִתּוֹךְ הַיְאוֹר וְעוֹלִים לַיַּבָּשָׁה, וּמְרִימִים קוֹלוֹת לְכָל הַצְּדָדִים, עַד שֶׁהֵם נוֹפְלִים כְּמוֹ מֵתִים בְּתוֹךְ הַבַּיִת.</p>\n<p>וְסוֹד הַדָּבָר - כָּל אוֹתָם עֲשָׂרָה אוֹתוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם הָיוּ מִתּוֹךְ הַיָּד הַחֲזָקָה, וְאוֹתָהּ יָד הִתְחַזְּקָה עַל אוֹתָן דְּרָגוֹת כֻּלָּם וְהַשִּׁלְטוֹן שֶׁלָּהֶם כְּדֵי לְבַלְבֵּל אֶת דַּעְתָּם, וְלֹא הָיוּ יוֹדְעִים לַעֲשּׂוֹת דָּבָר. בֹּא רְאֵה, כָּל מַדְרֵגוֹתֵיהֶם, כֵּיוָן שֶׁיּוֹצְאִים לַעֲשׂוֹת דָּבָר, שֶׁהַכֹּל רוֹאִים שֶׁלֹּא יְכוֹלִים (אחר כך) לַעֲשׂוֹת דָּבָר. אֵימָתַי? כַּאֲשֶׁר (בגללאותה) יָד חֲזָקָה (שורה) שֶׁשָּׁרְתָה עֲלֵיהֶם.</p>"],[9522011577,"<p>(שכתוב) וְשָׁרַץ הַיְאֹר צְפַרְדְּעִים וְעָלוּ וּבָאוּ בְּבֵיתֶךְ. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ירמיה לא) קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ וְגוֹ'. בֹּא רְאֵה, הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ בְּכַמָּה מְקוֹמוֹת. וּפָסוּק זֶה קָשֶׁה, רָחֵל מְבַכָּה עַל בָּנֶיהָ - בְּנֵי רָחֵל הָיוּ יוֹסֵף וּבִנְיָמִין וְלֹא יוֹתֵר, וְלֵאָה (כלם) שִׁשָּׁה שְׁבָטִים הָיוּ לָהּ, לָמָּה בָּכְתָה רָחֵל וְלֹא לֵאָה?</p>\n<p>אֶלָּא כָּךְ אָמְרוּ, כָּתוּב (בראשית כט) וְעֵינֵי לֵאָה רַכּוֹת. לָמָּה רַכּוֹת? מִשּׁוּם שֶׁכָּל יוֹם יָצְאָה לְפָרָשַׁת דְּרָכִים וְשָׁאֲלָה עַל עֵשָׂו, וְהָיוּ אוֹמְרִים לָהּ אֶת מַעֲשָׂיו שֶׁל אוֹתוֹ רָשָׁע, וּפָחֲדָה לִפֹּל בְּגוֹרָלוֹ, וְהָיְתָה בּוֹכָה כָּל יוֹם עַד שֶׁהִתְרַכְּכוּ עֵינֶיהָ.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא אָמַר: אַתְּ בָּכִית בִּשְׁבִיל אוֹתוֹ צַדִּיק כְּדֵי שֶׁלֹּא תִהְיִי בְּגוֹרָלוֹ שֶׁל אוֹתוֹ רָשָׁע, חַיָּיִךְ אֲחוֹתֵךְ תַּעֲמֹד בְּפָרָשַׁת דְּרָכִים וְתִבְכֶּה עַל גָּלוּת יִשְׂרָאֵל, וְאַתְּ תַּעַמְדִי בִּפְנִים וְלֹא תִבְכִּי עֲלֵיהֶם, וְרָחֵל הִיא הַבּוֹכָה עַל גָּלוּת יִשְׂרָאֵל.</p>\n<p>אֲבָל פָּסוּק זֶה הוּא עַל מַה שֶּׁאָמַרְנוּ. אֲבָל סוֹד הַדָּבָר, שֶׁרָחֵל וְלֵאָה הֵן שְׁנֵי עוֹלָמוֹת, אֶחָד עוֹלָם הַנִּכְסֶה, וְאֶחָד עוֹלָם הַנִּגְלֶה, וְלָכֵן זוֹ נִקְבְּרָה וְנִסְתַּתְּרָה בְּתוֹךְ הַמְּעָרָה וְנִתְכַּסְּתָה, וְזוֹ עוֹמֶדֶת בְּפָרָשַׁת דְּרָכִים בַּנִּגְלֶה, וְהַכֹּל כַּצּוּרָה הָעֶלְיוֹנָה, וְלָכֵן לֹא הִכְנִיס אוֹתָהּ יַעֲקֹב לַמְּעָרָה וְלֹא בְּמָקוֹם אַחֵר, שֶׁהֲרֵי כָּתוּב (שם מח) בְּעוֹד כִּבְרַת אֶרֶץ לָבֹא אֶפְרָתָה, וְלֹא הִכְנִיס אוֹתָהּ לָעִיר, מִשּׁוּם שֶׁהָיָה יוֹדֵעַ שֶׁמְּקוֹמָה הָיָה בְּמָקוֹם הַנִּגְלֶה.</p>\n<p>בֹּא רְאֵה, כְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת כָּךְ: רָחֵל. כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נג) וּכְרָחֵל לִפְנֵי גוֹזְזֶיהָ נֶאֱלָמָה. לָמָּה נֶאֱלָמָה? שֶׁכְּשֶׁשּׁוֹלְטִים שְׁאָר הָעַמִּים, הַקּוֹל נִפְסָק מִמֶּנָּה וְהִיא נֶאֱלֶמֶת.</p>\n<p>וְזְהִוּ שֶׁכָּתוּב קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים. קוֹל בְּרָמָה נִשְׁמָע - זוֹ יְרוּשָׁלַיִם לְמַעְלָה. רָחֵל מְבַכָּה עַל בָּנֶיהָ - כָּל זְמַן שֶׁיִּשְׂרָאֵל הֵם בַּגָּלוּת, הִיא מְבַכָּה עֲלֵיהֶם שֶׁהִיא הָאֵם שֶׁלָּהֶם. מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ, מָה הַטַּעַם? כִּי אֵינֶנּוּ. כִּי אֵינָם הָיָה צָרִיךְ (לכתב) ! אֶלָּא מִשּׁוּם שֶׁבַּעְלָהּ הוּא קוֹל, הִסְתַּלֵּק מִמֶּנָּה וְלֹא הִתְחַבֵּר עִמָּה.</p>\n<p>וּבֹא רְאֵה, לֹא שָׁעָה אַחַת הִיא בּוֹכָה עַל יִשְׂרָאֵל, אֶלָּא בְּכָל זְמַן וּזְמַן שֶׁהֵם בַּגָּלוּת, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא גָּרַם לַמִּצְרִיִּים קוֹל, שֶׁכָּתוּב (שמות יא) וְהָיְתָה צְעָקָה גְדֹלָה בְּכָל אֶרֶץ מִצְרָיִם אֲשֶׁר כָּמֹהוּ לֹא נִהְיָתָה וְגוֹ'. וְהִזְמִין לָהֶם קוֹלוֹת אֲחֵרִים בְּאוֹתָם הַצְּפַרְדְּעִים שֶׁהֵרִימוּ קוֹלוֹת בִּמְעֵיהֶם, וְהָיוּ נוֹפְלִים בַּשְּׁוָקִים כְּמוֹ מֵתִים.</p>\n<p>וַתַּעַל הַצְּפַרְדֵּעַ. הָיְתָה אַחַת וְהוֹלִידָה, וְהִתְמַלְּאָה הָאָרֶץ מֵהֶם. וְהָיוּ כֻלָּן מוֹסְרוֹת עַצְמָן לָאֵשׁ, שֶׁכָּתוּב וּבְתַנּוּרֶיךְ וּבְמִשְׁאֲרוֹתֶיךְ. וּמָה הָיוּ אוֹמְרוֹת? (תהלים סו) בָּאנוּ בָּאֵשׁ וּבַמַּיִם וַתּוֹצִיאֵנוּ לָרְוָיָה. וְאִם תֹּאמַר, אִם כָּךְ מָה אִכְפַּת לְמִצְרַיִם שֶׁכָּל אוֹתָן הַצְּפַרְדְּעִים נִכְנָסוֹת לָאֵשׁ? אֶלָּא כֻלָּן נִכְנָסוֹת לָאֵשׁ וְהוֹלְכוֹת בַּתַּנּוּר וְלֹא מֵתוֹת. וְאוֹתָן שֶׁמֵּתוֹת מֶה עָשׂוּ? לֶחֶם הָיָה בַּתַּנּוּר, וְנִכְנָסוֹת לְתוֹךְ הַלֶּחֶם וּמִתְבַּקְּעוֹת, וְיוֹצְאוֹת מֵהֶן אֲחֵרוֹת וְנִשְׁאָבוֹת לְתוֹךְ הַלֶּחֶם. בָּאוּ לֶאֱכֹל מִמֶּנּוּ, אוֹתָהּ פַּת הָפְכָה לִצְפַרְדֵּעַ בִּמְעֵיהֶם וְרוֹקְדוֹת, וּמְרִימוֹת קוֹלוֹת עַד שֶׁהָיוּ מֵתִים, וְזֶה קָשֶׁה לָהֶם מֵהַכֹּל. בֹּא רְאֵה, כָּתוּב וְשָׁרַץ הַיְאֹר צְפַרְדְּעִים וְעָלוּ וּבָאוּ בְּבֵיתֶךְ וּבַחֲדַר מִשְׁכָּבְךְ וְעַל מִטָּתֶךְ. פַּרְעֹה לָקָה רִאשׁוֹן מִכֻּלָּם, וְיוֹתֵר מִכֻּלָּם, כְּדֵי שֶׁיִּהְיֶה שֵׁם הָאֱלוֹהַּ מְבֹרָךְ מִן הָעוֹלָם וְעַד הָעוֹלָם, שֶׁהוּא פּוֹקֵד מַעֲשֵׂי בְּנֵי אָדָם בְּכָל מַה שֶּׁעוֹשִׂים.</p>\n<p>כָּתוּב (בראשיתיב) וַיִּרְאוּ אֹתָהּ שָׂרֵי פַרְעֹה וַיְהַלֲלוּ אֹתָהּ אֶל פַּרְעֹה וַתֻּקַּח הָאִשָּׁה בֵּית פַּרְעֹה. פָּסוּק זֶה לִדְרָשָׁה הוּא בָּא. שְׁלֹשָׁה פַרְעֹה כָּאן. אֶחָד בְּאוֹתוֹ זְמַן, וְאֶחָד בִּימֵי יוֹסֵף, וְאֶחָד בִּימֵי מֹשֶׁה שֶׁהִלְקָהוּ בְּמַקְלוֹ. (הפסוק הזה כלו התקים בפרעה הראשון, אבל בשעה וכו') (והפסוק הזה התקים).</p>\n<p>פַּרְעֹה הָרִאשׁוֹן, בְּשָׁעָה שֶׁנִּלְקְחָה שָׂרָה אֵלָיו, רָמַז לְאָמָּנִים וְצִיְּרוּ בְּחַדְרוֹ אֶת דְּמוּתָהּ עַל מִטָּתוֹ בַּכֹּתֶל. לֹא נָחָה דַעְתּוֹ עַד שֶׁעָשׂוּ אֶת דְּמוּתָהּ שֶׁל שָׂרָה עַל לוּחַ עֵץ, וּכְשֶׁהָיָה עוֹלֶה לְמִטָּתוֹ, הֶעֱלָה אוֹתָהּ עִמּוֹ. כָּל מֶלֶךְ שֶׁבָּא אַחֲרָיו הָיָה רוֹאֶה אוֹתוֹ דְיוֹקָן מְצֻיָּר בְּצִיּוּר, וְהָיוּ נִכְנָסִים לְפָנָיו בַּדְּחָנִים, וּכְשֶׁעוֹלֶה לְמִטָּתוֹ הָיָה נֶהֱנֶה מֵאוֹתוֹ צִיּוּר, לָכֵן הַמֶּלֶךְ לָקָה כָּאן יוֹתֵר מֵהַכֹּל. (בא וראה) הַיְנוּ מַה שֶּׁכָּתוּב וּבַחֲדַר מִשְׁכָּבְךְ וְעַל מִטָּתֶךְ, וְאַחַר כָּךְ וּבְבֵית עֲבָדֶיךְ וּבְעַמֶּךְ. וּבְכֻלָּם לֹא כָתוּב עַל מִטָּתָם, אֶלָּא רַק לוֹ לְבַדּוֹ.</p>\n<p>רַבִּי אַבָּא פָּתַח, (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא אֶל מָקוֹם שֶׁהַנְּחָלִים הֹלְכִים שָׁם הֵם שָׁבִים לָלֶכֶת. פָּסוּק זֶה נֶאֱמַר וְאָמְרוּ אוֹתוֹ הַחֲבֵרִים, אֲבָל בֹּא רְאֵה, כְּשֶׁאוֹתָם נְחָלִים נִכְנָסִים לְתוֹךְ הַיָּם, וְהַיָּם לוֹקֵחַ אוֹתָם וְשׁוֹאֵב אוֹתָם לְתוֹכוֹ בִּשְׁבִיל שֶׁקּוֹפְאִים הַמַּיִם בְּתוֹךְ הַיָּם, וְאוֹתוֹ הַקֶּרַח שׁוֹאֵב אֶת הַמַּיִם שֶׁנִּכְנָס בּוֹ, וְאַחַר כָּךְ יוֹצְאִים הַמַּיִם בְּתֹקֶף שֶׁל הַדָּרוֹם, וּמַשְׁקֶה אֶת כָּל חַיּוֹת הַשָּׂדֶה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי.</p>\n<p>וּבֹא רְאֵה, יָם שֶׁקּוֹפֵא שׁוֹאֵב אֶת כָּל הַמַּיִם וּמַפְשִׁיר בְּכֹחַ הַדָּרוֹם כְּמוֹ שֶׁנִּתְבָּאֵר, וּמִשּׁוּם כָּךְ אֵינֶנּוּ מָלֵא, וְנֶאֱמַר.</p>\n<p>וַהֲרֵי הִתְעוֹרְרוּ בוֹ הַחֲבֵרִים, אֶל מָקוֹם שֶׁהַנְּחָלִים הֹלְכִים שָׁם הֵם שָׁבִים לָלֶכֶת. מָה הַטַּעַם הֵם שָׁבִים? מִשּׁוּם שֶׁאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן לֹא פוֹסֵק לְעוֹלָמִים, וְהוּא מוֹצִיא תָּמִיד מַיִם לַיָּם, וְעַל זֶה הַמַּיִם שָׁבִים לָלֶכֶת, וְשָׁבִים, וְהוֹלְכִים וְשָׁבִים, וְלֹא פוֹסְקִים לְעוֹלָמִים. וּכְשֶׁהוּא שָׁב לָלֶכֶת, כְּדֵי לָלֶכֶת לְהַשְׁקוֹת אֶת הַכֹּל, וּבָאָה רוּחַ צָפוֹן וְהַמַּיִם קוֹפְאִים, וְרוּחַ הַדָּרוֹם שֶׁהִיא חֲמִימָה, (מפשירה) מַטִּילָה אוֹתָם לָלֶכֶת לְכָל צַד. וְעַל זֶה הַיָּם הַזֶּה יוֹשֵׁב בֵּין שְׁנֵי הַצְּדָדִים הַלָּלוּ, וּבִשְׁבִילָם הוּא עוֹמֵד, וָאֳנִיּוֹת הוֹלְכוֹת וְנוֹסְעוֹת לְכָל צַד.</p>\n<p>בֹּא רְאֵה, כְּשֶׁהַמֶּלֶךְ בָּא לְמִטָּתוֹ בְּשָׁעָה שֶׁנֶּחֱלָק הַלַּיְלָה, רוּחַ צָפוֹן מִתְעוֹרֶרֶת, שֶׁהִיא מְעוֹרֶרֶת חֲבִיבוּת לַגְּבִירָה, שֶׁאִלְמָלֵא רוּחַ הַצָּפוֹן אֵין מִתְחַבֵּר הַמֶּלֶךְ עִמָּהּ, מִשּׁוּם שֶׁמִּצָּפוֹן מַתְחִילָה חֲבִיבוּת, כְּמוֹ שֶׁנֶּאֱמַר (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְדָרוֹם מְחַבֵּק בְּאַהֲבָה, שֶׁכָּתוּב וִימִינוֹ תְּחַבְּקֵנִי. וְאָז כַּמָּה בַּדְּחָנִים מְעוֹרְרִים שִׁירָה עַד שֶׁבָּא הַבֹּקֶר, שֶׁכָּתוּב (איוב לח) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים.</p>\n<p>וּכְשֶׁבָּא הַבֹּקֶר, כָּל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים אוֹמְרִים שִׁירָה, וְיִשְׂרָאֵל כְּמוֹ כֵן לְמַטָּה, שֶׁכָּתוּב (ישעיהסב) הַמַּזְכִּירִים אֶת ה' אַל דֳּמִי לָכֶם. אַל דֳּמִי לָכֶם לְמַטָּה דַּוְקָא (בלילה).</p>\n<p>כְּשֶׁנֶּחֱלָק הַלַּיְלָה, אוֹתָם שֶׁתְּשׁוּקָתָם לְהַזְכִּיר תָּמִיד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא נוֹתְנִים שֵׁנָה לַלֵּב, וְעוֹמְדִים לְהַזְכִּיר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. כְּשֶׁעוֹלֶה הַבֹּקֶר, מַקְדִּימִים לְבֵית הַכְּנֶסֶת וּמְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֵן אַחַר חֲצוֹת הַיּוֹם, וְכֵן בַּלַּיְלָה כְּשֶׁנֶּחְשָׁךְ וְנִדְבָּק הַלַּיְלָה בַּחֹשֶׁךְ וְלָן הַשֶּׁמֶשׁ, וְעַל אֵלֶּה כָּתוּב הַמַּזְכִּירִים אֶת ה' אַל דֳּמִי לָכֶם. וִזֶה עַם יִשְׂרָאֵל הַקָּדוֹשׁ.</p>\n<p>וְלָכֵןֹ הִזְכִּירָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם וְעָלָה עַל פַּרְעֹה, אֵלּוּ שֶׁלֹּא שׁוֹכְכִים יוֹמָם וָלַיְלָה, וּמִי הֵם? צְפַרְדְּעִים, שֶׁקּוֹלָם לֹא שׁוֹכֵךְ תָּמִיד, מִשּׁוּם שֶׁהֶחֱזִיק בָּעָם הַקָּדוֹשׁ שֶׁלֹּא שׁוֹכְכִים יָמִים וְלֵילוֹת לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא הָיָה אִישׁ בְּמִצְרַיִם שֶׁיָּכֹל לְדַבֵּר זֶה עִם זֶה, וּמֵהֶם נִשְׁחֲתָה הָאָרֶץ, וּמִקּוֹלָם הָיוּ יוֹנְקִים וִילָדִים קְטַנִּים מֵתִים.</p>\n<p>וְאִם תֹּאמַר, אֵיךְ לֹא יָכְלוּ לַהֲרֹג אוֹתָם? אֶלָּא אִם הֵרִים אָדָם מַקֵּל אוֹ אֶבֶן לַהֲרֹג אַחַת, הִתְבַּקְּעָה וְיָצְאוּ מִמֶּנָּה שֵׁשׁ מִתּוֹךְ מֵעֶיהָ, וְהוֹלְכוֹת וּמְקַלְקְלוֹת אֶת הָאָרֶץ עַד שֶׁהָיָה מֵהַנִּמְנָע לִקְרַב אֲלֵיהֶם.</p>\n<p>בֹּא וּרְאֶה כַּמָּה נְהָרוֹת, כַּמָּה יְאוֹרִים יוֹצְאִים מִתּוֹךְ הַיָּם הָעֶלְיוֹן, כְּשֶׁנִּמְשָׁכִים וּמַפְשִׁירִים הַמַּיִם וּמִתְחַלְּקִים כַּמָּה נְחָלִים לְכַמָּה צְדָדִים, לְכַמָּה יְאוֹרִים, לְכַמָּה נְהָרוֹת. הַחֵלֶק שֶׁל הַמְמֻנֶּה שֶׁל צַד מִצְרַיִם הֵם הַמַּיִם הַמְרַחֲשִׁים הָאֵלֶּה, שֶׁאֵין לְךְ מַיִם שֶׁיּוֹצְאִים מִתּוֹךְ הַיָּם שֶׁלֹּא מוֹצִיאִים דָּגִים לְמִינֵיהֶם.</p>\n<p>מִי הֵם הַדָּגִים? אוֹתָם שְׁלִיחִים בָּעוֹלָם מְמֻנִּים לַעֲשׂוֹת אֶת רְצוֹן אֲדוֹנָם, מְמֻנִּים בְּרוּחַ שֶׁל חָכְמָה. וְעַל זֶה שָׁנִינוּ, יֵשׁ מַיִם מְגַדְּלִים חֲכָמִים, וְיֵשׁ מַיִם מְגַדְּלִים טִפְּשִׁים, לְפִי אוֹתָם נְהָרוֹת שֶׁמִּתְחַלְּקִים לְכָל הַצְּדָדִים.</p>\n<p>וְכָאן נַהֲרוֹת מִצְרַיִם מְגַדְּלִים בַּעֲלֵי כְשָׁפִים, דָּגִים בְּסוּגִים שׁוֹנִים, בְּעֶשֶׂר דְּרָגוֹת שֶׁל כְּשָׁפִים, שֶׁכָּתוּב (דברים יח) קוֹסֵם, קְסָמִים, מְעוֹנֵן, וּמְנַחֵשׁ, וּמְכַשֵּׁף, וְחוֹבֵר, חָבֶר, וְשׁוֹאֵל אוֹב, וְיִדְּעוֹנִי, וְדוֹרֵשׁ אֶל הַמֵּתִים. הֲרֵי עֲשָׂרָה מִינִים שֶׁל חָכְמַת הַמְּכַשְּׁפִים.</p>\n<p>וּבְאוֹתוֹ זְמַן הוֹשִׁיט הַקָּדוֹשׁ בָּרוּךְ הוּא אֶצְבַּע שֶׁלּוֹ וּבִלְבֵּל אוֹתָם נְחָלִים וּנְהָרוֹת שֶׁל מִצְרַיִם, וְנִמְנְעוּ אוֹתָם הַדָּגִים שֶׁל הַחָכְמָה שֶׁלָּהֶם. אֶחָד הִתְהַפֵּךְ לְדָם, וְאֶחָד שֶׁהֶעֱלוּ הַדָּגִים קוֹלוֹת (שכל הדגים תלויים) בְּלִי תוֹעֶלֶת, וְלֹא בָאָה עֲלֵיהֶם רוּחַ שֶׁל אוֹתָן חָכְמוֹת.</p>\n<p>עָרֹב - כְּאוֹתָהּ דֻּגְמָא, שֶׁעִרְבֵּב לָהֶם מִינֵי חָכְמָה שֶׁלָּהֶם, וְלֹא יָכְל לְהִדָּבֵק, וְלֹא עוֹד, אֶלָּא אֲפִלּוּ שֶׁאֵלֶּה שֶׁנִּמְצְאוּ בָּאָרֶץ, מַשְׁחִיתִים אוֹתָם בָּאָרֶץ וּמַשְׁחִיתִים אֶת דַּרְכֵיהֶם. עָרֹב, מַה זֶּה עָרֹב? עִרְבּוּבְיָא, כְּמוֹ שֶׁנֶּאֱמַר וּבֶגֶד כִּלְאַיִם. עֵרוּבִין - (ויקראיט) שָׂדְךְ לֹא תִזְרַע כִּלְאָיִם. מִינִים רַבִּים בַּהֲרָמַת יָד.</p>\n<p>בֹּא רְאֵה כַּמָּה כֹּחוֹת הִתְעוֹרְרוּ לְמַעְלָה כְאֶחָד, וּבִלְבֵּל אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאֶחָד כְּדֵי לְבַלְבֵּל אֶת הַכֹּחַ הַתַּקִּיף שֶׁלָּהֶם לְמַעְלָה. וְכָל אוֹתָן גְּבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, בְּיָד אַחַת זֶה הָיָה, שֶׁהֵרִים יָדוֹ עֲלֵיהֶם לְמַעְלָה וּלְמַטָּה, וּמִשָּׁם אָבְדָה חָכְמַת מִצְרַיִם, שֶׁכָּתוּב (ישעיה כט) וְאָבְדָה חָכְמַת חֲכָמָיו וּבִינַת נְבֹנָיו תִּסְתַּתָּר.</p>\n<p>וּבֹא רְאֵה, כָּתוּב (שם יט) וְסִכְסַכְתִּי מִצְרַיִם בְּמִצְרַיִם. מִצְרַיִם - לְמַעְלָה, בְּמִצְרַיִם - לְמַטָּה. מִשּׁוּם שֶׁאוֹתָם חֲיָלוֹת לְמַעְלָה מְמֻנִּים עַל הַחֲיָלוֹת שֶׁל מַטָּה, וְהִתְעָרְבוּ כֻלָּם. הִתְעָרְבוּ לְמַעְלָה, שֶׁלֹּא הָיוּ הַמִּצְרִים יְכוֹלִים לְהִתְקַשֵּׁר לְכִשְׁפֵיהֶם, בְּאוֹתָם מְקוֹמוֹת שֶׁהָיוּ מִתְקַשְּׁרִים בַּהַתְחָלָה, שֶׁהֲרֵי הִתְבַּלְבְּלוּ, וְעַל זֶה הֵבִיא עֲלֵיהֶם עָרֹב, חַיּוֹת שֶׁהָיוּ מְעֹרָבוֹת זֶה בָּזֶה.</p>\n<p>כִּנִּים - שֶׁעָלָה עֲפַר הָאָרֶץ. וּבֹא רְאֵה, כָּל פְּרִי שֶׁנּוֹלָד בָּאָרֶץ, מֵחַיִל שֶׁלְּמַעְלָה מְמֻנֶּה שֶׁנִּזְרַע עָלֶיהָ הוּא, וְהַכֹּל הָיָה כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>וּבֹא רְאֵה, שִׁבְעָה רְקִיעִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ זֶה שֶׁבַע אֲרָצוֹת. וְאוֹתָם תְּחוּמִים שֶׁנִּפְרָדִים בִּמְקוֹמָם. שִׁבְעָה רְקִיעִים לְמַעְלָה, שִׁבְעָה תְחוּמֵי אֶרֶץ לְמַעְלָה, כְּמוֹ כֵן לְמַטָּה נִפְרָדוֹת הַדְּרָגוֹת, שִׁבְעָה רְקִיעִים, וְשִׁבְעָה תְחוּמֵי אֶרֶץ. וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, בְּשֶׁבַע אֲרָצוֹת כְּגִלְדֵי בְצָלִים זֶה עַל זֶה.</p>\n<p>וְאוֹתָם שִׁבְעָה תְחוּמִים שֶׁל הָאָרֶץ לְמַעְלָה, כָּל אֶחָד וְאֶחָד (נפרדים לשבעים ממגים) נִפְרָדִים לַעֲשָׂרָה, וְהֵם מִתְחַלְּקִים לְשִׁבְעִים מְמֻנִּים שֶׁמְּמֻנִּים עַל שִׁבְעִים עַמִּים, וְאוֹתָהּ אֶרֶץ תְּחוּם לְכָל עַם וְעַם סְבִיב הָאָרֶץ הַקְּדוֹשָׁה שֶׁל יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ מִגִּבּוֹרֵי יִשְׂרָאֵל. וַעֲשָׂרָה בְּתוֹכָם טְמוּנִים, וְהֵם שִׁבְעִים שֶׁסּוֹבְבִים אֶת הָאָרֶץ הַקְּדוֹשָׁה, וְזֶהוּ לְמַעְלָה כְּמוֹ זֶה לְמַטָּה.</p>\n<p>וּבֹא רְאֵה, אוֹתָהּ אֶרֶץ הַתְּחוּם שֶׁל חֵלֶק מִצְרַיִם, בְּאוֹתוֹ זְמַן הוֹשִׁיט הַקָּדוֹשׁ בָּרוּךְ הוּא אֶצְבָּעוֹ, וְנוֹלְדוֹ לַהֲבוֹת אֵשׁ בְּאוֹתוֹ תְחוּם, וְהִתְיַבְּשׁוּ כָּל אוֹתָם תְּחוּמִים שֶׁמְּרֻכָּכִים בְּמַיִם. וְכָל הַיָּרֹק שֶׁל הַמַּיִם שֶׁנּוֹבְעִים אָז לְמַטָּה, נִרְאוּ הַכִּנִּים מֵעֲפַר הָאָרֶץ.</p>\n<p>וַהֲרֵי נֶאֱמַר שֶׁאַהֲרֹן הָיָה מַכֶּה, אֲבָל מִשּׁוּם זֶה אַהֲרֹן הָיָה מַכֶּה, לְהַרְאוֹת שֶׁיְּמִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹבֶרֶת שׂוֹנְאִים, כְּמוֹ שֶׁנֶּאֱמַר (שמותטו) יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. כְּמוֹ זֶה עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָבִיא עַל הָעִיר רוֹמָא רַבָּתִי, שֶׁכָּתוּב (ישעיה לד) וְנֶהֶפְכוּ נְחָלֶיהָ לְזֶפֶת וַעֲפָרָהּ לְגָפְרִית. וְעַל זֶה, כָּל עֲפַר הָאָרֶץ הָיָה כִנִּים בְּכָל אֶרֶץ מִצְרָיִם.</p>"],[9522011578,"<p>רַבִּי יְהוּדָה וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי חִיָּיא, כְּשֶׁחֲבֵרִים הוֹלְכִים בַּדֶּרֶךְ, צְרִיכִים לָלֶכֶת בְּלֵב אֶחָד, וְאִם נִפְגְּשׁוּ אוֹ שֶׁהוֹלְכִים עִמָּם הָרְשָׁעִים שֶׁל הָעוֹלָם, אוֹ בְּנֵי אָדָם שֶׁאֵינָם מֵהֵיכַל הַמֶּלֶךְ, צְרִיכִים לְהִפָּרֵד מֵהֶם. מִנַּיִן לָנוּ? מִכָּלֵב, שֶׁכָּתוּב (במדבר יד) וְעַבְדִּי כָלֵב עֵקֶב הָיְתָה רוּחַ אַחֶרֶת עִמּוֹ וַיְמַלֵּא אַחֲרָי. מַה זֶּה רוּחַ אַחֶרֶת? שֶׁנִּפְרַד מֵאוֹתָם מְרַגְּלִים, שֶׁכָּתוּב (שם יג) וַיַּעֲלוּ בַנֶּגֶב וַיָּבֹא עַד חֶבְרוֹן. שֶׁנִּפְרַד מֵאוֹתָם מְרַגְּלִים וּבָא לְבַדּוֹ לְחֶבְרוֹן לְהִשְׁתַּטֵּחַ עַל קִבְרֵי הָאָבוֹת.</p>\n<p>וְחֶבְרוֹן נִתְּנָה לוֹ חֵלֶק יְרֻשָּׁה לְהַחֲזִיק בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (דברים א) וְלוֹ אֶתֵּן אֶת הָאָרֶץ אֲשֶׁר דָּרַךְ בָּהּ. לָמָּה נָתְנוּ לוֹ אֶת חֶבְרוֹן? אִם מִשּׁוּם שֶׁהִשְׁתַּטַּח בְּקִבְרֵי הָאָבוֹת לְהִנָּצֵל מֵאוֹתָהּ עֵצָה שֶׁלָּהֶם שֶׁנִּצַּל - לֹא!</p>\n<p>אֶלָּא, סוֹד הַדָּבָר שָׁמַעְתִּי, כְּמוֹ זֶה כָּתוּב (שמואל א ב) וַיִּשְׁאַל דָּוִד בַּה' לֵאמֹר הַאֶעֱלֶה בְּאַחַת עָרֵי יְהוּדָה וַיֹּאמֶר ה' אֵלָיו עֲלֵה וַיֹּאמֶר דָּוִד אָנָה אֶעֱלֶה וַיֹּאמֶר חֶבְרֹנָה. כָּאן יֵשׁ לְהִסְתַּכֵּל, כֵּיוָן שֶׁהֲרֵי מֵת שָׁאוּל, וְדָוִד נִמְשַׁח בִּימֵי שָׁאוּל לְקַבֵל מַלְכוּת, כֵּיוָן שֶׁמֵּת שָׁאוּל לָמָּה לֹא הִמְלִיכוּ אֶת דָּוִד וְלֹא קִבֵּל מַלְכוּת עַל כָּל יִשְׂרָאֵל, וּבָא לְחֶבְרוֹן וְקִבֵּל מַלְכוּת עַל יְהוּדָה לְבַדָּהּ שֶׁבַע שָׁנִים, וְהִתְעַכֵּב שָׁם כָּל שֶׁבַע הַשָּׁנִים הַלָּלוּ, וְאַחַר שֶׁמֵּת אִישׁ בֹּשֶׁת קִבֵּל מַלְכוּת עַל כָּל יִשְׂרָאֵל בִּירוּשָׁלַיִם?</p>\n<p>אֶלָּא הַכֹּל הוּא סוֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. בּא רְאֵה, הַמַּלְכוּת הַקְּדוֹשָׁה לֹא קִבְּלָה מַלְכוּת שְׁלֵמָה עַד שֶׁהִתְחַבְּרָה בָּאָבוֹת, וּכְשֶׁהִתְחַבְּרָה בָהֶם, נִבְנָה בִּנְיָן שָׁלֵם מֵעוֹלָם הָעֶלְיוֹן, וְהָעוֹלָם הָעֶלְיוֹן נִקְרָא שֵׁבַע שָׁנִים, מִשּׁוּם שֶׁכֻּלָּם בּוֹ.</p>\n<p>וְסִימָנְךָֹ - (מלכים א ו) וַיִּבְנֵהוּ שֶׁבַע שָׁנִים. זֶהוּ הָעוֹלָם הָעֶלְיוֹן. וְלֹא כָתוּב וַיִּבְנֵהוּ בְּשֶׁבַע שָׁנִים, כְּמוֹ שֶׁנֶּאֱמַר (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. מִי אֵלּוּ שֵׁשֶׁת הַיָּמִים? זֶה אַבְרָהָם, שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּאַבְרָהָם. וְאַבְרָהָם נִקְרָא שֵׁשֶׁת יָמִים, וּמִשּׁוּם (ובו) שֶׁהוּא שֵׁשֶׁת יָמִים, נִבְנָה הָעוֹלָם בְּאוֹתוֹ (בזה) גָוֶן, וַיִּבְנֵהוּ שֶׁבַע שָׁנִים.</p>\n<p>וּבֹא רְאֵה, דָּוִד רָצָה לְהִבָּנוֹת בְּמַלְכוּת שְׁלֵמָה לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, וְלֹא נִבְנָה עַד שֶׁבָּא וְהִתְחַבֵּר בָּאָבוֹת, וְעָמַד שֶׁבַע שָׁנִים לְהִבָּנוֹת בְּתוֹכָם. אַחַר שֶׁבַע שָׁנִים נִבְנָה בַּכֹּל, נִמְשְׁכָה מַלְכוּתוֹ שֶׁלֹּא תַעֲבֹר לְעוֹלָמִים. וְאִם לֹא שֶׁנַּעֲשָׂה בְּחֶבְרוֹן לְהִתְחַבֵּר בִּמְקוֹמוֹ, לֹא נִבְנְתָה מַלְכוּתוֹ לְהִמָּשֵׁךְ כָּרָאוּי. כְּמוֹ כֵן כָּלֵב, הֵאִירָה בּוֹ רוּחַ חָכְמָה, וּבָא לְחֶבְרוֹן לְהִתְחַבֵּר בָּאָבוֹת וְלִמְקוֹמוֹ הָלַךְ. אַחַר כָּךְ מְקוֹמוֹ הָיָה, וְיָרַשׁ אוֹתוֹ.</p>"],[9522011579,"<p>רַבִּי יֵיסָא וְרַבִּי חִזְקִיָּה הָיוּ הוֹלְכִים מִקַּפּוֹטְקִיָּא לְלוֹד, וְהָיָה עִמָּהֶם יְהוּדִי אֶחָד עִם מַשָּׂא שֶׁל עוֹפוֹת (שגקראים קטפירא) עַל חֲמוֹר. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי יֵיסָא לְרַבִּי חִזְקִיָּה, פְּתַח פִּיךְ וֶאֱמֹר דָּבָר אֶחָד מֵאוֹתָם דִּבְרֵי הַתּוֹרָה הַמְעֻלִּים שֶׁאַתָּה אוֹמֵר לִפְנֵי הַמְּנוֹרָה הַקְּדוֹשָׁה.</p>\n<p>פָּתַח וְאָמַר, (משלי ג) דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. דְּרָכֶיהָ דַּרְכֵי נֹעַם - אֵלּוּ דַּרְכֵי הַתּוֹרָה, שֶׁמִּי שֶׁהוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁרֶה עָלָיו נֹעַם הַשְּׁכִינָה שֶׁלֹּא תָזוּז מִמֶּנּוּ לְעוֹלָמִים. וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם - שֶׁכָּל שְׁבִילֵי הַתּוֹרָה כֻּלָּם שָׁלוֹם. שָׁלוֹם לוֹ לְמַעְלָה, שָׁלוֹם לוֹ לְמַטָּה. שָׁלוֹם לוֹ בָּעוֹלָם הַזֶּה, שָׁלוֹם לוֹ בָּעוֹלָם הַבָּא.</p>\n<p>אָמַר אוֹתוֹ יְהוּדִי, מַטְבֵּעַ בְּכִיס בְּפָסוּק זֶה נִמְצָא. אָמַר לוֹ, מִנַּיִן לְךְ? אָמַר לוֹ, שָׁמַעְתִּי מֵאָבִי, וְלָמַדְתִּי כָּאן בַּפָּסוּק הַזֶּה דָּבָר טוֹב.</p>\n<p>פָּתַח וְאָמַר, פָּסוּק זֶה הוּא בִּשְׁתֵּי צוּרוֹת וּבִשְׁנֵי צְדָדִים. קוֹרְאִים בּוֹ דְּרָכִים, וְקוֹרְאִים בּוֹ נְתִיבוֹת. קוֹרְאִים בּוֹ נֹעַם, וְקוֹרְאִים בּוֹ שָׁלוֹם. מַה זֶּה דְּרָכִים, וּמַה זֶּה נְתִיבוֹת? מַה זֶּה נֹעַם, וּמַה זֶּה שָׁלוֹם?</p>\n<p>אֶלָּא דְּרָכֶיהָ דַּרְכֵי נֹעַם, הַיְנוּ שֶׁכָּתוּב (ישעיה נג) הַנּוֹתֵן בַּיָּם דָּרֶךְ. שֶׁהֲרֵי כָּל מָקוֹם שֶׁנִּקְרָא בַּתּוֹרָה דֶּרֶךְ, הִיא דֶרֶךְ פְּתוּחָה לַכֹּל, כְּמוֹ זֶה זוֹ שֶׁפְּתוּחָה לְכָל אָדָם - כָּךְ דְּרָכֶיהָ. אֵלּוּ דְרָכִים שֶׁפְּתוּחִים מֵהָאָבוֹת, שֶׁכָּרוּ בַּיָּם הַגָּדוֹל וְנִכְנָסִים לְתוֹכוֹ. וְאוֹתָם דְּרָכִים נִפְתָּחוֹת לְכָל עֵבֶר וּלְכָל צִדְדֵי הָעוֹלָם.</p>\n<p>וְנֹעַם זֶה הוּא נְעִימוּת שֶׁיּוֹצֵאת מִן הָעוֹלָם הַבָּא, (ומהעולם הבא מאירות כל המנורות) וּמְאִירָה אֶת כָּל הַמְּנוֹרוֹת, וְנִפְרָדִים (האורות) לְכָל עֵבֶר. וְאוֹתוֹ טוּב וְאוֹר שֶׁל הָעוֹלָם הַבָּא שֶׁיּוֹנְקִים הָאָבוֹת נִקְרָא נֹעַם. דָּבָר אַחֵר, הָעוֹלָם הַבָּא נִקְרָא נֹעַם. וּכְשֶׁמִּתְעוֹרֵר הָעוֹלָם הַבָּא, אָז כָּל הַטּוּב וְכָל הַשִּׂמְחָה וְכָל הָאוֹרוֹת וְכָל הַחֵרוּת שֶׁל הָעוֹלָם מִתְעוֹרְרִים, וְלָכֵן נִקְרָא נֹעַם.</p>\n<p>וְעַל זֶה שָׁנִינוּ, רִשְׁעֵי הַגֵּיהִנֹּם, בְּשָׁעָה שֶׁנִּכְנֶסֶת שַׁבָּת, כֻּלָּם נָחִים, וְיֵשׁ לָהֶם (חרות) שִׂמְחָה וּמְנוּחָה בְּשַׁבָּת. וְכֵיוָן שֶׁיּוֹצֵאת שַׁבָּת, יֵשׁ לָנוּ לְעוֹרֵר שִׂמְחָה עֶלְיוֹנָה עָלֵינוּ כְּדֵי שֶׁנִּנָּצֵל מֵאוֹתוֹ הָעֹנֶשׁ שֶׁל הָרְשָׁעִים שֶׁנִּדּוֹנִים מֵאוֹתָהּ שָׁעָה וָהָלְאָה, וְיֵשׁ לָנוּ לְהִתְעוֹרֵר וְלוֹמַר, (תהלים צ) וִיהִי נֹעַם ה' אֱלֹהֵינוּ עָלֵינוּ. זֶהוּ נֹעַם עֶלְיוֹן, (חרות) שִׂמְחַת הַכֹּל. וְעַל זֶה, דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם.</p>\n<p>מַה זֶּה נְתִיבוֹתֶיהָ? אֵלּוּ אוֹתָם נְתִיבוֹת וּשְׁבִילִים שֶׁיּוֹצְאִים מִלְּמַעְלָה, וְכֻלָּם לוֹקֵחַ אוֹתָם בְּרִית הַיְחִידִי שֶׁנִּקְרָא שָׁלוֹם, שְׁלוֹם הַבַּיִת, וּמַכְנִיס אוֹתָם לַיָּם הַגָּדוֹל. כְּשֶׁהוּא בְּתָקְפּוֹ, וְאָז נוֹתֵן בּוֹ שָׁלוֹם. זֶהוּ שֶׁכָּתוּב וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. בָּאוּ רַבִּי יֵיסָא וְרַבִּי חִזְקִיָּה וְנָשְׁקוּ לוֹ. אָמְרוּ, וּמַה כָּל הַדְּבָרִים הָעֶלְיוֹנִים הַלָּלוּ טְמוּנִים אֶצְלְךְ וְלֹא יָדַעְנוּ?! הָלְכוּ. כְּשֶׁהִגִּיעוּ לְבֵית שָׂדֶה, רָאוּ בְּהֵמוֹת שֶׁל הַשָּׂדֶה מֵתִים. אָמְרוּ, וַדַּאי דָּבָר שֶׁל בְּהֵמוֹת יֵשׁ בְּמָקוֹם זֶה.</p>"],[9522011580,"<p>אָמַר אוֹתוֹ יְהוּדִי, זֶה שֶׁאֲמַרְתֶּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָרַג בְּמִצְרַיִם כָּל אוֹתָם הַצּאן, כָּל אוֹתָם בְּהֵמוֹת. שְׁלֹשָׁה סוּגֵי מָוֶת הָיוּ בַּבְּהֵמוֹת, אֶחָד דֶּבֶר, וְאֶחָד אוֹתָם שֶׁהָרַג הַבָּרָד, וְאֶחָד אוֹתָם בְּכוֹרֵי הַבְּהֵמוֹת.</p>\n<p>וּמֶה הָיָה הַמָּוֶת שֶׁלָּהֶם? אֶלָּא זֶה כָּתוּב בַּתְּחִלָּה, הִנֵּה יַד ה' הוֹיָה בְּמִקְנְךְ אֲשֶׁר בַּשָּׂדֶה. לָמָּה בְּכֻלָּם לֹא כָתוּב יַד ה'? אֶלָּא כָּאן (כתוב יד אלהים, אלא יד ה') (אל יד ה') זֶה יָד עִם חָמֵשׁ אֶצְבְּעוֹת, שֶׁהֲרֵי בַּתְּחִלָּה כָּתוּב אֶצְבַּע אֱלֹהִים הִיא, וְכָאן כָּל חֲמֵשׁ הָאֶצְבָּעוֹת, וְכָל אֶצְבַּע וְאֶצְבַּע הָרְגָה מִין אֶחָד. וַחֲמִשָּׁה מִינִים הָיוּ, שֶׁכָּתוּב בַּסּוּסִים, בַּחֲמוֹרִים, בַּגְּמַלִּים, בַּבָּקָר, וּבַצֹאן. הֲרֵי חֲמִשָּׁה מִינִים לְחָמֵשׁ אֶצְבָּעוֹת, שֶׁנִּקְרֵאת יָד. מִשּׁוּם כָּךְ הִנֵּה יַד ה' הוֹיָה וְגוֹ' דֶּבֶר כָּבֵד מְאֹד. שֶׁהָיוּ מֵתִים מֵעַצְמָם וְנִמְצְאוּ מֵתִים.</p>\n<p>מֵאַחַר שֶׁלֹּא חָזְרוּ הַמִּצְרִים, אוֹתָן אוֹתִיּוֹת מַמָּשׁ חָזְרוּ וְהָרְגוּ כָּל אוֹתָם שֶׁנִּשְׁאֲרוּ, וְדֶבֶר הָפַךְ לְבָרָד. מַה בֵּין זֶה לָזֶה? אֶלָּא זֶה בְּנוֹחוּת, וְזֶה בְּתֹקֶף הָרֹגֶז, וּשְׁנֵי אֵלֶּה הָיוּ בְּמָקוֹם אֶחָד בְּחָמֵשׁ אֶצְבָּעוֹת.</p>"],[9522011581,"<p>בֹּא וּרְאֵה, דֶּבֶר אוֹתִיּוֹת שֶׁהָיוּ בְּנוֹחוּת, מָוֶת בִּמְנוּחָה, שֶׁהָיוּ מֵתִים מֵעַצְמָם. בָּרָד שֶׁהִתְהַפְּכוּ הָאוֹתִיּוֹת לְתֹקֶף הָרֹגֶז וְהָרַג הַכֹּל. יָשְׁבוּ בְּאוֹתוֹ שָׂדֶה, רָאוּ צֹאן שֶׁבָּאִים לְמָקוֹם אֶחָד וּמֵתִים שָׁם. קָם אוֹתוֹ יְהוּדִי לְאוֹתוֹ מָקוֹם, וְרָאָה שְׁנֵי נֹאדוֹת מְלֵאִים אֶרֶס.</p>\n<p>פָּתַח וְאָמַר, כָּתוּב וְאֶעֶשְׂךְ לְגוֹי גָּדוֹל וַאֲבָרֶכְךְ וַאֲגַדְּלָה שְׁמֶךְ וֶהְיֵה בְּרָכָה. דָּבָר זֶה שֶׁל רַבִּי אֶלְעָזָר שֶׁאָמַר (בראשית יב) וְאֶעֶשְׂךְ לְגוֹי גָּדוֹל - כְּנֶגֶד לֶךְ לְךְ. וַאֲבָרֶכְךְ - כְּנֶגֶד מֵאַרְצְךְ. וַאֲגַדְּלָה שְׁמֶךְ - כְּנֶגֶד וּמִמּוֹלַדְתְּךְ. וֶהְיֵה בְּרָכָה - כְּנֶגֶד וּמִבֵּית אָבִיךְ, וְזֶה כְּנֶגֶד זֶה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, סוֹד הַחָכְמָה יֵשׁ כָּאן. וְאֶעֶשְׂךְ לְגוֹי גָּדוֹל - כְּנֶגֶד צַד יָמִין. וַאֲבָרֶכְךְ - כְּנֶגֶד צַד שְׂמֹאל. וַאֲגַדְּלָה שְׁמֶךְ - כְּנֶגֶד צַד הָאֶמְצַע. וֶהְיֵה בְּרָכָה - כְּנֶגֶד צַד אֶרֶץ יִשְׂרָאֵל, וְהַכֹּל סוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה.</p>\n<p>בֹּא רְאֵה, בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה מִתְעוֹרֵר לְמַעְלָה, וְעַד שֶׁלֹּא מִתְעוֹרֵר לְמַטָּה לֹא מִתְעוֹרֵר לְמַעְלָה לִשְׁרוֹת עָלָיו. מַה כָּתוּב בְּאַבְרָהָם? וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים. וַיֵּצְאוּ אִתָּם - וַיֵּצְאוּ אִתּוֹ הָיָה צָרִיךְ (לכתב) ! שֶׁהֲרֵי כָּתוּב וַיִּקַּח תֶּרַח אֶת אַבְרָם בְּנוֹ (ואת לוט בן הרן) וְגוֹ'. מַהוּ וַיֵּצְאוּ אִתָּם. ? אֶלָּא, תֶּרַח וְלוֹט יָצְאוּ עִם אַבְרָהָם וְשָׂרָה, שֶׁכֵּיוָן שֶׁנִּצּוֹל אַבְרָהָם מִן הָאֵשׁ, חָזַר תֶּרַח לַעֲשׂוֹת אֶת רְצוֹנוֹ, וְלָכֵן וַיֵּצְאוּ אִתָּם. כֵּיוָן שֶׁהֵם הִתְעוֹרְרוּ תְחִלָּה, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לֶךְ לְךְ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, לֶךְ לְךְ - לְתִקּוּנְךְ, לְעַצְמְךְ. מֵאַרְצְךְ - מֵאוֹתוֹ הַצַּד שֶׁל הַיִּשּׁוּב שֶׁאַתָּה שׁוֹקֵל, שֶׁנּוֹלַדְתָּ בּוֹ. וּמִמּוֹלַדְתְּךְ - מֵאוֹתוֹ תּוֹלָדָה שֶׁלְּךְ. וּמִבֵּית אָבִיךְ - שֶׁהֲרֵי הִשְׁגִּיחַ בַּשֹּׁרֶשׁ שֶׁלָּהֶם. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ - שָׁם אֲגַלֶּה לְךְ מַה שֶּׁאַתָּה מְבַקֵּשׁ. אוֹתוֹ כֹּחַ שֶׁמְּמֻנֶּה עָלֶיהָ, שֶׁהוּא עָמֹק וְסָתוּם, מִיָּד - וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה'. וְאָנוּ רָצִינוּ לָלֶכֶת מִכָּאן לָדַעַת סוֹד הַחָכְמָה. (פתח רבי אבא ואמר (צפניה ג) כי אז אהפוך אל עמים שפה ברורה לקרא כלם בשם ה' לעבדו שכם אחד. וכתוב (זכריה יד) והיה ה' למלך וגו' ביום ההוא יהיה ה' אחד ושמו אחד).</p>"],[9522011582,"<p>רַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, לָמָּה אַתָּה שׁוֹתֵק, הֲרֵי הַדֶּרֶךְ לֹא מְתֻקֶּנֶת אֶלָּא רַק בְּדִבְרֵי תוֹרָה? נֶאֱנַח רַבִּי חִיָּיא וּבָכָה. (אמר לו, מהי, ' אמר לו, אוי וכו') פָּתַח וְאָמַר (בראשית יא) וַתְּהִי שָׂרַי עֲקָרָה אֵין לָהּ וָלָד. אוֹי עַל זֶה! אוֹי עַל אוֹתוֹ זְמַן שֶׁהוֹלִידָה הָגָר אֶת יִשְׁמָעֵאל.</p>\n<p>אָמַר לוֹ רַבִּי יוֹסֵי, לָמָּה? וַהֲרֵי הוֹלִידָה אַחַר כָּךְ, וְהָיָה לָהּ בֵּן גֶּזַע קָדוֹשׁ? אָמַר לוֹ, אַתָּה רוֹאֶה וַאֲנִי רוֹאֶה. וְכָךְ שָׁמַעְתִּי מִפִּי רַבִּי שִׁמְעוֹן דָּבָר, וּבָכִיתִי. (ס\"א אמר לו מה היא אמר לו ווי וכו') אוֹי עַל אוֹתוֹ הַזְּמַן שֶׁבִּגְלַל שֶׁשָּׂרָה הִתְעַכְּבָה, כָּתוּב (בראשית טז) וַתֹּאמֶר שָׂרַי אֶל אַבְרָם וְגוֹ' בּא נָא אֶל שִׁפְחָתִי וְגוֹ'. וְעַל זֶה עָמְדָה הַשָּׁעָה לְהָגָר לָרֶשֶׁת אֶת שָׂרָה גְּבִרְתָּהּ, וְהָיָה לָהּ בֵּן מֵאַבְרָהָם.</p>\n<p>וְאַבְרָהָם אָמַר, לוּ יִשְׁמָעֵאל יִחְיֶה לְפָנֶיךְ. וְאַף עַל גַּב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מְבַשֵּׂר לוֹ עַל יִצְחָק, נִדְבַּק אַבְרָהָם בְּיִשְׁמָעֵאל, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵשִׁיב לוֹ, וּלְיִשְׁמָעֵאל שְׁמַעְתִּיךְ וְגוֹ'. אַחַר כָּךְ נִמּוֹל וְנִכְנַס לַבְּרִית הַקָּדוֹשׁ, עַד שֶׁטֶּרֶם יָצָא יִצְחָק לָעוֹלָם.</p>\n<p>וּבֹא רְאֵה, אַרְבַּע מֵאוֹת שָׁנִים עָמַד אוֹתוֹ מְמֻנֶּה שֶׁל בְּנֵי יִשְׁמָעֵאל וּבִקֵּשׁ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר לוֹ, מִי שֶׁנִּמּוֹל יֵשׁ לוֹ חֵלֶק בְּשִׁמְךְ? אָמַר לוֹ, כֵּן. אָמַר לוֹ, וַהֲרֵי יִשְׁמָעֵאל נִמּוֹל, (ולא עוד, אלא שגמול בן שלש עשרה שנה) אָז לָמָּה אֵין לוֹ חֵלֶק בְּךְ כְּמוֹ יִצְחָק? אָמַר לוֹ, זֶה נִמּוֹל כָּרָאוּי וּכְתִקּוּנוֹ, וְזֶה לֹא כָּךְ. וְלֹא עוֹד, אֶלָּא שֶׁאֵלֶּה נִדְבָּקִים בִּי כָּרָאוּי לִשְׁמוֹנָה יָמִים, וְאֵלֶּה רְחוֹקִים מִמֶּנִּי עַד כַּמָּה יָמִים. אָמַר לוֹ, וְעִם כָּל זֶה, כֵּיוָן שֶׁנִּמּוֹל, לֹא יִהְיֶה לוֹ שָׂכָר טוֹב בִּשְׁבִיל זֶה?</p>\n<p>אוֹי עַל אוֹתוֹ זְמַן שֶׁנּוֹלַד יִשְׁמָעֵאל בָּעוֹלָם וְנִמּוֹל, מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? הִרְחִיק אֶת בְּנֵי יִשְׁמָעֵאל מִן הַדְּבֵקוּת הָעֶלְיוֹנָה, וְנָתַן לָהֶם חֵלֶק לְמַטָּה בָּאָרֶץ הַקְּדוֹשָׁה בִּשְׁבִיל אוֹתָהּ הַמִּילָה שֶׁבָּהֶם.</p>\n<p>וַעָתִידִים בְּנֵי יִשְׁמָעֵאל לִשְׁלֹט בָּאָרֶץ הַקְּדוֹשָׁה כְּשֶׁהִיא רֵיקָה מֵהַכֹּל זְמַן רַב, כְּמוֹ שֶׁהַמִּילָה שֶׁלָּהֶם רֵיקָה בְּלִי שְׁלֵמוּת, וְהֵם יְעַכְּבוּ אֶת בְּנֵי יִשְׂרָאֵל לָשׁוּב לִמְקוֹמָם, עַד שֶׁיִּשְׁתַּלֵּם אוֹתָהּ זְכוּת שֶׁל בְּנֵי יִשְׁמָעֵאל.</p>\n<p>וַעָתִידִים בְּנֵי יִשְׁמָעֵאל לְעוֹרֵר קְרָבוֹת חֲזָקִים בָּעוֹלָם וּלְהִתְכַּנְּסוּת בְּנֵי אֱדוֹם עֲלֵיהֶם, וִיעוֹרְרוּ בָהֶם קְרָב, אֶחָד עַל הַיָּם, וְאֶחָד עַל הַיַּבָּשָׁה, וְאֶחָד סָמוּךְ לִירוּשָׁלַיִם, וְיִשְׁלְטוּ אֵלֶּה בְּאֵלֶּה, וְאֶרֶץ הַקְּדוֹשָׁה לֹא תִמָּסֵר לִבְנֵי אֱדוֹם.</p>\n<p>בְּאוֹתוֹ זְמַן יִתְעוֹרֵר עַם אֶחָד מִסּוֹף הָעוֹלָם עַל רוֹמִי הָרְשָׁעָה, וְיַעֲרֹךְ בָּהּ קְרָב שְׁלֹשָׁה חֳדָשִׁים, וְיִתְכַּנְּסוּ שָׁם עַמִּים, וְיִפְּלוּ בִידֵיהֶם, עַד שֶׁיִּתְכַּנְּסוּ כָּל בְּנֵי אֱדוֹם עָלֶיהָ מִסּוֹפֵי כָּל הָעוֹלָם, וְאָז יִתְעוֹרֵר עֲלֵיהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (ישעיהלד) כִּי זֶבַח לַה' בְּבָצְרָה וְגוֹ'. אַחַר זֶה מַה כָּתוּב? לֶאֱחֹז בְּכַנְפוֹת הָאָרֶץ וְגוֹ'. וִיכַלֶּה אֶת בְּנֵי יִשְׁמָעֵאל מִמֶּנָּה, וְיִשְׁבֹּר כָּל הַחֲיָלוֹת-כֹּחוֹת שֶׁלְּמַעְלָה, וְלֹא יִשָּׁאֵר כֹּחַ לְמַעְלָה עַל הָעָם שֶׁל הָעוֹלָם, אֶלָּא כֹּחַ יִשְׂרָאֵל לְבַדּוֹ, זֶהוּ שֶׁכָּתוּב (תהלים קכא) ה' צִלְּךְ עַל יַד יְמִינֶךְ.</p>\n<p>מִשּׁוּם שֶׁהַשֵּׁם הַקָּדוֹשׁ בְּיָמִין, וְתוֹרָה בְיָמִין, וְעַל זֶה בְּיָמִין תָּלוּי הַכֹּל, וְשָׁנִינוּ שֶׁצָּרִיךְ לִזְקֹף אֶת הַיָּמִין עַל הַשְּׂמֹאל, כְּמוֹ שֶׁפֵּרְשׁוּהָ, שֶׁכָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ. וּבַזְּמַן שֶׁיָּבֹא, (תהלים ס) הוֹשִׁיעָה יְמִינְךְ וַעֲנֵנִי. וּבְאוֹתוֹ זְמַן כָּתוּב, כִּי אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם ה' לְעָבְדוֹ שְׁכֶם אֶחָד. וְכָתוּב בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן:</p>"],[9522011583,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה בּא אֶל פַּרְעֹה כִּי אֲנִי הִכְבַּדְתִּי אֶת לִבּוֹ וְגוֹ'. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים פט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה ה' בְּאוֹר פָּנֶיךְ יְהַלֵּכוּן. כַּמָּה צְרִיכִים בְּנֵי אָדָם לָלֶכֶת בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלִשְׁמֹר מִצְווֹת הַתּוֹרָה כְּדֵי שֶׁיִּזְכּוּ בָהּ לָעוֹלָם הַבָּא, וּלְהַצִּיל אוֹתָם מִכָּל הַקִּטְרוּגִים שֶׁלְּמַעְלָה וּמַטָּה, מִשּׁוּם שֶׁהֲרֵי כְּמוֹ שֶׁנִּמְצָאִים מְקַטְרְגִים בָּעוֹלָם לְמַטָּה, כָּךְ גַּם נִמְצָאִים מְקַטְרְגִים לְמַעְלָה שֶׁעוֹמְדִים עַל בְּנֵי אָדָם.</p>\n<p>אוֹתָם שֶׁעוֹשִׂים מִצְווֹת הַתּוֹרָה וְהוֹלְכִים בְּדֶרֶךְ יְשָׁרָה בְּיִרְאַת אֲדוֹנָם, כַּמָּה סָנֵגוֹרִים שֶׁעוֹמְדִים עֲלֵיהֶם לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (איוב לג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף וְגוֹ'. וְכָתוּב וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר. מִשּׁוּם כָּךְ אַשְׁרֵי מִי שֶׁשּׁוֹמֵר מִצְווֹת הַתּוֹרָה.</p>\n<p>אָמַר לוֹ רַבִּי חִיָּיא, אִם כָּךְ, לָמָּה צָרִיךְ כָּאן מַלְאָךְ שֶׁיִּהְיֶה סָנֵגוֹר עַל הָאָדָם, וַהֲרֵי כָּתוּב (משלי ג) כִּי ה' יִהְיֶה בְּכִסְלֶךְ וְשָׁמַר רַגְלְךְ מִלָּכֶד, וְכָתוּב (תהלים קכא) ה' יִשְׁמָרְךְ מִכָּל רָע. שֶׁהֲרֵי רוֹאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל מַה שֶּׁאָדָם עוֹשֶׂה בָּעוֹלָם, הֵן לְטוֹב וְהֵן לְרַע. וְכֵן הוּא אוֹמֵר, (ירמיה כג) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'.</p>\n<p>אָמַר לוֹ רַבִּי יְהוּדָה, הַכֹּל כָּךְ הוּא וַדַּאי, אֲבָל הֲרֵי כָּתוּב (איובב) וְגַע אֶל עַצְמוֹ וְאֶל בְּשָׂרוֹ. וְכָתוּב וַתְּסִיתֵנִי בוֹ לְבַלְּעוֹ חִנָּם. לְהַרְאוֹת שֶׁהֲרֵי רְשׁוּת נִמְסְרָה לַצַּד הָאַחֵר לְקַטְרֵג (והרשות נמסרה) עַל דְּבָרִים שֶׁל הָעוֹלָם (למי שלא הצטרך) וּלְהִמָּסֵר בְּיָדוֹ, וְכָל הַדְּרָכִים הַלָּלוּ טְמוּנִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֵינְךְ כְּדַאי לָלֶכֶת אַחֲרֵיהֶם, מִשּׁוּם שֶׁאֵלּוּ הַנְהָגוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֵין בְּנֵי אָדָם רַשָּׁאִים לְדַקְדֵּק אַחֲרֵיהֶם, פְּרָט לְאוֹתָם צַדִּיקֵי אֱמֶת שֶׁיּוֹדְעִים אֶת סוֹדוֹת הַתּוֹרָה וְהוֹלְכִים בַּדֶּרֶךְ שֶׁל הַחָכְמָה לָדַעַת אוֹתָם דְּבָרִים נִסְתָּרִים שֶׁל הַתּוֹרָה.</p>"],[9522011584,"<p>רַבִּי אֶלְעָזָר פָּתַח, (שם א) וַיְהִי הַיּוֹם וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים לְהִתְיַצֵּב עַל ה' וַיָּבוֹא גַם הַשָּׂטָן בְּתוֹכָם. וַיְהִי הַיּוֹם - זֶה רֹאשׁ הַשָּׁנָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד לָדוּן אֶת הָעוֹלָם, כְּמוֹ זֶה, וַיְהִי הַיּוֹם וַיָּבֹא שָׁמָּה. אוֹתוֹ יוֹם הָיָה יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה.</p>\n<p>וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים - אֵלּוּ מְמֻנִּים גְּדוֹלִים שְׁלוּחִים בָּעוֹלָם, לְהַשְׁגִּיחַ בְּמַעֲשֵׂי בְּנֵי הָאָדָם. לְהִתְיַצֵּב עַל ה' - כְּמוֹ שֶׁנֶּאֱמַר (מלכים א כב) וְכָל צְבָא הַשָּׁמַיִם עֹמֵד עָלָיו מִימִינוֹ וּמִשְּׂמֹאלוֹ. אֲבָל לְהִתְיַצֵּב עַל ה', בְּפָסוּק זֶה מָצָאנוּ אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יִשְׂרָאֵל, מִשּׁוּם שֶׁהַשְּׁלוּחִים הַלָּלוּ, שֶׁמְּמֻנִּים לְהַשְׁגִּיחַ עַל מַעֲשֵׂי בְּנֵי הָאָדָם, הוֹלְכִים וּמְשׁוֹטְטִים וְלוֹקְחִים אֶת כָּל אוֹתָם הַמַּעֲשִׂים, וּבַיּוֹם שֶׁבָּא הַדִּין לַעֲמֹד לָדוּן הָעוֹלָם, נַעֲשִׂים קָטֵגוֹרִים לַעֲמֹד עַל בְּנֵי אָדָם. וּבֹא רְאֵה, מִכָּל הָעַמִּים שֶׁבָּעוֹלָם לֹא עוֹמְדִים לְהַשְׁגִּיחַ בְּמַעֲשֵׂיהֶם רַק עַל יִשְׂרָאֵל לְבַדָּם, מִשּׁוּם שֶׁאֵלֶּה בָּנִים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וּכְשֶׁלֹּא נִמְצָאִים הַמַּעֲשִׂים שֶׁל יִשְׂרָאֵל כָּרָאוּי, כִּבְיָכוֹל אוֹתָם שְׁלוּחִים מְמֻנִּים, כְּשֶׁרוֹצִים לַעֲמֹד עַל אוֹתָם מַעֲשִׂים שֶׁל יִשְׂרָאֵל, הֵם עוֹמְדִים וַדַּאי עַל ה', שֶׁהֲרֵי כְּשֶׁיִּשְׂרָאֵל עוֹשִׂים מַעֲשִׂים שֶׁלֹּא כְשֵׁרִים, כִּבְיָכוֹל מְתִשִּׁים כֹּחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְשֶׁעוֹשִׂים מַעֲשִׂים כְּשֵׁרִים, נוֹתְנִים כֹּחַ וְתֹקֶף לַקָּדוֹשׁ-בָּרוּךְ-הוּא. וְעַל זֶה כָּתוּב (תהלים סח) תְּנוּ עֹז לֵאלֹהִים. בַּמֶּה? בְּמַעֲשִׂים כְּשֵׁרִים, וְעַל זֶה בְּאוֹתוֹ יוֹם כָּל הַשָּׂרִים הַגְּדוֹלִים הַמְמֻנִּים הִתְכַּנְּסוּ עַל ה'. עַל ה' וַדַּאי, שֶׁהֲרֵי כֵּיוָן שֶׁהִתְכַּנְּסוּ עַל יִשְׂרָאֵל, הֵם הִתְכַּנְּסוּ עָלָיו.</p>\n<p>וַיָּבוֹא גַם הַשָּׂטָן בְּתוֹכָם. גַּם - לְרַבּוֹתוֹ עֲלֵיהֶם, שֶׁכֻּלָּם בָּאִים לִהְיוֹת קָטֵגוֹרִים עַל יִשְׂרָאֵל, וְזֶה נוֹסַף עֲלֵיהֶם מִשּׁוּם שֶׁהוּא הַמַּלְשִׁין הַגָּדוֹל מִכֻּלָּם, קָטֵגוֹר מִכֻּלָּם. כֵּיוָן שֶׁרוֹאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכֻּלָּם בָּאִים לְקַטְרֵג, מִיָּד - וַיֹּאמֶר ה' אֶל הַשָּׂטָן מֵאַיִן תָּבֹא. וְכִי לֹא הָיָה יוֹדֵעַ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאֵיפֹה הָיָה בָּא? אֶלָּא לְהָבִיא אֶת הַמַּעֲשֶׂה לִרְצוֹנוֹ.</p>\n<p>וַיֹּאמֶר ה' אֶל הַשָּׂטָן וְגוֹ' וַיַּעַן הַשָּׂטָן אֶת ה' וַיֹּאמַר מִשּׁוּט בָּאָרֶץ. מִכָּאן לָמַדְנוּ שֶׁיִּשּׁוּב הָאָרֶץ נִמְסָר לִצְדָדִים אֲחֵרִים, פְּרָט לְאֶרֶץ יִשְׂרָאֵל לְבַדָּהּ. כֵּיוָן שֶׁאָמַר מִשּׁוּט בָּאָרֶץ, הִשְׁגִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁרוֹצֶה לִהְיוֹת מַלְשִׁין עַל יִשְׂרָאֵל. מִיָּד - וַיֹּאמֶר ה' אֶל הַשָּׂטָן הֲשַׂמְתָּ לִבְּךְ עַל עַבְדִּי אִיּוֹב כִּי אֵין כָּמֹהוּ בָּאָרֶץ.</p>\n<p>רָאָה שָׁעָה לָתֵת לוֹ חֵלֶק בְּמַה שֶּׁיִּתְעַסֵּק, וְיִפָּרֵד מִיִּשְׂרָאֵל, וַהֲרֵי פֵּרְשׁוּהָ, לְרוֹעֶה שֶׁרָצָה לְהַעֲבִיר אֶת צֹאנוֹ בְּנָהָר אֶחָד וְכוּ', מִיָּד הִתְעַסֵּק בּוֹ אוֹתוֹ שָׂטָן וְלֹא קִטְרֵג עַל יִשְׂרָאֵל.</p>\n<p>וַיַּעַן הַשָּׂטָן אֶת ה' וַיֹּאמַר הַחִנָּם יָרֵא אִיּוֹב אֱלֹהִים. אֵין תְּמִיהָה עַל עֶבֶד שֶׁרַבּוֹ עוֹשֶׂה לוֹ כָּל רְצוֹנוֹ שֶׁיִּהְיֶה יָרֵא מִמֶּנּוּ. הָסֵר מִמֶּנּוּ אֶת הַשְׁגָּחָתְךְ, וְתִרְאֶה אִם יִפְחַד מִמְּךְ אִם לֹא.</p>\n<p>בֹּא רְאֵה, בִּשְׁעַת צָרָה, כְּשֶׁנִּתָּן חֵלֶק אֶחָד לַצַּד הַזֶּה לְהִתְעַסֵּק בּוֹ, נִפְרָד אַחַר כָּךְ מֵהַכֹּל. כְּמוֹ זֶה שָׂעִיר בְּרֹאשׁ חֹדֶשׁ, שָׂעִיר בְּיוֹם הַכִּפּוּרִים, כְּדֵי שֶׁיִּתְעַסֵּק בּוֹ וְיַעֲזֹב אֶת יִשְׂרָאֵל עִם מַלְכָּם, וְכָאן הִגִּיעַ זְמַן לִטֹּל חֵלֶק זֶה מִכָּל זֶרַע אַבְרָהָם בַּצַּד הָאַחֵר, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כב) הִנֵּה יָלְדָה מִלְכָּה גַּם הִיא וְגוֹ' אֶת עוּץ בְּכוֹרוֹ וְגוֹ'.</p>\n<p>וּבֹא רְאֵה, בְּשָׁעָה שֶׁאָמַר מִשּׁוּט בָּאָרֶץ, רָצָה מִמֶּנּוּ לַעֲשׂוֹת דִּין בְּיִשְׂרָאֵל, שֶׁהֲרֵי דִּין הָיָה לוֹ עַל אַבְרָהָם לִתְבֹּעַ מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁלֹּא נַעֲשָׂה דִין בְּיִצְחָק כְּשֶׁהֻקְרַב עַל גַּבֵּי הַמִּזְבֵּחַ, שֶׁהֲרֵי לֹא הָיָה לוֹ לְהַחֲלִיף קָרְבָּן שֶׁמֻּזְמָן עַל הַמִּזְבֵּחַ בְּאַחֵר, (וכן בכל צד שלו) כְּמוֹ שֶׁנֶּאֱמַר לֹא יַחֲלִיפֶנּוּ. וְכָאן עָמַד יִצְחָק עַל גַּבֵּי הַמִּזְבֵּחַ וְלֹא הִשְׁתַּלֵּם מִמֶּנּוּ קָרְבָּן וְלֹא נַעֲשָׂה בּוֹ דִּין, וְרָצָה אֶת זֶה מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ שֶׁרָצָה אֶת דִּינוֹ שֶׁל יוֹסֵף לְכַמָּה דוֹרוֹת מְאֻחָר יוֹתֵר, וְכָל מַה שֶּׁרָצָה - רָצָה בְּדֶרֶךְ דִּין.</p>\n<p>וּמֵאוֹתוֹ זְמַן שֶׁנִּצַּל יִצְחָק וְהִתְחַלֵּף קָרְבָּנוֹ, הִזְמִין לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ מְקַטְרֵג זֶה לְחֶלְקוֹ, כְּמוֹ שֶׁנֶּאֱמַר הִנֵּה יָלְדָה מִלְכָּה גַּם הִיא וְגוֹ' אֶת עוּץ בְּכוֹרוֹ. וְכָאן הִגִּיעַ לִטֹּל חֶלְקוֹ עָלָיו מִכָּל זַרְעוֹ שֶׁל אַבְרָהָם וְלֹא יִקְרַב לְצַד אַחֵר.</p>\n<p>וְהַכֹּל בָּא בְּדִין (אצלו). כְּמוֹ שֶׁהוּא דָּן - כָּךְ נִדּוֹן. מִשּׁוּם שֶׁאִיּוֹב מִקְּרוֹבֵי הָעֵצָה שֶׁל פַּרְעֹה הָיָה, וּכְשֶׁעָמַד פַּרְעֹה עַל יִשְׂרָאֵל, רָצָה לַהֲרֹג אוֹתָם. אָמַר לוֹ, לֹא, אֶלָּא קַח מָמוֹנָם וּשְׁלֹט עַל גּוּפָם בַּעֲבוֹדָה קָשָׁה, וְאַל תַּהֲרֹג אוֹתָם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, חַיֶּיךְ, בְּאוֹתוֹ דִין מַמָּשׁ תִּהְיֶה נִדּוֹן. מַה כָּתוּב? (איוב ב) אוּלָם שְׁלַח נָא יָדְךְ וְגַע אֶל עַצְמוֹ וְאֶל בְּשָׂרוֹ וְגוֹ'. בְּמַה שֶּׁהוּא דָּן - כָּךְ נִדּוֹן. וְאַף עַל גַּב שֶׁבְּכָל הַשְּׁאָר הָיָה יָרֵא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא וּרְאֶה מַה כָּתוּב, אַךְ אֶת נַפְשׁוֹ שְׁמֹר. וְנִתְּנָה לוֹ רְשׁוּת לִשְׁלֹט עַל הַבָּשָׂר, מִשּׁוּם הַסּוֹד שֶׁכָּתוּב (בראשית ו) קֵץ כָּל בָּשָׂר בָּא לְפָנַי, וּפֵרְשׁוּהָ, בָּא לְפָנַי וַדַּאי. וְזֶהוּ קֵץ כָּל בָּשָׂר, וְלֹא רוּחַ. וְנֶאֱמַר שֶׁהוּא קֵץ שֶׁבָּא מִצַּד הַחֹשֶׁךְ, כְּמוֹ שֶׁנֶּאֱמַר (איוב כח) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר. וּלְכָל בָּשָׂר, מִשּׁוּם שֶׁיֵּשׁ קֵץ אַחֵר, וְנִקְרָא קֵץ הַיָּמִין, וְזֶהוּ קֵץ אַחֵר מִצַּד הַשְּׂמֹאל שֶׁהוּא חֹשֶׁךְ, וְלָכֵן נִתְּנָה לוֹ רְשׁוּת בְּעַצְמוֹ וּבְשָׂרוֹ.</p>\n<p>וַתְּסִיתֵנִי בוֹ לְבַלְּעוֹ. אִם כָּךְ, לֹא בְּדִין הָיָה, אֶלָּא בְּמַאֲמַר אוֹתוֹ מְקַטְרֵג שֶׁהֵסִית אוֹתוֹ וְהִסְטָה אוֹתוֹ, אֶלָּא הַכֹּל הָיָה בְּדִין. וְכָךְ אָמַר לוֹ אֱלִיהוּא, (שם לד) כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִיאֶנּוּ. וְכָךְ הָיָה כְּמוֹ שֶׁנֶּאֱמַר, כְּמוֹ שֶׁהוּא גָּזַר - כָּךְ נִגְזַר עָלָיו.</p>\n<p>וְזְהִ שֶׁאָמַר וַתְּסִיתֵנִי בוֹ לְבַלְּעוֹ חִנָּם. וַתְּסִיתֵי לְבַלְּעוֹ לֹא כָתוּב, אֶלָּא וַתְּסִיתֵנִי בוֹ, בּוֹ עוֹמֵד בְּדַעְתּוֹ, שֶׁהוּא חָשַׁב שֶׁהֲרֵי תְּסִיתֵנִי, כְּמוֹ שֶׁאָמַר וְעַל עֲצַת רְשָׁעִים הוֹפָעְתָּ. (אמר איוב, התפתתי על דברי אותו מקטרג) כְּמוֹ זֶה (תהלים עח) וַיְפַתּוּהוּ בְּפִיהֶם וּבִלְשׁוֹנָם יְכַזְּבוּ לוֹ. וַיְפַתּוּהוּ וַיְכַזְּבוּ לוֹ לֹא כָתוּב, אֶלָּא וַיְפַתּוּהוּ בְּפִיהֶם. בְּפִיהֶם עוֹמֵד הַדָּבָר הַזֶּה, שֶׁהֲרֵי הִתְפַּתָּה.</p>\n<p>אָמַר רַבִּי אַבָּא, הַכֹּל הוּא יָפֶה, אֲבָל כָּךְ לָמַדְנוּ, שֶׁשָּׁנִינוּ, עוֹלֶה וּמַסְטִין. וְכִי הוּא יָכוֹל לְהַסְטִין? כֵּן, שֶׁהֲרֵי הוּא מֶלֶךְ זָקֵן וּכְסִיל, שֶׁכָּתוּב (קהלת ד) טוֹב יֶלֶד מִסְכֵּן וְחָכָם מִמֶּלֶךְ זָקֵן וּכְסִיל. וְעַל זֶה יָכוֹל לְהַסְטִין לָאָדם. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא נֶאֱמָן עַל מַעֲשֵׂי בְּנֵי אָדָם.</p>\n<p>בֹּא רְאֵה, זֶה בְּדִין הַיָּחִיד, אֲבָל בְּדִין הָעוֹלָם כָּתוּב (בראשית יא) וַיֵּרֶד ה' לִרְאוֹת. אֵרֲדָה נָא וְאֶרְאֶה. שֶׁלֹּא נִתְּנָה הָאֱמוּנָה אֶלָּא בְּיָדוֹ לְבַדּוֹ, שֶׁהֲרֵי לֹא רָצָה לְאַבֵּד אֶת הָעוֹלָם עַל מַאֲמַר אוֹתוֹ מְקַטְרֵג שֶׁתְּשׁוּקָתוֹ תָּמִיד לְהַשְׁמִיד. מִנַּיִן לָנוּ? שֶׁכָּתוּב (איוב כח) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר. לְהַשְׁמִיד הַכֹּל הוּא חוֹקֵר. וְזֶהוּ קֵץ כָּל בָּשָׂר בָּא לְפָנַי, וַדַּאי כְּדֵי לְהַשְׁמִיד.</p>\n<p>וּבֹא רְאֵה, וַיְהִי הַיּוֹם וַיָּבֹאוּ בְּנֵי הָאֱלֹהִים לְהִתְיַצֵּב עַל ה', כְּמוֹ שֶׁנֶּאֱמַר. וְאוֹתוֹ יוֹם עוֹמְדִים שְׁנֵי צְדָדִים כְּנֶגֶד בְּנֵי הָעוֹלָם. כָּל אוֹתָם שֶׁבָּאִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְשׁוּבָה וּבְמַעֲשִׂים טוֹבִים, הֵם זוֹכִים לִהְיוֹת כְּתוּבִים אֵצֶל אוֹתוֹ צַד שֶׁהוּא חַיִּים, וּמוֹצִיא תּוֹצְאוֹת חַיִּים. וּמִי שֶׁהוּא מִצִּדּוֹ, נִכְתָּב לְחַיִּים. וְכָל אוֹתָם שֶׁבָּאִים בְּמַעֲשִׂים רָעִים לְאוֹתוֹ צַד, הֵם נִכְתָּבִים לְאוֹתוֹ צַד אַחֵר שֶׁהוּא מָוֶת, וְנִקְרָא מָוֶת, וּבוֹ שׁוֹרֶה הַמָּוֶת.</p>\n<p>וּבְאוֹתוֹ יוֹם עוֹמְדִים שְׁנֵי הַצְּדָדִים הַלָּלוּ - חַיִּים וּמָוֶת. יֵשׁ מִי שֶׁנִּכְתָּב לְצַד הַחַיִּים, וְיֵשׁ מִי שֶׁנִּכְתָּב לְצַד הַמָּוֶת. וְלִפְעָמִים שֶׁהָעוֹלָם שָׁרוּי בָּאֶמְצַע. אִם עוֹמֵד צַדִּיק אֶחָד בָּעוֹלָם שֶׁעוֹמֵד עֲלֵיהֶם, כֻּלָּם עוֹמְדִים וְנִכְתָּבִים לְחַיִּים. וְאִם רָשָׁע אֶחָד מַכְרִיעַ אֶת הָעוֹלָם, כֻּלָּם נִכְתָּבִים לְמִיתָה.</p>\n<p>וְאוֹתוֹ הַזְּמַן הָעוֹלָם הָיָה עוֹמֵד בָּאֶמְצַע, וְאוֹתוֹ מְקַטְרֵג רָצָה לְהַסְטִין. מִיָּד מַה כָּתוּב? הֲשַׂמְתָּ לִבְּךְ עַל עַבְדִּי אִיּוֹב כִּי אֵין כָּמֹהוּ בָּאָרֶץ וְגוֹ'. כֵּיוָן שֶׁנּוֹדַע הוּא לְבַדּוֹ, מִיָּד הֶחֱזִיק בּוֹ הַמְקַטְרֵג. וְעַל זֶה שָׁנִינוּ שֶׁלֹּא צָרִיךְ לָאָדָם לְהִפָּרֵד מִכְּלָל שֶׁל רַבִּים, כְּדֵי שֶׁלֹּא יֵרָשֵׁם לְבַדּוֹ, וְלֹא יְקַטְרְגוּ עָלָיו מִלְמַעְלָה.</p>\n<p>שֶׁכָּתוּב בַּשּׁוּנַמִּית, (מלכים ב ד) וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת. לֹא רוֹצָה לְהוֹצִיא אֶת עַצְמִי מִכְּלָל שֶׁל רַבִּים. בְּתוֹךְ עַמִּי יוֹשֶׁבֶת עַד יוֹם זֶה, וּבְתוֹךְ עַמִּי - בִּכְלָל אֶחָד נוֹדַעַת לְמַעְלָה. וְכָאן אִיּוֹב, כֵּיוָן שֶׁנּוֹדַע לְמַעְלָה וְנִרְשַׁם, מִיָּד הֶחֱזִיק בּוֹ הַמְקַטְרֵג וְאָמַר, הַחִנָּם יָרֵא אִיּוֹב אֱלֹהִים?! כָּל מַה שֶּׁפָּחַד מִמְּךְ וְהִתְחַזֵּק, לֹא לְחִנָּם עָשָׂה, הֲלֹא אַתָּה שַׂכְתָּ בַעֲדוֹ וּבְעַד וְגוֹ'. אֲבָל טֹל אֶת כָּל הַטּוּב שֶׁאַתָּה עוֹשֶׂה לוֹ, וּמִיָּד אִם לֹא עַל פָּנֶיךְ יְבָרְכֶךָּ. יַעֲזב אוֹתְךְ וְיִדְבַּק בַּצַּד הָאַחֵר, שֶׁהֲרֵי עַכְשָׁו בְּשֻׁלְחָנְךְ הוּא אוֹכֵל. סַלֵּק מִמֶּנּוּ אֶת שֻׁלְחָנְךְ, וְנִרְאֶה מִמִּי הוּא וְאֵיזֶה צַד יִדְבַּק.</p>\n<p>מִיָּד - וַיֹּאמֶר ה' אֶל הַשָּׂטָן הִנֵּה כָל אֲשֶׁר לוֹ בְּיָדֶךְ. לְהַרְאוֹת שֶׁיִּרְאַת אִיּוֹב לַקָּדוֹשׁ-בָּרוּךְ-הוּא הוּא כְּדֵי לִשְׁמֹר עָשְׁרוֹ. וּמִכָּאן לָמַדְנוּ, שֶׁכָּל אוֹתָם הַיְּרֵאִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא מִשּׁוּם עָשְׁרָם אוֹ בְנֵיהֶם, זוֹ אֵינָהּ יִרְאָה כָּרָאוּי. וְעַל כֵּן קִטְרֵג אוֹתוֹ מְקַטְרֵג וְאָמַר, הַחִנָּם יָרֵא אִיּוֹב אֱלֹהִים הֲלֹא אַתָּה שַׂכְתָּ בַעֲדוֹ וְגוֹ' מַעֲשֵׂה יָדָיו בֵּרַכְתָּ. וְעַל כָּךְ הוּא יָרֵא מִמְּךְ. וְנִתְּנָה לוֹ רְשׁוּת לְקַטְרֵג בּוֹ וּלְהַרְאוֹת שֶׁלֹּא עָבַד אִיּוֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַהֲבָה.</p>\n<p>שֶׁכֵּיוָן שֶׁהִתְנַסָּה, יָצָא מֵהַדֶּרֶךְ וְלֹא עָמַד בְּקִיּוּמוֹ. מַה כָּתוּב? בְּכָל זאת לֹא חָטָא אִיּוֹב בִּשְׂפָתָיו. לֹא חָטָא בִּשְׂפָתָיו, אֲבָל בִּרְצוֹנוֹ חָטָא, וְאַחַר כָּךְ חָטָא בַּכֹּל.</p>\n<p>וְאִם תֹּאמַר שֶׁלֹּא מִתְנַסֶּה בֶּן אָדָם, הֲרֵי כָּתוּב ה' צַדִּיק יִבְחָן וְגוֹ'. וּמִשּׁוּם כָּךְ הִתְנַסָּה אִיּוֹב. וְאַף עַל גַּב שֶׁלֹּא עָמַד בְּקִיּוּמוֹ כָּרָאוּי, לֹא יָצָא מִתַּחַת רְשׁוּת אֲדוֹנוֹ לְהִדָּבֵק בַּצַּד הָאַחֵר.</p>\n<p>וְכַמָּה הָיָה אוֹתוֹ נִסָּיוֹן שֶׁלּוֹ? שְׁנֵים עָשָׂר חֳדָשִׁים הַשִּׁלְטוֹן שֶׁל אוֹתוֹ הַצַּד הָאַחֵר, כְּמוֹ שֶׁשָּׁנִינוּ דִּין הָרְשָׁעִים בַּגֵּיהִנֹּם שְׁנֵים עָשָׂר חֳדָשִׁים, וּמִשּׁוּם שֶׁלֹּא דָבַק בַּצַּד הָאַחֵר, כָּתוּב (איוב מב) וַה' בֵּרַךְ אֶת אַחֲרִית אִיּוֹב מֵרֵאשִׁיתוֹ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, זֶה שֶׁל אִיּוֹב אֵינוֹ נִסָּיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ נִסָּיוֹן שֶׁל שְׁאָר הַצַּדִּיקִים, שֶׁהֲרֵי לֹא כָתוּב וְהָאֱלֹהִים נִסָּה אֶת אִיּוֹב כְּמוֹ שֶׁכָּתוּב (בראשית כב) וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. שֶׁאַבְרָהָם הוּא בְּיָדָיו הִקְרִיב אֶת בְּנוֹ הַיְחִידִי לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְאִיּוֹב לֹא נָתַן כְּלוּם, וְלֹא מָסַר לַקָּדוֹשׁ-בָּרוּךְ-הוּא כְּלוּם.</p>\n<p>וְלֹא נֶאֱמַר לוֹ, שֶׁהֲרֵי גָּלוּי לְפָנָיו שֶׁלֹּא יָכוֹל לַעֲמֹד בּוֹ, אֲבָל נִמְסַר בְּיַד הַמְקַטְרֵג, וּבַדִּין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נַעֲשָׂה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֵעִיר אֶת הַדִּין (בדין) הַזֶּה אֶל אוֹתוֹ מְקַטְרֵג אֵלָיו. זֶהוּ שֶׁכָּתוּב הֲשַׂמְתָּ לִבְּךְ עַל עַבְדִּי אִיּוֹב וְגוֹ'.</p>\n<p>פָּתַח וְאָמַר, (שם ד) וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה. מִקֵּץ יָמִים וְלֹא מִקֵּץ יָמִין. הוּא דָּחָה אֶת קֵץ הַיָּמִין, וְהִתְקָרֵב לְקֵץ הַיָּמִים. וַהֲרֵי בֵּאַרְנוּ, (דניאל יב) וְאַתָּה לֵךְ לְקֵץ. וְאָמַר דָּנִיֵּאל, לְאֵיזֶה קֵץ? לְקֵץ הַיָּמִין אוֹ לְקֵץ הַיָּמִים? עַד שֶׁאָמַר לוֹ לְקֵץ הַיָּמִין. וְעַל זֶה דָּוִד פָּחַד וְאָמַר, (תהלים לט) הוֹדִיעֵנִי ה' קִצִּי וּמִדַּת יָמַי מַה הִיא, אוֹ לְקֵץ הַיָּמִים אוֹ לְקֵץ הַיָּמִין. וְכָאן מַה כָּתוּב? וַיְהִי מִקֵּץ יָמִים, וְלֹא מִקֵּץ יָמִין, וְלָכֵן לֹא הִתְקַבֵּל קָרְבָּנוֹ, שֶׁהֲרֵי הָיָה מִצַּד הָאַחֵר (הכל).</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב? וְהֶבֶל הֵבִיא גַּם הוּא. מַה זֶּה גַּם הוּא? לְרַבּוֹת זֶה עִם זֶה. קָרְבָּנוֹ לַקָּדוֹשׁ-בָּרוּךְ- הוּא הָיָה הַכֹּל, וְעִקַּר הַקָּרְבָּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְנָתַן חֶלְקוֹ לַצַּד הָאַחֵר, כְּמוֹ שֶׁנֶּאֱמַר וּמֵחֶלְבֵיהֶן. וְקַיִן עִקָּרוֹ עָשָׂה מִקֵּץ יָמִים, הַסּוֹד שֶׁל הַצַּד הָאַחֵר, וְנָתַן חֵלֶק לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְלָכֵן לֹא הִתְקַבֵּל.</p>\n<p>בְּאִיּוֹב מַה כָּתוּב? וְהָלְכוּ בָנָיו וְעָשׂוּ מִשְׁתֶּה וְגוֹ', וְשָׁלְחוּ וְקָרְאוּ לִשְׁלֹשֶׁת אַחְיֹתֵיהֶם לֶאֱכֹל וְלִשְׁתּוֹת עִמָּהֶם וַיְהִי כִּי הִקִּיפוּ יְמֵי הַמִּשְׁתֶּה וְגוֹ'. וּבְמִשְׁתֶּה בְּכָל יוֹם מָצוּי הַמְקַטְרֵג, וְלֹא יָכוֹל לוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב הֲלֹא אַתָּה שַׂכְתָּ בַעֲדוֹ וּבְעַד בֵּיתוֹ וּבְעַד כָּל אֲשֶׁר לוֹ מִסָּבִיב, וּלְעוֹלָם לֹא נָתַן לוֹ חֵלֶק כְּלָל, שֶׁהֲרֵי (מה) כָּתוּב וְהֶעֱלָה עֹלוֹת מִסְפַּר כֻּלָּם. הָעוֹלָה עוֹלָה לְמַעְלָה לְמַעְלָה, וְלֹא נָתַן חֵלֶק לַצַּד הָאַחֵר. שֶׁאִלְמָלֵא נָתַן לוֹ חֵלֶק, לֹא יָכֹל לוֹ אַחַר כָּךְ, וְעָל מַה שֶּׁנָּטַל - מִשֶּׁלּוֹ נָטַל.</p>\n<p>וְאִם תֹּאמַר, לָמָּה הֵרַע לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא שֶׁאִלְמָלֵא נָתַן לוֹ חֵלֶק, יִפְנֶה הַדֶּרֶךְ וְיִסְתַּלֵּק מֵעַל הַמִּקְדָּשׁ, וְצַד הַקְּדֻשָּׁה מִסְתַּלֵּק לְמַעְלָה לְמַעְלָה. וְהוּא לֹא עָשָׂה כֵּן, וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא תָּבַע בְּדִין.</p>\n<p>בֹּא רְאֵה, כְּמוֹ שֶׁהוּא נִפְרַד וְלֹא הִפְרִיד טוֹב וָרַע, הוּא דָּן אוֹתוֹ בְּאוֹתוֹ אֹפֶן. נָתַן לוֹ טוֹב, וְאַחַר כָּךְ רַע, וְאַחַר כָּךְ הֶחֱזִירוֹ לְטוֹב. שֶׁכֵּן רָאוּי לָאָדָם, לָדַעַת טוֹב וְלָדַעַת רַע וּלְהַחֲזִיר עַצְמוֹ לְטוֹב, וְזֶהוּ סוֹד הָאֱמוּנָה. בּא רְאֵה, אִיּוֹב הָיָה מֵעַבְדֵי פַרְעֹה, וְזֶהוּ שֶׁכָּתוּב בּוֹ (שמות ט) הַיָּרֵא אֶת דְּבַר ה' מֵעַבְדֵי פַּרְעֹה. בֹּא וּרְאֵה שֶׁלֹּא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲקֹר אֶת אִיּוֹב מִמְּקוֹמוֹ, שֶׁהוּא הָיָה מֵגֵן (את הכל רצה הקדוש ברוך הוא לעקר ממקומם, איוב היה מגן (איּוב חָכָם הָיָה) על פרעה. כיון שגחלש, עשה נקמות לפרעה).</p>"],[9522011585,"<p>אָמַר רַבִּי שִׁמְעוֹן, כָּעֵת יֵשׁ לְגַלּוֹת סוֹדוֹת שֶׁנִּדְבָּקִים לְמַעְלָה וּלְמַטָּה. מַה כָּתוּב? בֹּא אֶל פַּרְעֹה, הָיָה צָרִיךְ (לכתב) לֵךְ אֶל פַּרְעֹה, מַה זֶּה בּא? אֶלָּא שֶׁהִכְנִיס אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא חֲדָרִים אַחַר חֲדָרִים לְתַנִּין אֶחָד עֶלְיוֹן תַּקִּיף, שֶׁכַּמָּה דְרָגוֹת מִשְׁתַּלְשְׁלוֹת מִמֶּנּוּ. וּמִיהוּ? סוֹד הַתַּנִּין הַגָּדוֹל.</p>\n<p>וּמֹשֶׁה פָּחַד מִמֶּנּוּ, וְלֹא קָרַב אֶלָּא לְאוֹתָם יְאוֹרִים, וְאוֹתָן הַדְּרָגוֹת שֶׁלּוֹ, אֲבָל מִמֶּנּוּ הוּא פָּחַד וְלֹא הִתְקָרֵב, מִשּׁוּם שֶׁרָאָה אוֹתוֹ מֵשְׁרָשׁ בְּשָׁרָשִׁים עֶלְיוֹנִים.</p>\n<p>כֵּיוָןֹ שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמֹּשֶׁה פּוֹחֵד וּשְׁלוּחִים מְמֻנִּים אֲחֵרִים לְמַעְלָה לֹא יְכוֹלִים לְהִתְקָרֵב אֵלָיו, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, (יחזקאל כט) הִנְנִי עָלֶיךְ פַּרְעֹה מֶלֶךְ מִצְרָיִם הַתַּנִּים הַגָּדוֹל הָרֹבֵץ בְּתוֹךְ יְאֹרָיו. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִצְטָרֵךְ לַעֲרֹךְ בּוֹ קְרָב וְלֹא אַחֵר, כְּמוֹ שֶׁנֶּאֱמַר אֲנִי ה', וּפֵרְשׁוּהָ סוֹד הַחָכְמָה, שֶׁהַתַּנִּים הַגָּדוֹל הָרֹבֵץ בְּתוֹךְ יְאֹרָיו לְאוֹתָם בַּעֲלֵי הַדִּין שֶׁיּוֹדְעִים בְּסוֹדוֹת אֲדוֹנָם.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדלִים וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרֹמֶשֶׂת אֲשֶׁר שָׁרְצוּ הַמַּיִם לְמִינֵיהֶם. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם - הוּא סוֹד זֶה לִוְיָתָן וּבַת זוּגוֹ. תַּנִּינִם חָסֵר כָּתוּב, מִשּׁוּם שֶׁהָרַג אֶת הַנְּקֵבָה, וְהֶעֱלָה אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים, וּפֵרְשׁוּהָ.</p>\n<p>הַתַּנִּים הַגָּדוֹל - תִּשְׁעָה יְאוֹרִים הֵם, שֶׁהוּא רוֹבֵץ בֵּינֵיהֶם, וִיאוֹר אֶחָד הוּא שֶׁמֵּימָיו שׁוֹכְכִים, וּבְרֵכוֹת מֵימֵי הַגָּן נוֹפְלִים בּוֹ שָׁלֹשׁ פְּעָמִים בַּשָּׁנָה. וְכַאֲשֶׁר זֶה שְׁתֵּי פְעָמִים, מִתְבָּרֵךְ אוֹתוֹ יְאוֹר וְלֹא כָּל כָּךְ, וּכְשֶׁאֶחָד בִּכְלָל לֹא.</p>\n<p>וְהַתַּנִּין הַזֶּה נִכְנָס לְאוֹתוֹ יְאוֹר מִתְחַזֵּק וְהוֹלֵךְ וְשָׁט וְנִכְנָס לְתוֹךְ הַיָּם, וּבוֹלֵעַ דָּגִים מִכַּמָּה מִינִים, וְשׁוֹלֵט וְשָׁב לְאוֹתוֹ יְאוֹר. תִּשְׁעָה יְאוֹרִים הַלָּלוּ הוֹלְכִים וְעוֹלִים, וּסְבִיבוֹ כַּמָּה אִילָנוֹת וַעֲשָׂבִים לְמִינֵיהֶם.</p>\n<p>הַיְאוֹר הָרִאשׁוֹן. יוֹצֵא מִצַּד שְׂמֹאל בְּצִנּוֹר אֶחָד שֶׁשּׁוֹפֵעַ וְיוֹצֵא שָׁלֹשׁ טִפּוֹת, וְכָל טִפָּה וְטִפָּה נִפְרֶדֶת לְשָׁלֹשׁ טִפּוֹת, וְכָל טִפָּה וְטִפָּה נַעֲשֶׂה מִמֶּנָּה יְאוֹר אֶחָד, וְאֵלֶּה הֵם תִּשְׁעָה יְאוֹרִים שֶׁמִּתְחַזְּקִים וְהוֹלְכִים וּמְשׁוֹטְטִים וְסוֹבְבִים בְּכָל אוֹתָם הָרְקִיעִים.</p>\n<p>מִמַּה שֶּׁנִּשְׁאָר מֵאוֹתָן טִפּוֹת כְּשֶׁסִּיְּמוּ לָצֵאת, נִשְׁאֶרֶת טִפָּה אַחַת שֶׁיּוֹצֵאת בְּשֶׁקֶט, נוֹפֶלֶת בֵּינֵיהֶם, וְנַעֲשֶׂה מִמֶּנָּה יְאוֹר אֶחָד. הַיְאוֹר הַזֶּה הוּא שֶׁאָמַרְנוּ שֶׁהוֹלֵךְ כְּשֶׁהוּא שׁוֹכֵךְ.</p>\n<p>הַיְאוֹר הַזֶּה, כְּשֶׁאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, מוֹצִיא טִפּוֹת אֲחֵרוֹת גְּדוֹלוֹת (של ברכות) שֶׁל בְּרָכוֹת מִצַּד הַיָּמִין, מַה שֶּׁנִּשְׁאָר מֵאוֹתָן טִפּוֹת, נִשְׁאֶרֶת טִפָּה אַחַת שׁוֹכֶכֶת מֵאוֹתָן בְּרָכוֹת, וְנוֹפֶלֶת בְּאוֹתוֹ יְאוֹר שֶׁהוּא שׁוֹכֵךְ, וְזֶהוּ הַיְאוֹר שֶׁעָדִיף מִכֻּלָּם.</p>\n<p>כְּשֶׁיּוֹצְאִים וְנִפְרָדִים אוֹתָם אַרְבָּעָה נְהָרוֹת שֶׁיּוֹצְאִים מִגַּן עֵדֶן, אוֹתוֹ שֶׁנִּקְרָא פִּישׁוֹן נוֹפֵל בְּאוֹתוֹ יְאוֹר וְנִכְלָל בּוֹ, וְלָכֵן מַלְכוּת בָּבֶל נִכְלֶלֶת בָּזֶה, וּפִישׁוֹן הוּא מַלְכוּת בָּבֶל. מֵהַיְאוֹר הַזֶּה נִזּוֹנִים וּמִתְמַלְּאִים כָּל אוֹתָם הַיְאוֹרִים הָאֲחֵרִים.</p>\n<p>בְּכָל יְאוֹר וִיאוֹר הוֹלֵךְ וְשָׁט תַּנִּין אֶחָד, וְהֵם תִּשְׁעָה, וְכָל אֶחָד וְאֶחָד נוֹקֵב נֶקֶב בְּרֹאשׁוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים עד) שִׁבַּרְתָּ רָאשֵׁי תַנִּינִים וְגוֹ'. וַאֲפִלּוּ הַתַּנִּין הַגָּדוֹל הַזֶּה כָּךְ הוּא, מִשּׁוּם שֶׁכֻּלָּם נוֹפְחִים רוּחוֹת לְמַעְלָה וְלֹא לְמַטָּה.</p>\n<p>כָּתוּב בְּרֵאשִׁית בָּרָא אֱלֹהִים. וְכָתוּב וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדלִים, בְּכָל מַעֲשֶׂה שֶׁל אוֹתָם עֶשֶׂר אֲמִירוֹת, עוֹמְדִים כְּנֶגְדָּם אוֹתָם עֲשָׂרָה יְאוֹרִים. וְתַנִּין אֶחָד מִתְפַּרְפֵּר (פורש) (מתרפרף) בָּרוּחַ כְּנֶגֶד כָּל אֶחָד וְאֶחָד.</p>\n<p>וְעַל זֶה אַחַת לְשִׁבְעִים שָׁנָה מִזְדַּעֲזֵעַ הָעוֹלָם, מִשּׁוּם שֶׁהַתַּנִּין הַגָּדוֹל הַזֶּה מַעֲלֶה אֶת הַסְּנַפִּירִים שֶׁלּוֹ וּמִזְדַּעֲזֵעַ, אָז כֻּלָּם מִזְדַּעְזְעִים בְּאוֹתָם יְאוֹרִים, וְכָל הָעוֹלָם מִזְדַּעֲזֵעַ, וְהָאָרֶץ מִתְחַלְחֶלֶת, וְכֻלָּם כְּלוּלִים בַּתַּנִּין הַגָּדוֹל הַזֶּה.</p>\n<p>וְהָאָרֶץ הָיְתָה תֹהוּ וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, בְּמַעֲשֵׂה בְרֵאשִׁית הַחֲבֵרִים עוֹסְקִים בּוֹ וְיוֹדְעִים בּוֹ, אֲבָל הֵם מְעַטִּים שֶׁיּוֹדְעִים אֶת רֶמֶז מַעֲשֵׂה בְרֵאשִׁית בְּסוֹד הַתַּנִּין הַגָּדוֹל. וְעַל זֶה שָׁנִינוּ, שֶׁכָּל הָעוֹלָם אֵינוֹ מִשְׁתַּלְשֵׁל אֶלָּא עַל סְנַפִּירָיו שֶׁל זֶה.</p>\n<p>בֹּא רְאֵה, וְהָאָרֶץ הָיְתָה תֹהוּ וָבהוּ וְגוֹ'. שָׁנִינוּ הָיְתָה, וּבֵאַרְנוּ. מִשּׁוּם שֶׁבַּיְאוֹר הָרִאשׁוֹן הַזֶּה שֶׁאָמַרְנוּ, כְּשֶׁהַתַּנִּין הַגָּדוֹל הַזֶּה נִכְנָס בּוֹ, אָז מִתְמַלֵּא, וְשׁוֹטֵף וְדוֹעֵךְ הַנִּיצוֹצוֹת שֶׁנִּלְקְטוּ בְּאוֹתָן עוֹלָמוֹת שֶׁנֶּחְרְבוּ בַּתְּחִלָּה.</p>\n<p>אוֹתָם תַּנִּינִים אֲחֵרִים שֶׁאָמַרְנוּ הָיוּ וְלֹא הָיוּ, לָמָּה? מִשּׁוּם שֶׁנֶּחֱלַשׁ כֹּחָם שֶׁלֹּא יַחֲרִיבוּ הָעוֹלָם, פְּרָט לְשִׁבְעִים שָׁנָה פַּעַם אַחַת, וְהֵם מִתְחַזְּקִים בְּכֹחַ הַתַּנִּין הַגָּדוֹל הַהוּא, וְהוּא לְבַדּוֹ מִתְחַזֵּק, וְאִלְמָלֵא נְקֵבָתוֹ הָיְתָה קַיֶּמֶת אֶצְלוֹ, לֹא יָכוֹל הָיָה הָעוֹלָם לִסְבֹּל אוֹתָם. (ומשום כך)</p>\n<p>עַד שֶׁלֹּא הָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְּקֵבָה, הָאָרֶץ הָיְתָה תֹהוּ (ובהו). תֹּהוּ הָיְתָה. וְאַחַר שֶׁהָרַג אוֹתָהּ הָיְתָה בּהוּ, הִתְחִילָה לְהִתְקַיֵּם. וְחֹשֶׁךְ עַל. עֲדַיִן לֹא הָיָה מֵאִיר הַמַּעֲשֶׂה שֶׁעָשָׂה.</p>\n<p>מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? מָחַץ אֶת רֹאשׁ הַזָּכָר לְמַעְלָה וְנִכְפָּה, מִשּׁוּם שֶׁהֲרֵי הַתְּהוֹם לְמַטָּה לֹא הָיָה מֵאִיר. מָה הַטַּעַם לֹא הָיָה מֵאִיר? מִשּׁוּם שֶׁהַתַּנִּין הַגָּדוֹל הַזֶּה הָיָה מְנַשֵּׁב רוּחַ עַל הַתְּהוֹם וּמַחֲשִׁיךְ אוֹתוֹ, וְלֹא הָיָה מְרַחֵף לְמַטָּה.</p>\n<p>וְעָבְרָה (ועם כל זה) רוּחַ אַחֶרֶת שֶׁלְּמַעְלָה, וְנָשְׁבָה (שגשבה) וְהִכְּתָה בְּאוֹתָהּ רוּחַ וְהִשְׁקִיטָה אוֹתָהּ, זֶהוּ שֶׁכָּתוּב וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם. וְזֶהוּ מַה שֶּׁשָּׁנִינוּ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִכָּה רוּחַ בְּרוּחַ וּבָרָא אֶת הָעוֹלָם.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. הֵאִיר הָאוֹר שֶׁלְּמַעְלָה וְהִכָּה עַל גַּב הָרוּחַ שֶׁנָּשְׁבָה, וְהִסְתַּלֵּק מֵעַל הַתְּהוֹם וְלֹא כִסָּה אוֹתוֹ. כֵּיוָן שֶׁהֵאִיר הַתְּהוֹם וְהוּא הִסְתַּלֵּק, אָז הָיָה אוֹר.</p>\n<p>זְהִ מֵאִיר עַל רֹאשׁוֹ, וּמַיִם הָיוּ יוֹצְאִים מִתּוֹךְ מִצְחוֹ, וְרוּחַ נוֹשֶׁבֶת לְמַעְלָה וּמְאִירָה מֵאוֹר זֶה, עַד שֶׁהָיָה יוֹרֵד אוֹרוֹ, מְנַצְנֵץ לְשִׁבְעִים וּשְׁנַיִם אוֹרוֹת שֶׁל הַשֶּׁמֶשׁ. כֵּיוָן שֶׁאוֹתָם אוֹרוֹת נִרְשְׁמוּ בְּתוֹךְ הַשֶּׁמֶשׁ לְמַטָּה, הָיוּ הָרְשָׁעִים שֶׁל הָעוֹלָם יוֹדְעִים בָּהֶם וְהָיוּ עוֹבְדִים לַשֶּׁמֶשׁ. כֵּיוָן שֶׁהִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָם הָרְשָׁעִים, סִלֵּק אֶת אוֹרוֹ וְגָנַז אוֹתוֹ. לָמָּה גָּנַז אוֹתוֹ? מִשּׁוּם שֶׁאוֹתוֹ תַּנִּין הָיָה עוֹלֶה וְיוֹרֵד וּמַכֶּה בְּאוֹתָם יְאוֹרִים, עַד שֶׁגָּנַז אוֹתוֹ וְלֹא הִתְגַּלָּה.</p>\n<p>וְזָרַע אוֹתוֹ הַזֶּרַע בְּצַדִּיק, שֶׁהוּא הַגַּנָּן שֶׁל הַגָּן, וְהַזֶּרַע שֶׁנִּזְרַע בַּגָּן הוּא גְּנִיזַת וּטְמִינַת (זה) שֶׁל הָאוֹר הַזֶּה הוּא.</p>\n<p>כְּשֶׁהַתַּנִּין הַגָּדוֹל הַזֶּה רוֹאֶה שֶׁצּוֹמֵחַ בַּגָּן זֶרַע שֶׁל אוֹר זֶה, אָז מִתְעוֹרֵר לַצַּד הָאַחֵר לְאוֹתוֹ נָהָר שֶׁנִּקְרָא גִיחוֹן. וְנֶחְלָקִים מֵימֵי הַגִּיחוֹן הַזֶּה, שְׁבִיל אֶחָד שֶׁלּוֹ, הוּא הוֹלֵךְ לְתוֹךְ אוֹתוֹ זֶרַע שֶׁצָּמַח בְּתוֹךְ הַגָּן, וּמֵאִיר בּוֹ בְּגֹדֶל הַזֶּרַע הַזֶּה, וְנִקְרָא גִיחוֹן.</p>\n<p>וּמִתּוֹךְ גַּדְלוּת שֶׁל אוֹתוֹ הַזֶּרַע עָלָה לִגְדֻלָּה שְׁלֹמֹה הַמֶּלֶךְ, כְּשֶׁעָלָה לַמַּלְכוּת, שֶׁכָּתוּב (מלכים א א) וְהוֹרַדְתֶּם אֹתוֹ אֶל גִּחוֹן, וְכָתוּב וּמָשַׁח אֹתוֹ שָׁם. שָׁם, וְלֹא בְּמָקוֹם אַחֵר, מִשּׁוּם שֶׁאֶת זֶה יָדַע דָּוִד הַמֶּלֶךְ, וּמֵימָיו הָאֲחֵרִים עָלוּ לְמַלְכוּת אַחֶרֶת, וְזֶהוּ הַמֶּלֶךְ שֶׁהוּא תַּקִּיף.</p>\n<p>וְהַתַּנִּין הַגָּדוֹל הַזֶּה הִתְעוֹרֵר אֵלָיו, וְהִתְעַלּוּ סְנַפִּירָיו שֶׁל הַתַּנִּין הַזֶּה בְּאוֹתוֹ נָהָר לְהִתְחַזֵּק בּוֹ, וְכָל אוֹתָם שְׁאָר הַיְאוֹרִים עוֹלִים וְיוֹרְדִים בְּתָקְפּוֹ שֶׁל הַתַּנִּין הַגָּדוֹל הַזֶּה, וּמִשְׁתּוֹקֵק וְנִכְנָס לְתוֹךְ יְאוֹר הַשָּׁקֵט וְשׁוֹכֵךְ בּוֹ.</p>\n<p>וְאָז, כְּשֶׁאוֹתוֹ אוֹר נִגְנָז (להסיעו) לְהַעֲלוֹתוֹ אוֹתוֹ גַנָּן שֶׁאָמַרְנוּ, אָז יוֹצֵא הַחֹשֶׁךְ הָרִאשׁוֹן וּמַכֶּה עַל רֹאשׁוֹ בְּאוֹתוֹ נֶקֶב שֶׁנַּעֲשָׂה בּוֹ, וְנִפְרָד חוּט אֶחָד בֵּין אוֹתוֹ הָאוֹר שֶׁל הָאוֹר הַזֶּה שֶׁנִּגְנָז, וּבֵין אוֹתָהּ חֲשֵׁכָה שֶׁל הַחֹשֶׁךְ הַזֶּה, שֶׁכָּתוּב (בראשית א) וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ.</p>\n<p>הַתַּנִּין הַזֶּה שָׁב בְּאוֹתָהּ הַפְרָדָה שֶׁל הַחוּט שֶׁהִפְרִיד, וְהִפְרִיד אֶת אוֹתָם (בין אותם) יְאוֹרִים לְתוֹךְ הַחֲשֵׁכָה, וְנִפְרָדִים דָּגִים לְמִינֵיהֶם אֵלֶּה מֵאֵלֶּה בְּאוֹתָהּ הַפְרָדָה.</p>\n<p>וּכְשֶׁנִּפְרְדוּ הַמַּיִם הָעֶלְיוֹנִים הַקְּדוֹשִׁים, כָּל אוֹתָם הַיְאוֹרִים נִפְרָדִים, וְנִכְנְסוּ לְתוֹךְ אוֹתוֹ הַיְאוֹר הַשָּׁקֵט שֶׁנִּבְחָר מִכֻּלָּם, וְיוֹצְאִים וְנִכְנָסִים בּוֹ שָׁלֹשׁ פְּעָמִים בְּיוֹם.</p>\n<p>וְכָל אוֹתָם דָּגִים שֶׁגְּדֵלִים תּוֹךְ אוֹתָם יְאוֹרִים, נִפְרָדִים אֵלֶּה מֵאֵלֶּה, וְנִקְרָאִים לֵילוֹת, וְאֵלֶּה הֵם רָאשִׁים לְכָל אוֹתָם דָּגִים שֶׁיּוֹצְאִים הַחוּצָה, וְאֵלֶּה שׁוֹלְטִים עַל כֻּלָּם, וְאֵלֶּה נִקְרָאִים בְּכוֹרֵי מִצְרַיִם. וּמִכָּאן הִתְפַּזְּרוּ הַחוּצָה הַבְּכוֹרִים, וְכֻלָּם נִזּוֹנִים מֵהַשְׁקָאַת אוֹתָם יְאוֹרִים. וְהַתַּנִּין הַגָּדוֹל הַזֶּה שׁוֹלֵט עַל כֻּלָּם.</p>\n<p>וְהַסֹל בְּהַבְדָּלַת הַמַּיִם הָעֶלְיוֹנִים, שֶׁכָּתוּב וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם, וְנִרְשְׁמוּ מַיִם הַקְּדוֹשִׁים הָעֶלְיוֹנִים וְנִפְרְדוּ לְמַעְלָה, וְהַמַּיִם הַתַּחְתּוֹנִים, נִפְרְדוּ כֻלָּם אֵלֶּה מֵאֵלֶּה, קְדוֹשִׁים וְשֶׁלֹּא קְדוֹשִׁים, וְעַל זֶה נִקְרְאוּ מַלְאָכִים עֶלְיוֹנִים פְּרוּדִים, מִשּׁוּם שֶׁנִּפְרְדוּ אֵלֶּה מֵאֵלֶּה לְמִינֵיהֶם.</p>\n<p>וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע. סוֹד זֶה, כְּשֶׁהַתַּנִּין הַגָּדוֹל הָיָה מְנַשֵּׁב רוּחַ בְּאוֹתוֹ נֶקֶב וּמְרַחֵף כְּלַפֵּי מַעְלָה, אֶת כָּל אוֹתָם הָעֲשָׂבִים הָיָה הוֹפֵךְ אוֹתָם לְיֹבֶשׁ, עַד שֶׁרוּחַ אַחֶרֶת נוֹשֶׁבֶת בְּאוֹתָהּ רוּחַ וּמַשְׁקִיטָה אוֹתָהּ לְמַטָּה, וְהָעֲשָׂבִים צָמְחוּ כְּבַתְּחִלָּה, וְשׁוֹלְטִים וּמְשַׁבְּחִים וּמוֹדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מִצַד שְׂמֹאל וּלְתוֹךְ הַיְאוֹר הַשָּׁקֵט יוֹצְאוֹת בְּהֵמוֹת לְמִינֵיהֶן, וְהוֹלְכִים לְהִתְקָרֵב לְאוֹתָם עֲשָׂבִים וְלֹא יְכוֹלִים, וְשָׁבִים לִמְקוֹמָם. כָּל הַיְאוֹרִים הַלָּלוּ הוֹלְכִים וְשָׁטִים עִם אוֹתוֹ הַתַּנִּין שֶׁשּׁוֹלְטִים בָּהֶם, וּמַקִּיפִים אֶת אוֹתָם הָעֲשָׂבִים וְלֹא יְכוֹלִים, פְּרָט לִפְעָמִים שֶׁרוּחַ עֶלְיוֹנָה אֵינָהּ נוֹשֶׁבֶת, וְהִיא מְרַחֶפֶת הָרוּחַ בְּאוֹתוֹ הַנֶּקֶב שֶׁלְּמַעְלָה, כְּמוֹ שֶׁבֵּאַרְנוּ, וְאָז שׁוֹלֶטֶת אוֹתָהּ הָרוּחַ עַל אוֹתָם עֲשָׂבִים.</p>\n<p>וְהַיְאוֹר הַשָּׁקֵט שָׁב לִמְקוֹמוֹ, וְעוֹלֶה וְיוֹרֵד. וּמִשּׁוּם שֶׁמֵּימָיו שְׁקֵטִים, הוֹלֵךְ בְּשֶׁקֶט. וְהַתַּנִּים הַגָּדוֹל הַזֶּה עוֹלֶה לְאוֹתָם יְאוֹרִים, וְכָל הָעֲשָׂבִים מִתְגַּדְּלִים סְבִיב אוֹתוֹ הַיְאוֹר הַשָּׁקֵט, וְאֵלֶּה (והם) גְּדֵלִים בְּכָל עֵבֶר, וְאָז עוֹלֶה אוֹתוֹ תַּנִּין וּמִתְגַּדֵּל בֵּינֵיהֶם, וְשָׁב אֶל כָּל אוֹתָם יְאוֹרִים.</p>\n<p>וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם. זֶהוּ נָחָשׁ בָּרִיחַ. לָמָּה בָּרִיחַ? מִשּׁוּם שֶׁסּוֹגֵר אֶת שְׁנֵי הַצְּדָדִים, וְלֹא יוֹצֵא לְעוֹלָמִים, אֶלָּא פַּעַם אַחַת בַּיּוֹבֵל.</p>\n<p>וּבְסִפְרֵי הָרִאשׁוֹנִים, זֶה נָחָשׁ עֲקַלָּתוֹן, שֶׁהוּא תָּמִיד בְּעַקְמִימוּת, וּמֵבִיא קְלָלוֹת עַל הָעוֹלָם. כְּשֶׁזֶּה קָם - נִשְׁבָּר תָּקְפּוֹ שֶׁל אוֹתוֹ הַתַּנִּין, וְלֹא יָכוֹל לַעֲמֹד עַד שֶׁאוֹבֵד גּוּפוֹ, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא כּוֹפֵף אוֹתוֹ לְתוֹךְ הַיָּם כְּשֶׁנִּכְנָס אֵלָיו, וְהוּא דּוֹרֵךְ עַל תָּקְפּוֹ שֶׁל הַיָּם, וְתֹקֶף הַיָּם הַזֶּה הוּא תַּנִּין, כְּמוֹ שֶׁנֶּאֱמַר (איוב ט) וְדוֹרֵךְ עַל בָּמֳתֵי יָם.</p>\n<p>וּכְשֶׁקָּם הַנָּחָשׁ הַזֶּה, אָז מַה כָּתוּב? (ישעיהנו) וְהָרַג אֶת הַתַּנִּין אֲשֶׁר בַּיָּם. זֶהוּ הַתַּנִּין הַגָּדוֹל. וְעַל זֶה כָּתוּב הִנְנִי עָלֶיךְ. וְנָחָשׁ זֶה הוּא מְאֹרֹת, בִּקְלָלוֹת לַכֹּל, מִשּׁוּם שֶׁהוּא חָזָק עָלָיו בְּחָזְקוֹ שֶׁל אוֹתוֹ הַנָּהָר הַגָּדוֹל שֶׁנִּקְרָא חִדֶּקֶל, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>אוֹתוֹ הַנָּחָשׁ שֶׁבַּיַּבָּשָׁה, כְּשֶׁיּוֹצְאִים (להלחם) זֶה בָּזֶה, אוֹתוֹ שֶׁבַּיַּבָּשָׁה תָּמִיד מִתְגַּבֵּר, מִשּׁוּם שֶׁכָּל דַּרְכּוֹ וְחָזְקוֹ הוּא בַּיַּבָּשָׁה, וְאוֹכֵל אֶרֶץ וְעָפָר תָּמִיד, כְּמוֹ שֶׁנֶּאֱמַר וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ. זֶה גָּדֵל בֶּעָפָר, וְזֶה גָּדֵל בַּמַּיִם. נָחָשׁ שֶׁהִתְגַּדֵּל בְּמַיִם לֹא חָזָק כְּזֶה שֶׁהִתְגַּדֵּל בַּיַּבָּשָׁה, וְעַל זֶה כָּתוּב מְאֹרֹת חָסֵר.</p>\n<p>וְזְהִ הִזְדַּמֵּן לְאוֹתוֹ שֶׁל הַמַּיִם. וְאַף עַל גַּב (וזה לא) שֶׁהִזְדַּמֵּן אֵלָיו, לֹא נִלְחַם בּוֹ, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ שֶׁהָרַג אוֹתוֹ מִתּוֹךְ הַיָּם, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁבִּגְלַל גַּסּוּת הָרוּחַ שֶׁבּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל כט) אֲשֶׁר אָמַר לִי יְאֹרִי וְגוֹ'.</p>"],[9522011586,"<p>וְעָבַר ה' לִנְגֹּף אֶת מִצְרַיִם וְגוֹ'. שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, פָּסוּק זֶה קָשֶׁה, וְכִי יִרְאֶה אֶת הַדָּם וְאַחַר כָּךְ וּפָסַח, שֶׁמַּשְׁמָע שֶׁסִּימָן הוּא עָשָׂה? וְאִם תֹּאמַר בִּשְׁבִיל הַדָּם שֶׁהוּא מִצְוָה, אָז לָמָּה בַּחוּץ? וְלָמָּה בִּשְׁלֹשָׁה מְקוֹמוֹת שֶׁל הַפֶּתַח, וַהֲרֵי כָּתוּב (דניאל ב) הוּא מְגַלֶּה עֲמֻקּוֹת וְגוֹ', וּמָה הַטַּעַם שֶׁרָצָה לִהְיוֹת דָּם גָּלוּי עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזוֹת?</p>\n<p>אֶלָּא שָׁנִינוּ, כָּתוּב (דברים לב) וַיַּרְא ה' וַיִּנְאָץ, וְכָתוּב (בראשית ו) וַיַּרְא ה' כִּי רַבָּה רָעַת הָאָדָם בָּאָרֶץ. וְשָׁנִינוּ, לֹא נִרְאֵית הַהַשְׁגָּחָה הָעֶלְיוֹנָה אֶלָּא כְּשֶׁנִּרְאִים לְמַטָּה הַמַּעֲשִׂים שֶׁנַּעֲשׂוּ מַעֲשֶׂה מִמֶּנּוּ, וְעַל זֶה (ועד שעושים מעשה למטה) לֹא מַשְׁגִּיחִים לְהָרַע, פְּרָט לַהִרְהוּר שֶׁל עֲבוֹדָה זָרָה, שֶׁכָּתוּב (דברים א) הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה לְבַבְכֶם. וּמִשֶּׁנַּעֲשָּׂה הַמַּעֲשֶׂה, מִתְעוֹרֶרֶת הַהַשְׁגָּחָה מִלְמַעְלָה, וְלָכֵן הַכֹּל, בֵּין לְטוֹב בֵּין לְרַע, תָּלוּי הַדָּבָר בַּמַּעֲשֶׂה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּל שׁוּקֵי מִצְרַיִם הָיוּ מְלֵאִים אֱלִילִים, וְעוֹד, שֶׁבְּכָל בַּיִת וּבַיִת הָיוּ מְצוּיִים מִינִים שֶׁנִּקְשָׁרִים בְּכִשְׁפֵיהֶם בְּאוֹתָם כְּתָרִים תַּחְתּוֹנִים שֶׁלְּמַטָּה, וּמְעוֹרְרִים רוּחַ טֻמְאָה בְּתוֹכָם.</p>\n<p>וְסוֹד הַדָּבָר לָמַדְנוּ, כָּתוּב וּלְקַחְתֶּם אֲגֻדַּת אֵזוֹב וּטְבַלְתֶּם בַּדָּם אֲשֶׁר בַּסַּף וְהִגַּעְתֶּם אֶל הַמַּשְׁקוֹף וְאֶל שְׁתֵּי הַמְּזוּזת. אֲגֻדַּת אֵזוֹב לָמָּה? כְּדֵי לְבַעֵר רוּחַ טֻמְאָה מִבֵּינֵיהֶם, (זה הפסוק קשה, וכי וראה את הדם ואחר כך ופסח, שמשמע שסימן הוא שעשה, מדוע, ' והרי הכל גלוי לפני הקדוש ברוך הוא, וכתוב (דניאל ב) הוא מגלהעמקות ונסתרות. אלא שנינו, כתוב וירא ה' וינאץ וגו', וכתוב וירא ה' כי רבה רעת וגו'. ושנינו, לא מתראה השגחה למעלה, אלא כאשר נראה למטה מעשה, ומשגעשה מעשה ההשגחה למעלה מתעוררת, ומפני כן הכל, בין לטובה ובין לרעה, במעשה תלוי הדבר. ולקחתם אגדת אזוב וגו'. אגדת אזוב למה, ' ומה הטעם רצה שיתגלה דם על המשקוף ועל שתי המזוזות, אמר רבי יוסי, כל השוקים במצרים היו מלאים אלילים, ובכל בית ובית היו נמצאים מינים שמקטירים בכשפיהם באותם כתרים תחתונים שלמטה ומעוררים רוח טמאה אצלם, ועל זה אגדת אזוב, כדי לבער רוחות מביניהם) וּלְהַרְאוֹת בְּפִתְחֵיהֶם בִּשְׁלֹשֶׁת הַמְּקוֹמוֹת הַלָּלוּ הָאֱמוּנָה הַשְּׁלֵמָה. אֶחָד כָּאן, וְאֶחָד כָּאן, וְאֶחָד בֵּינֵיהֶם. וְלָכֵן וּפָסַח ה' עַל הַפֶּתַח וְלֹא יִתֵּן הַמַּשְׁחִית לָבֹא אֶל בָּתֵּיכֶם לִנְגֹּף, מִשּׁוּם שֶׁרוֹאֶה אֶת הַשִּׁםִ הַקָּדוֹשׁ רָשׁוּם עַל הַפֶּתַח.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם כָּךְ אָז לְשֵׁם מָה דָּם, שֶׁהֲרֵי שָׁנִינוּ, לָבָן וְאָדם וְאֶחָד שֶׁכָּלוּל בֵּין הַגְּוָנִים? אָמַר לוֹ, שְׁנֵי דָמִים הָיוּ, אֶחָד שֶׁל מִילָה וְאֶחָד שֶׁל פֶּסַח. שֶׁל מִילָה רַחֲמִים, וְשֶׁל פֶּסַח דִּין.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לֹא כָּךְ, אֶלָּא כְּמוֹ שֶׁלָּמַדְנוּ, שֶׁהֶחֱזִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתוֹ דָּם לְרַחֲמִים, כְּאִלּוּ הָיוּ לָבָן בְּתוֹךְ הַגְּוָנִים. זֶהוּ שֶׁכָּתוּב (יחזקאל טז) וָאֶעֱבֹר עָלַיִךְ וָאֶרְאֵךְ מִתְבּוֹסֶסֶת בְּדָמָיִךְ וָאֹמַר לָךָּ בְּדָמַיִךְ חֲיִי וְגוֹ'. וְאַף עַל גַּב שֶׁהָיָה אָדם, הָחְזַר לְרַחֲמִים, שֶׁכָּתוּב בְּדָמַיִךְ חֲיִי. וְלָכֵן רָשׁוּם הַפֶּתַח בִּשְׁלֹשָׁה צְדָדִים - אֶחָד כָּאן, וְאֶחָד כָּאן, וְאֶחָד בֵּינֵיהֶם.</p>\n<p>שָׁנָה רַבִּי חִזְקִיָּה, שְׁנֵי דָמִים נִרְאוּ כְּנֶגֶד שְׁנֵי כְתָרִים שֶׁנִּרְאוּ (שהתעוררו) למעלה באותה שעה. אמר רבי יוסי, כתר אחד שכלול בשני צדדים טמונים, ברחמים ודין.</p>\n<p>כְּתֹב אֶת שְׁמִי וְשִׂים אוֹתוֹ בַּפֶּתַח שֶׁלְּךְ, וְאַתָּה שָׁרוּי בְּתוֹךְ הַבַּיִת, וַאֲנִי יוֹשֵׁב מִחוּץ לַפֶּתַח לִשְׁמֹר אוֹתְךְ. וְכָאן אָמַר: רְשֹׁם עַל הַפֶּתַח אֶת סוֹד הָאֱמוּנָה שֶׁלִּי, וְאַתָּה שָׁרוּי בְּתוֹךְ הַבַּיִת, וַאֲנִי שׁוֹמֵר אוֹתְךְ מִבַּחוּץ, שֶׁכָּתוּב וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר, וְכָתוּב וְרָאָה אֶת הַדָּם עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזֹת וּפָסַח ה' עַל הַפֶּתַח וְלֹא יִתֵּן הַמַּשְׁחִית לָבֹא אֶל בָּתֵּיכֶם לִנְגֹּף.</p>\n<p>עוֹד אָמַר רַבִּי אַבָּא, כְּמוֹ הַשֵּׁם הַקָּדוֹשׁ עָשׂוּ בְּאוֹתָהּ שָׁעָה. מָה הַשֵּׁם הַקָּדוֹשׁ ה חָזַר בְּאוֹתָהּ שָׁעָה לְדִין, אַף כָּךְ חָזַר דָּם זֶה בְּשָׁעָה זוֹ לְדִין, שֶׁכָּתוּב וְרָאָה אֶת הַדָּם עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזת. רשֶׁם שֶׁל כֻּלָּם אָדם, לְהֵרָאוֹת שֶׁהֲרֵי חָזַר לִהְיוֹת דִּין לַעֲשׂוֹת נְקָמוֹת.</p>\n<p>וְסוֹד הַדָּבָר - כְּמוֹ שֶׁהוּא לְמַעְלָה בְּאוֹתָהּ שָׁעָה, כְּשֶׁרוֹצֶה לְהֵרָאוֹת לְמַטָּה, אִם רַחֲמִים - רַחֲמִים, וְאִם דִּין - דִּין. זֶהוּ שֶׁכָּתוּב וּטְבַלְתֶּם בַּדָּם אֲשֶׁר בַּסַּף וְהִגַּעְתֶּם וְגוֹ'. וְלֶעָתִיד לָבֹא כָּתוּב, (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה. שֶׁעָתִיד לְהַרְאוֹת (להחזיר) כֻּלָּם דִּין לַעֲשׂוֹת נְקָמוֹת.</p>\n<p>וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר. מָה הַטַּעַם? מִשּׁוּם שֶׁשָּׁנִינוּ, אָמַר רַבִּי יִצְחָק (אמר רבי ירמיה), לֹא צָרִיךְ לָאָדָם לָלֶכֶת בַּשּׁוּק וּלְהִמָּצֵא בַּשּׁוּק בִּזְמַן שֶׁהַדִּין תָּלוּי בָּעִיר, שֶׁכֵּיוָן שֶׁנִּתְּנָה רְשׁוּת לַמַּשְׁחִית - מִי שֶׁפּוֹגֵשׁ אוֹתוֹ, נִזָּק. וְכָאן מִשּׁוּם שֶׁהַדִּין נִמְצָא, לֹא צָרִיךְ לָצֵאת בַּחוּץ.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, בְּאוֹתוֹ מַמָּשׁ שֶׁנִּמְצָא דִּין לְמִצְרַיִם, בְּאוֹתוֹ מַמָּשׁ נִמְצָא דִּין לְיִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב וְרָאִיתִי אֶת הַדָּם וּפָסַחְתִּי עֲלֵיכֶם. וְכֵן שָׁנִינוּ, בְּכָל אוֹתָם כְּתָרִים קְדוֹשִׁים שֶׁלְּמַעְלָה - כְּמוֹ שֶׁנִּמְצָא דִּין, נִמְצָאִים רַחֲמִים, וְהַכֹּל בְּשָׁעָה אַחַת. שָׁנָה רַבִּי חִזְקִיָּה, כָּתוּב (שם יט) וְנָגַף ה' אֶת מִצְרַיִם נָגֹף וְרָפוֹא. נָגֹף לְמִצְרַיִם, וְרָפוֹא לְיִשְׂרָאֵל. מַה זֶּה וְרָפוֹא? מִמַּה שֶּׁנִּמּוֹלוּ צְרִיכִים רְפוּאָה.</p>\n<p>וְשָׁנִינוּ, בְּאוֹתָהּ שָׁעָה שֶׁנִּגְּפוּ הַמִּצְרִים, בְּאוֹתָהּ שָׁעָה נִתְרַפְּאוּ יִשְׂרָאֵל. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יוֹסֵי, מַה שֶּׁכָּתוּב וּפָסַח ה' עַל הַפֶּתַח, מַה זֶּה עַל הַפֶּתַח? וּפָסַח ה' עֲלֵיכֶם הִצְטָרֵךְ הָיָה צָרִיךְ (לכתב) ! אֲבָל עַל הַפֶּתַח, עַל הַפֶּתַח מַמָּשׁ, זֶהוּ פֶּתַח הַגּוּף. וְאֵיזֶהוּ פֶּתַח הַגּוּף? הֱוֵי אוֹמֵר זוֹ מִילָה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בְּשָׁעָה שֶׁנֶּחֱלָק הַלַּיְלָה, וְהַכֶּתֶר הַקָּדוֹשׁ מִתְעוֹרֵר אֵלֶיהָ (מתערב בו) הַזָּכָר. וּמִי הַזָּכָר? חֶסֶד עֶלְיוֹן, שֶׁמַּשְׁמָע שֶׁזֶּה בְּלִי זֶה לֹא עוֹלֶה, וּבִשְׁבִיל זֶה, זֶה מַכֶּה וְזֶה מְרַפֵּא, וְהַכֹּל בְּשָׁעָה אַחַת.</p>\n<p>וְכָתוּב וּפָסַח עַל הַפֶּתַח, הַיָּדוּעַ. מַה זֶּה הַפֶּתַח? מִשּׁוּם שֶׁהוּא פֶּתַח וּמְשִׁיכַת הָרוּחַ וְהַגּוּף. וּבא רְאֵה, עַד שֶׁלֹּא נִמּוֹל אַבְרָהָם, הָיָה אָטוּם וְסָתוּם מִכָּל צְדָדָיו. מִשֶּׁנִּמּוֹל נִפְתַּח מֵהַכֹּל, וְלֹא הָיָה אָטוּם וְסָתוּם כְּמוֹ בַּתְּחִלָּה.</p>\n<p>וְהַיְנוּ הַסּוֹד שֶׁשָּׁנִינוּ (בראשית יח) וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל, מִשּׁוּם שֶׁהִתְגַּלְּתָה יוֹ\"ד. מַה זֶּה אוֹמֵר? אֶלָּא, אָמַר רַבִּי יִצְחָק, שֶׁהוּא הִשְׁרָה בְּגִלּוּי זֶה חֶסֶד בְּצֶדֶק, וְזֶהוּ פֶּתַח שֶׁל מִשְׁכָּן הָעֶלְיוֹן הַקָּדוֹשׁ, מַשְׁמָע שֶׁכָּתוּב הָאֹהֶל, הָאֹהֶל הַיָּדוּעַ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כְּשֶׁהִתְגַּלְּתָה הַיּוֹ\"ד הַזּוֹ, הִתְבַּשֵּׂר (התבסם) וְהִתְבָּרֵךְ בְּפֶתַח הָאֹהֶל, שֶׁהִיא צֶדֶק, לְהִתְבַּסֵּם בְּחֶסֶ\"ד. זֶהוּ שֶׁכָּתוּב כְּחֹם הַיּוֹם, שֶׁהוּא שָׁעָה שֶׁשּׁוֹלֵט הַחֶסֶד, חֶלְקוֹ שֶׁל אַבְרָהָם. וּמִנַּיִן לָנוּ שֶׁפֶּתַח הָאֹהֶל הַזֶּה הִתְבַּשֵּׂם כְּנֶגֶד אַבְרָהָם? שֶׁכָּתוּב וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. שֶׁהִתְבַּשֵּׂם בְּחֶסֶ\"ד מִשֶּׁהִתְגַּלְּתָה הַיּוֹ\"ד.</p>\n<p>אָמַר רַבִּי אַבָּא, וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל, כְּמוֹ שֶׁכָּתוּב (שם כד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. שֶׁזֶּהוּ הַפֶּתַח הַקָּדוֹשׁ, כֶּתֶר עֲשִׂירִי. כְּחֹם הַיּוֹם, כְּמוֹ שֶׁנִּתַּן לוֹ כֶּתֶר שֶׁל חֶסֶד. זֶהוּ שֶׁכָּתוּב כְּחֹם הַיּוֹם. כְּמוֹ שֶׁיָּשַׁב בָּזֶה, יָשַׁב בָּזֶה, שֶׁלֹּא עוֹלֶה זֶה בְּלִי זֶה.</p>\n<p>דָּבָר אַחֵר וְעָבַר ה' לִנְגֹּף אֶת מִצְרַיִם, מַה זֶּה וְעָבַר? שֶׁעָבַר עַל שׁוּרַת הַדִּין שֶׁל הַכְּתָרִים, (שקשרים) שֶׁהָיוּ מִתְקַשְּׁרִים בִּכְתָרִים אֲחֵרִים שֶׁלְּמַעְלָה, וְהִתִּיר אוֹתָם מִקִּיּוּמָם, וְעָבַר עַל דְּרָכָיו כְּדֵי לַעֲשׂוֹת בָּהֶם דִּין וְלִשְׁמֹר עַל יִשְׂרָאֵל. וְכֵן הוּא, כָּל וְעָבַר, וְעָבַרְתִּי, וַיַּעֲבֹר - שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָבַר עַל כָּל דְּרָכָיו אוֹ לְדִין אוֹ לְרַחֲמִים. כָּאן וְעָבַר, כְּדֵי לַעֲשׂוֹת דִּין. שָׁם וַיַּעֲבֹר, כְּדֵי לְרַחֵם.</p>"],[9522011587,"<p>וַיְהִי בַּחֲצִי הַלַּיְלָה וַה' הִכָּה כָּל בְּכוֹר וְגוֹ'. (כתוב (תהלים סט) ואני תפלתי לך ה' עת רצון וגו') רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים מֵאוּשָׁא לְלוֹד, וְהָיָה רַבִּי חִיָּיא רוֹכֵב בַּחֲמוֹר. אָמַר רַבִּי יוֹסֵי, נֵשֵׁב כָּאן וְנִתְפַּלֵּל, שֶׁהֲרֵי הִגִּיעַ זְמַן תְּפִלַּת מִנְחָה, וְשָׁנִינוּ, לְעוֹלָם יְהֵא אָדָם זָהִיר בִּתְפִלַּת מִנְחָה. לָמָּה זָהִיר? מִשּׁוּם שֶׁהִיא שָׁעָה שֶׁתָּלוּי הַדִּין וְצָרִיךְ אָדָם לְכַוֵּן דַּעְתּוֹ. יָרַד רַבִּי חִיָּיא וְהִתְפַּלֵּל.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, נָטָה הַשֶּׁמֶשׁ לְהִכָּנֵס. אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, לָמָּה אַתָּה שׁוֹתֵק? אָמַר רַבִּי יוֹסֵי, הָיִיתִי מִסְתַּכֵּל בְּדַעְתִּי שֶׁאֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל רָאשֵׁי הָעָם. אִם רָאשֵׁי הָעָם צַדִּיקִים - טוֹב לָעוֹלָם. וְאִם לֹא צַדִּיקִים - אוֹי לָעוֹלָם וְאוֹי לָעָם.</p>\n<p>אָמַר רַבִּי חִיָּיא, וַדַּאי כָּךְ הוּא, מִנַּיִן לָנוּ? שֶׁכָּתוּב (דברי הימים ב יח) רָאִיתִי אֶת כָּל יִשְׂרָאֵל נְפוֹצִים עַל הֶהָרִים כַּצֹּאן אֲשֶׁר אֵין לָהֶן רֹעֶה וַיֹּאמֶר ה' לֹא אֲדנִים לָאֵלֶּה יָשׁוּבוּ אִישׁ לְבֵיתוֹ בְּשָׁלוֹם. יָשׁוּבוּ, יֵשְׁבוּ הָיָה צָרִיךְ (לכתב) ! לְבֵיתוֹ, בְּבֵיתוֹ הָיָה צָרִיךְ (לכתב), שֶׁהֲרֵי בַּמָּקוֹם עוֹמְדִים!</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, אִם רֹאשׁ הָעָם לֹא זוֹכֶה, הָעָם נִתְפָּסִים בְּחֶטְאוֹ, מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיֹּאמֶר דָּוִד וְגוֹ' הִנֵּה אָנֹכִי חָטָאתִי וְאָנֹכִי הֶעֱוֵיתִי וְאֵלֶּה הַצֹּאן מֶה עָשׂוּ. (וכתוב (דברי הימים א כא) ואני הוא אשר חטאתי וגו') דָּוִד חָטָא, וְיִשְׂרָאֵל סָבְלוּ. וְאִם רֹאשׁ הָעָם נִתְפָּס בְּחֶטְאוֹ - הָעָם נִצָּל, שֶׁהֲרֵי הַדִּין לֹא שׁוֹרֶה עֲלֵיהֶם, שֶׁכָּתוּב וַיֹּאמֶר ה' לֹא אֲדנִים לָאֵלֶּה. כְּלוֹמַר, (אם אלו) אִלּוּ לֹא הָיוּ רָאשִׁים לָעָם, מִדֶּרֶךְ זוֹ יָשׁוּבוּ אִישׁ לְבֵיתוֹ בְּשָׁלוֹם. כֻּלָּם נִצּוֹלִים אִם רָאשֵׁיהֶם נִתְפָּסִים. וַאֲפִלּוּ יְהוֹשָׁפָט נִגְזַר עָלָיו לְהֵעָנֵשׁ מִשּׁוּם שֶׁהִתְחַבֵּר עִם אַחְאָב, אִם לֹא אוֹתָהּ צְוָחָה, שֶׁכָּתוּב (מלכים א כב) וַיִּזְעַק יְהוֹשָׁפָט.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, יָרַד הַלַּיְלָה. אָמְרוּ, מַה נַּעֲשֶׂה? אִם נֵלֵךְ - חָשַׁךְ הַלַּיְלָה. אִם נֵשֵׁב - פַּחַד הוּא. סָטוּ מֵהַדֶּרֶךְ וְיָשְׁבוּ תַּחַת אִילָן אֶחָד. וְיָשְׁבוּ וְהָיוּ אוֹמְרִים דִּבְרֵי תוֹרָה, וְלֹא יָשְׁנוּ.</p>\n<p>בַּחֲצוֹת הַלַּיְלָה רָאוּ אַיָּלָה אַחַת שֶׁעָבְרָה לִפְנֵיהֶם, וְהָיְתָה צוֹוַחַת וּמְרִימָה קוֹלוֹת. שָׁמְעוּ. קָמוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וְהִזְדַּעְזְעוּ. שָׁמְעוּ קוֹל אֶחָד שֶׁמַּכְרִיז וְאוֹמֵר: מִתְעוֹרְרִים קוּמוּ! יְשֵׁנִים הִתְעוֹרְרוּ! עוֹלָמוֹת הִזְדַּמְּנוּ לִפְנֵי אֲדוֹנְכֶם! (שהרי קול יוצא שכואבת האילה של מעלה ושל מטה, שכתוב (תהלים כט) קול ה' יחולל אילות ויחשף יערות) שֶׁהֲרֵי אֲדוֹנְכֶם יוֹצֵא לְגַן עֵדֶן, שֶׁהוּא הֵיכָלוֹ, לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, שֶׁכָּתוּב וּבְהֵיכָלוֹ כֻּלּוֹ אוֹמֵר כָּבוֹד.</p>\n<p>אָמַר רַבִּי חִיָּיא, עַכְשָׁו חֲצוֹת הַלַּיְלָה מַמָּשׁ, וְקוֹל זֶה הוּא הַקּוֹל שֶׁיָּצָא, וְכוֹאֶבֶת הָאַיָּלָה שֶׁל מַעְלָה וּמַטָּה, שֶׁכָּתוּב (תהלים כט) קוֹל ה' יְחוֹלֵל אַיָּלוֹת. אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לִשְׁמֹעַ אֶת זֶה!</p>\n<p>וּבֹא רְאֵה סוֹד הַדָּבָר. בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִרְאָה עַל הַגָּן, כָּל הַגָּן מִתְכַּנֵּס וְלֹא נִפְרָד מֵעֵדֶן, וּמֵהָעֵדֶן הַזֶּה יוֹצְאִים מַעְיָנוֹת לְכַמָּה דְרָכִים וּשְׁבִילִים, וְהַגַּן הַזֶּה נִקְרָא צְרוֹר הַחַיִּים, שֶׁשָּׁם מִתְעַדְּנִים הַצַּדִּיקִים מֵאוֹר שֶׁל הָעוֹלָם הַבָּא, וּבְשָׁעָה זוֹ מִתְגַּלֶּה עֲלֵיהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְשָׁנִינוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר בְּגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, כָּרוֹז יוֹצֵא וְקוֹרֵא: עוּרִי צָפוֹן וּבוֹאִי תֵימָן הָפִיחִי גַנִּי יִזְּלוּ בְשָּׂמָיו יָבא דוֹדִי לְגַנּוֹ וְיֹאכַל פְּרִי מְגָדָיו. מַהוּ וְיֹאכַל פְּרִי מְגָדָיו? אֵלּוּ קָרְבָּנוֹת שֶׁנִּקְרְבוּ לְפָנָיו מִנִּשְׁמוֹת הַצַּדִּיקִים, זֶה בַּחֲצִי הַלַּיְלָה. בִּזְמַן אַחֵר שְׁאָר קָרְבָּנוֹת מַמָּשׁ.</p>\n<p>יָשְׁבוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי. אָמַר רַבִּי יוֹסֵי, בְּכַמָּה פְעָמִים שָׁאַלְתִּי, זֶה שֶׁכָּתוּב וַיְהִי בַּחֲצִי הַלַּיְלָה וַה' הִכָּה כָּל בְּכוֹר בְּאֶרֶץ מִצְרַיִם, לָמָּה זֶה לֹא הָיָה בַּיּוֹם, שֶׁיִּתְגַּלֶּה לַכֹּל פִּרְסוּם הַנֵּס? וְלָמָּה מֵתוּ כָּל אוֹתָם חַלָּשִׁים שֶׁאַחַר הָרֵחַיִם וְאוֹתָם טְלָאִים שֶׁל בְּנֵי הַצֹּאן, וְלֹא מֵתוּ מְלָכִים וְשָׂרִים וַאֲנָשִׁים עוֹרְכֵי קְרָבוֹת כְּמוֹ שֶׁהָיָה בְּסַנְחֵרִיב, שֶׁכָּתוּב (מלכים ב יט) וַיֵּצֵא מַלְאַךְ ה' וַיַּךְ בְּמַחֲנֵה אַשּׁוּר וְגוֹ'? וְשָׁנִינוּ, כֻּלָּם מְלָכִים בְּנֵי מְלָכִים, שָׂרִים וּקְצִינִים. שָׁם נִרְאֲתָה הַגְּבוּרָה שֶׁל שָׁלִיחַ אֶחָד שֶׁלּוֹ, יוֹתֵר מִזֶּה שֶׁהָיָה רָאוּי לִהְיוֹת שֶׁלּוֹ יוֹתֵר.</p>\n<p>אָמַר לוֹ, יָפֶה שָׁאַלְתָּ, וַאֲנִי לֹא שָׁמַעְתִּי דָבָר בָּזֶה וְלֹא אֹמַר, אֲבָל הֲרֵי זָכִיתִי לְכָל זֶה, וְהַדֶּרֶךְ מְתֻקֶּנֶת לְפָנֵינוּ. אֲנִי שָׁמַעְתִּי שֶׁרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי מְטַהֵר אֶת הַשְּׁוָקִים שֶׁל טְבֶרְיָה, נֵלֵךְ אֵלָיו. יָשְׁבוּ עַד שֶׁהֵאִיר הַיּוֹם. כְּשֶׁעָלָה הָאוֹר קָמוּ וְהָלְכוּ. כְּשֶׁהִגִּיעוּ אֵלָיו, מָצְאוּ אוֹתוֹ שֶׁהָיָה יוֹשֵׁב, וְסֵפֶר הָאַגָּדָה בְּיָדוֹ.</p>\n<p>פָּתַח וְאָמַר, (ישעיה מ) כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ. כֵּיוָן שֶׁאָמַר כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ, לָמָּה כָּתוּב מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ? אֶלָּא לָמַדְנוּ, דַּעְתָּם שֶׁל כָּל עַמֵּי הָעוֹלָם, שֶׁאֱמוּנָתָם הִיא כְּאַיִן, שֶׁלֹּא נִדְבְּקוּ עֶלְיוֹנִים וְתַחְתּוֹנִים (בתחתונים), וְשָׁוִים כְּנֶגְדָּם אֱמוּנָה שֶׁל שְׁטוּת. אֲבָל מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ, כְּמוֹ הַמּוֹץ שֶׁסּוֹבֵב (שעף) בָּרוּחַ וּמִתְגַּלְגֵּל בַּקַּיִץ בְּרֵיקָנוּת, זֶהוּ שֶׁכָּתוּב (דניאל ד) וְכָל דַּיָּרֵי הָאָרֶץ כִּכְלוּם חֲשׁוּבִים.</p>\n<p>עוֹד פָּתַח וְאָמַר, בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. אֵת - זֶה יָמִין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֵת - זֶה הַשְּׂמֹאל. לָמַדְנוּ שֶׁנָּטָה הַקָּדוֹשׁ בָּרוּךְ הוּא יְמִינוֹ וּבָרָא אֶת הַשָּׁמַיִם, וְנָטָה שְׂמֹאלוֹ וּבָרָא אֶת הָאָרֶץ. זֶהוּ שֶׁכָּתוּב (ישעיה מח) אַף יָדִי יָסְדָה אֶרֶץ וִימִינִי טִפְּחָה שָׁמָיִם קֹרֵא אֲנִי אֲלֵיהֶם יַעַמְדוּ יַחְדָּו.</p>\n<p>מַה זֶּה יַעַמְדוּ יַחְדָּו? הֲיַעֲלֶה עַל לִבְּךְ שֶׁשָּׁמַיִם וָאָרֶץ? לֹא כָּךְ (מהשמים קורא אני אליהם. והארץ לא כך) אֶלָּא יָמִין וּשְׂמֹאל שֶׁהֵם אֵ\"ת וְאֵ\"ת. וְהֵיאַךְ יַעַמְדוּ יַחְדָּו? בָּזֹאת הַהִיא שֶׁשּׁוֹלֶטֶת בַּחֲצוֹת הַלַּיְלָה שֶׁכְּלוּלָה אֵ\"ת בְּזֹאת.</p>\n<p>וְשָׁנִינוּ, כָּתוּב (קהלת ג) אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ. אֶ\"ת - זֶה שֶׁאָמַרְנוּ. הַכֹּל - כְּמוֹ שֶׁנֶּאֱמַר (בראשית כד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְשָׁנִינוּ שֶׁהִיא כֶּתֶר שֶׁנִּקְרָא זא\"ת, שֶׁכְּלוּלָה מֵאֵ\"ת וְאֵ\"ת, וְשׁוֹלֶטֶת בַּחֲצוֹת הַלַּיְלָה בִּשְׁנֵי צְדָדֶיהָ, בְּרַחֲמִים וְדִין. רַחֲמִים לְיִשְׂרָאֵל, וְדִין לָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, אִם נוֹחַ לִפְנֵי מַר שֶׁנֹּאמַר דָּבָר אֶחָד עַל מַה שֶׁבָּאתִי כָּתוּב, וַיְהִי בַּחֲצִי הַלַּיְלָה וַה' הִכָּה כָּל בְּכוֹר בְּאֶרֶץ מִצְרַיִם. וּמִזֶּה שֶׁאָמַר מַר, נִשְׁמָע שֶׁפָּסוּק זֶה בְּאוֹתוֹ דָבָר בָּא, וְאָנוּ הַדֶּרֶךְ תְּקִינָה לְפָנֵינוּ לָבֹא וְלִשְׁאֹל לְפָנֶיךְ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים קיג) מִי כַּה' אֱלֹהֵינוּ הַמַּגְבִּיהִי לָשָׁבֶת וְגוֹ'. מִי כַּה' אֱלֹהֵינוּ - שֶׁעוֹלֶה וּמִתְעַטֵּר לְהִתְיַשֵּׁב בְּכֶתֶר עֶלְיוֹן קָדוֹשׁ, מֵאִיר עַל כָּל הַמְּנוֹרוֹת שֶׁמְּאִירוֹת כְּתָרִים וַעֲטָרוֹת. הַמַּשְׁפִּילִי לִרְאוֹת - שֶׁיּוֹרֵד בִּכְתָרָיו מִכֶּתֶר לְכֶתֶר, מִנֵּזֶר לְנֵזֶר, מֵאוֹר לְאוֹר, מִמְּנוֹרָה לִמְנוֹרָה, לְהַשְׁגִּיחַ בָּעֶלְיוֹנִים וְתַחְתּוֹנִים. זֶהוּ שֶׁכָּתוּב (שם יד) ה' מִשָּׁמַיִם הִשְׁקִיף עַל בְּנֵי אָדָם וְגוֹ'.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַיְהִי בַּחֲצִי הַלַּיְלָה. כַּחֲצִי הָיָה צָרִיךְ (לכתב), אוֹ כַּחֲצוֹת, כְּמוֹ שֶׁאָמַר מֹשֶׁה. וְאִם כְּמוֹ שֶׁאָמְרוּ חֲבֵרֵינוּ, שֶׁלֹּא יֹאמְרוּ אִצְטַגְנִינֵי פַרְעֹה, מֹשֶׁה בַּדַּאי הוּא. הֲרֵי הַקֻּשְׁיָא בִּמְקוֹמָהּ עוֹמֶדֶת בִּשְׁלֹשָׁה אֳפָנִים, שֶׁאֲפִלּוּ יִשְׂרָאֵל יֹאמְרוּ כָּךְ. אֶחָד - שֶׁאִם כָּךְ, הָיָה לוֹ לוֹמַר, וַיֹּאמֶר מֹשֶׁה כַּחֲצוֹת הַלַּיְלָה. לָמָּה אָמַר כֹּה אָמַר ה' וְגוֹ', כְּמוֹ שֶׁלֹּא יְכַוֵּן אֶת הַשָּׁעָה, שֶׁהֲרֵי לֹא יִתָּפְסוּ בְּמֹשֶׁה אֶלָּא בַּפַּטְרוֹן, מִשּׁוּם שֶׁאָמַר כֹּה אָמַר ה' וְגוֹ'? שְׁנַיִם - שֶׁהֲרֵי מֹשֶׁה אָמַר עַד בְּכוֹר הַשִּׁפְחָה אֲשֶׁר אַחַר הָרֵחָיִם, וְלֹא הָיָה כָּךְ, אֶלָּא עַד בְּכוֹר הַשְּׁבִי אֲשֶׁר בְּבֵית הַבּוֹר. עַל כָּל פָּנִים, אֲפִלּוּ יִשְׂרָאֵל גַּם יֹאמְרוּ כָּךְ, שֶׁהֲרֵי לֹא הִתְבָּרְרוּ הַדְּבָרִים. שְׁלֹשָׁה - שֶׁהוּא אָמַר מִשֵּׁם הַפַּטְרוֹן כַּחֲצוֹת, וְכָתוּב וַיְהִי בַּחֲצִי הַלַּיְלָה.</p>\n<p>וְעוֹד שְׁאֵלָה שֶׁלָּכֶם יוֹתֵר עַל הַמַּשָּׂא שֶׁלֹּא יְכוֹלָה הַבְּהֵמָה לִסְבֹּל, לָמָּה הָיָה בַּחֲצוֹת הַלַּיְלָה וְלֹא בַּיּוֹם? וְלָמָּה מֵתוּ כָּל אוֹתָם הַחַלָּשִׁים שֶׁאַחַר הָרֵחַיִם? אֶלָּא הַכֹּל הוּא סוֹד עֶלְיוֹן בֵּין קוֹצְרֵי הַשָּׂדֶה, וְהַכֹּל הֻכְשַׁר (התבשר) בַּנָּבִיא הַנֶּאֱמָן.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁעָלָיו כָּתוּב יָפְיָפִיתָ מִבְּנֵי אָדָם הוּצַק חֵן בְּשִׂפְתוֹתֶיךְ עַל כֵּן בֵּרַכְךְ אֱלֹהִים לְעוֹלָם. אָהַבְתָּ צֶּדֶק וַתִּשְׂנָא רֶשַׁע עַל כֵּן מְשָׁחֲךְ אֱלֹהִים אֱלֹהֶיךְ שֶׁמֶן שָׂשׂוֹן מֵחֲבֵרֶיךְ. יָפְיָפִיתָ מִבְּנֵי אָדָם - מִשֵּׁת וַחֲנוֹךְ. הוּצַק חֵן בְּשִׂפְתוֹתֶיךְ - מִנֹּחַ וּבָנָיו. עַל כֵּן מְשָׁחֲךְ אֱלֹהִים אֱלֹהֶיךְ - מֵאַבְרָהָם וְיִצְחָק. שֶׁמֶן שָׂשׂוֹן - מִיַּעֲקֹב. מֵחֲבֵרֶיךְ - מִשְּׁאָר נְבִיאִים. וְכִי גֶבֶר שֶׁעוֹלֶה בִּדְרָגוֹת עֶלְיוֹנוֹת שֶׁלֹּא עוֹלֶה שׁוּם אָדָם אַחֵר לֹא יוֹדֵעַ מַה שֶּׁאוֹמֵר?</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, הַכֶּתֶר הַזֶּה שֶׁנִּקְרָא זא\"ת, נִקְרָא אִשָּׁ\"ה, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) לְזֹאת יִקָּרֵא אִשָּׁה. לָמָּה? מִשּׁוּם כִּי מֵאִישׁ לֻקֳחָה את. מִי הוּא אִישׁ? אוֹתוֹ שֶׁנִּקְרָא זֶה, וְזֶהוּ אִישׁ זָכָר, כְּמוֹ שֶׁנֶּאֱמַר (שמות לב) כִּי זֶה מֹשֶׁה הָאִישׁ. הָאִישׁ הַזֶּה. וְנִקְרָא אִישׁ זֶה, וְזֶה אִישׁ. וְזֹאת נִלְקְחָה מִזֶּה שֶׁנִּקְרָא זָכָר.</p>\n<p>וּמִשּׁוּם כָּךְ הַתָּמָר הַזֶּה זָכָר וּנְקֵבָה, שֶׁלֹּא עוֹלֶה זֶה בְּלִי זֶה. תָּמָר, כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) כְּתִמְרוֹת עָשָׁן. מֶה עָשָׁן עוֹלֶה לָבָן וְשָׁחֹר, אַף כָּךְ הַכֹּל כָּלוּל בָּהּ בַּחֲצוֹת הַלַּיְלָה לַעֲשׂוֹת הַנְהָגוֹתֶיהָ בְּשָׁעָה אַחַת לָבָן לְיִשְׂרָאֵל וְשָׁחֹר לְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת.</p>\n<p>וְעוֹד, שֶׁהַלַּיְלָה הַזֶּה לֹא נֶחֱלָק וְלֹא עוֹשֶׂה הַנְהָגוֹתָיו. מִנַּיִן לָנוּ? מֵאַבְרָהָם, שֶׁכָּתוּב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה, שֶׁנֶּחֱלַק לַעֲשׂוֹת הַנְהָגוֹתָיו. אַף כָּאן מֹשֶׁה אָמַר כַּחֲצוֹת, (מהו כחצות, ' כמו שגאמר (מלכים ב ג) כעלות המנחה, (איוב ה) כעלות גדיש. אף כאן כחצות) כְּשֶׁמִּתְחַלֵּק. שֶׁמֹּשֶׁה יָדַע שֶׁלֹּא יַעֲשֶׂה הַנְהָגוֹתָיו עַד שֶׁיִּתְחַלֵּק.</p>\n<p>וְכָךָ הָיָה, שֶׁלֹּא עָשָׂה הַלַּיְלָה הַנְהָגוֹתָיו עַד שֶׁהִתְחַלֵּק, בַּחֲצִי הָאַחֲרוֹן עָשָׂה הַנְהָגוֹתָיו, זֶהוּ שֶׁכָּתוּב וַיְהִי בַּחֲצִי הַלַּיְלָה. מַה זֶה בַּחֲצִי? בַּמַּחֲצִית הָאַחֲרוֹנָה, בִּזְמַן שֶׁהִיא שׁוֹלֶטֶת, וְנִמְצֵאת זֹאת הַזֹּאת לַעֲשׂוֹת הַנְהָגוֹת תָּמִיד. וְכָל הַנְהָגָה שֶׁנַּעֲשֵׂית בַּלַּיְלָה, נַעֲשֵׂית בַּמַּחֲצִית הָאַחֲרוֹנָה.</p>\n<p>וַה' הִכָּה כָל בְּכוֹר. וַה' - הוּא וּבֵית דִּינוֹ. וַה' - הוּא וְהַנְהָגוֹתָיו. הִכָּה כָל בְּכוֹר - הִכָּה? מֹשֶׁה לֹא אָמַר אֶלָּא וּמֵת וְגוֹ', מַהוּ הִכָּה? אֶלָּא שֶׁהִתְעוֹרֵר כֹּה, כְּמוֹ שֶׁהִפְחִיד אוֹתוֹ מֹשֶׁה, שֶׁכָּתוּב וְהִנֵּה לֹא שָׁמַעְתָּ עַד כֹּה.</p>\n<p>וְשָׁנִינוּ, פַּרְעֹה הָיָה חָכָם מִכָּל מְכַשְּׁפָיו, וְהִסְתַּכֵּל בָּזאת שֶׁתַּעֲשֶׂה בּוֹ דִּין, וַעֲתִידָה לְהַחֲרִיב אֶת אַרְצוֹ, כְּמוֹ שֶׁאָמַר מֹשֶׁה, בְּזֹאת תֵּדַע כִּי אֲנִי ה'. וּבַהוּא מַה כָּתוּב? (שמות ז) וַיִּפֶן פַּרְעֹה. מַה זֶּה וַיִּפֶן? שֶׁהִפְנָה לִבּוֹ מֵהִרְהוּר זֶה, כְּמוֹ שֶׁנֶּאֱמַר וַיִּפֶן אַהֲרֹן. וַיָּבא אֶל בֵּיתוֹ וְלֹא שָׁת לִבּוֹ גַּם לָזֹאת. גַּם - לְרַבּוֹת זוֹ שֶׁעֲתִידָה לְהַחֲרִיב אֶת אַרְצוֹ, וְלֹא שָׂם לִבּוֹ כְּנֶגֶד זֹאת.</p>\n<p>כָל בְּכוֹר - אֲפִלּוּ דְּרָגוֹת עֶלְיוֹנוֹת וְתַחְתּוֹנוֹת נִשְׁבְּרוּ מִשִּׁלְטוֹנָם (מהשתלשלותם), כָּל אוֹתָם שֶׁשּׁוֹלְטִים בַּחָכְמָה שֶׁלָּהֶם, שֶׁכָּתוּב בְּאֶרֶץ מִצְרַיִם. וְכָל הַדְּרָגוֹת, הָעֶלְיוֹנוֹת וְהַתַּחְתּוֹנוֹת שֶׁנִּשְׁבְּרוּ מִשִּׁלְטוֹנָם (מהשתלשלותם), כֻּלָּם נִרְאוֹת (נרמזות) בַּפָּסוּק, שֶׁכָּתוּב מִבְּכוֹר פַּרְעֹה הַיֹּשֵׁב עַל כִּסְאוֹ עַד בְּכוֹר הַשִּׁפְחָה אֲשֶׁר אַחַר הָרֵחָיִם וְכֹל בְּכוֹר בְּהֵמָה. הֲרֵי כֻּלָּם נִרְאִים בַּפָּסוּק.</p>\n<p>סְתָמוֹ שֶׁל דָּבָר, מִבְּכוֹר פַּרְעֹה הַיֹּשֵׁב עַל כִּסְאוֹ - כֶּתֶר תַּחְתּוֹן שֶׁל שְׁלִיטַת הַמַּלְכוּת (מהמלכות) שֶׁלְּמַעְלָה. עַד בְּכוֹר הַשִּׁפְחָה - כֶּתֶר שְׂמֹאל מִתַּחְתֶּיהָ שֶׁל שְׁלִיטָה מֵאַחַר אַרְבַּע (מכתר אחר) רֵחַיִם, אַרְבַּע מַחֲנוֹת. (משמע) מִשּׁוּם שֶׁכָּתוּב אַחַר הָרֵחָיִם, (ולא מן הרחים). וְכֹל בְּכוֹר בְּהֵמָה - תַּחְתּוֹנִים מִתַּחְתּוֹנִים, נְקֵבָה מִנְּקֵבוֹת, שֶׁנִּמְצְאוּ בָּאֲתוֹנוֹת בַּבְּהֵמוֹת וַחֲמוֹרִים, בִּגְדוֹלִים וּבִקְטַנִּים, וּמְקַבְּלִים מֵהֶם גְּבָרִים וּנְקֵבוֹת. עַד בְּכוֹר הַשְּׁבִי אֲשֶׁר בְּבֵית הַבּוֹר - אוֹתָם שֶׁיּוֹצְאִים מִשִּׁפְחָה, שֶׁבָּהֶם עוֹשִׂים לַאֲסִירִים שֶׁיִּשְׁתַּעְבְּדוּ בָהֶם לְעוֹלָמִים וְלֹא יֵצְאוּ לַחֵרוּת.</p>\n<p>וּבְבִטְחוֹן הַדְּרָגוֹת הַלָּלוּ סֵרְבוּ הַמִּצְרִים, שֶׁבָּהֶם עָשׂוּ קֶשֶׁר לְיִשְׂרָאֵל שֶׁלֹּא יֵצְאוּ מֵעַבְדוּתָם לְעוֹלָמִים. וּבָזֶה נִרְאֵית הַגְּבוּרָה וְהַשִּׁלְטוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזִכְרוֹן זֶה לֹא יִכְלֶה מִיִּשְׂרָאֵל לְדוֹרֵי דוֹרוֹת. שֶׁאִם לֹא הָיָה כֹּחַ וּגְבוּרָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל מַלְכֵי הָעַמִּים וְכָל מְכַשְּׁפֵי הָעוֹלָמוֹת וְחַכְמֵי הָעוֹלָמוֹת, לֹא יֵצְאוּ יִשְׂרָאֵל מִן הָעַבְדוּת, שֶׁהִתִּיר אֶת הַקְּשָׁרִים שֶׁלָּהֶם וְשָׁבַר אֶת כָּל אוֹתָם הַכְּתָרִים כְּדֵי לְהוֹצִיא אוֹתָם. עַל זֶה כָּתוּב (ירמיה י) מִי לֹא יִרָאֲךְ מֶלֶךְ הַגּוֹיִם כִּי לְךְ יָאָתָה כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךְ.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן, הֵרִים קוֹלוֹ וְנֶאֱנַח. אָמַר, אֶשְׁכּוֹל הַקִּנְטוּר נִמְצָא. חֲשַׁבְתֶּם שֶׁשִּׁבַּח הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמָּה פְעָמִים, (דברים ה) אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם, (שם טז) הוֹצִיאֲךְ ה' אֱלֹהֶיךְ מִמִּצְרַיִם, (שם ה) וַיֹּצִאֲךְ ה' אֱלֹהֶיךְ מִשָּׁם, (שמות יב) הוֹצֵאתִי אֶת צִבְאוֹתֵיכֶם, (שם יג) זָכוֹר אֶת הַיּוֹם הַזֶּה אֲשֶׁר יְצָאתֶם מִמִּצְרַיִם, (דברים ד) וַיּוֹצִאֲךְ בְּפָנָיו בְּכֹחוֹ הַגָּדוֹל מִמִּצְרָיִם, הוֹצִיא ה' אֶתְכֶם מִזֶּה.</p>\n<p>אֶלָּא שָׁנִינוּ, עֲשָׂרָה כְתָרִים הֵם לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, וְכֻלָּם נִסְתָּרִים בִּשְׁלֹשֶׁת אֵלֶּה שֶׁאָמַרְנוּ. וּשְׁלֹשָׁה קְשָׁרִים קְשׁוּרִים בָּהֶם עַל שָׁלֹשׁ דְּרָגוֹת אֵלּוּ שֶׁבָּהֶם עָשׂוּ שֶׁיִּשְׂרָאֵל לֹא יֵצְאוּ מִשִּׁעְבּוּדָם לְעוֹלָמִים.</p>\n<p>אַשְׁרֵיכֶם אַבְרָהָם יִצְחָק וְיַעֲקֹב, שֶׁבִּזְכוּתְכֶם הִתִּירוּ אֶת הַקְּשָׁרִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא זָכַר שְׁלֹשֶׁת קִשְׁרֵי הָאֱמוּנָה שֶׁלָּכֶם. זֶהוּ שֶׁכָּתוּב (שמותב) וַיִּזְכֹּר אֱלֹהִים אֶת בְּרִיתוֹ אֶת אַבְרָהָם אֶת יִצְחָק וְאֶת יַעֲקֹב. אֶת אַבְרָהָם - הֲרֵי קֶשֶׁר אֶחָד שֶׁל אַבְרָהָם. אֶת יִצְחָק - הֲרֵי קֶשֶׁר שֵׁנִי שֶׁל יִצְחָק. וְאֶת יַעֲקֹב - הֲרֵי קֶשֶׁר שְׁלִישִׁי, שְׁלֵמוּתוֹ שֶׁל יַעֲקֹב.</p>\n<p>לָמַדְנוּ, כָּל הַזְּמַנִּים וְהַחַגִּים וְהַשַּׁבָּתוֹת, כֻּלָּם זִכָּרוֹן לָזֶה, וְעַל זֶה הִתְקַיְּמוּ כֻלָּם, שֶׁאִלְמָלֵא זֶה לֹא הָיְתָה שְׁמִירָה שֶׁל זְמַנִּים וְחַגִּים וְשַׁבָּתוֹת, וְלָכֵן לֹא כָלָה הַזִּכָּרוֹן שֶׁל מִצְרַיִם מִכָּל הַזְּמַנִּים וְהַחַגִּים וְהַשַּׁבָּתוֹת. בֹּא רְאֵה, דִּין (זה) הוּא יְסוֹד וְשֹׁרֶשׁ שֶׁל הַתּוֹרָה, וְכָל מִצְווֹתָיו, וְכָל הָאֱמוּנָה הַשְּׁלֵמָה שֶׁל יִשְׂרָאֵל.</p>\n<p>וְעוֹד, לָמָּה לֹא הָיָה בַּיּוֹם כְּפִי שֶׁשְּׁאַלְתֶּם? שָׁנִינוּ, כָּתוּב הַיּוֹם אַתֶּם יצְאִים, וְכָתוּב הוֹצִיאֲךְ ה' אֱלֹהֶיךְ מִמִּצְרַיִם לַיְלָה. אֶלָּא שָׁנִינוּ, עִקַּר גְּאֻלַּת יִשְׂרָאֵל לֹא הָיָה אֶלָּא בַּלַּיְלָה, שֶׁהַלַּיְלָה מַתִּיר קְשָׁרִים וְעוֹשֶׂה נְקָמוֹת, וְהַיּוֹם הוֹצִיא אוֹתָם בְּרֹאשׁ גָּלוּי, זֶהוּ שֶׁכָּתוּב (במדבר לג) יָצְאוּ בְנֵי יִשְׂרָאֵל בְּיָד רָמָה לְעֵינֵי כָּל מִצְרָיִם. (ועוד, הלילה מתיר את הקשרים ועושה נקמות ודינים, והיום מגלה ומפרסם הגס והגקמה שגעשה. זהו שכתוביצאובניישראלביד רמה וגו'.) וְכָתוּב וּמִצְרַיִם מְקַבְּרִים אֵת אֲשֶׁר הִכָּה ה' בָּהֶם כָּל בְּכוֹר. זֶהוּ פִּרְסוּם הַנֵּס.</p>\n<p>בָּאוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי, הִשְׁתַּטְּחוּ לְפָנָיו וְנָשְׁקוּ יָדוֹ, וּבָכוּ וְאָמְרוּ, חֲקִיקוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים מְרִימִים רֹאשׁ בִּזְכוּתְךְ. עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא יְרוּשָׁלַיִם לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה. עָשָׂה (רשב\"י) חוֹמוֹת הָעִיר הַקְּדוֹשָׁה וּשְׁעָרֶיהָ. מִי שֶׁנִּכְנָס, לֹא נִכְנָס עַד שֶׁיִּפָּתְחוּ הַשְּׁעָרִים. מִי שֶׁעוֹלֶה, לֹא עוֹלֶה עַד שֶׁיִּתְתַּקְנוּ הַמַּדְרֵגוֹת שֶׁל הַחוֹמוֹת. מִי יָכוֹל לִפְתֹחַ אֶת שַׁעֲרֵי הָעִיר הַקְּדוֹשָׁה, וּמִי יָכוֹל לְהַתְקִין אֶת הַמַּדְרֵגוֹת שֶׁל הַחוֹמוֹת? זֶה רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, שֶׁהוּא פּוֹתֵחַ שְׁעָרִים שֶׁל סוֹדוֹת הַחָכְמָה וְהוּא מְתַקֵּן דְּרָגוֹת עֶלְיוֹנוֹת. וְכָתוּב (דברים טז) יֵרָאֶה כָּל זְכוּרְךְ אֶת פְּנֵי הָאָדוֹן ה'. מִי זֶה פְּנֵי הָאָדוֹן ה'? זֶה רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, שֶׁמִי שֶׁהוּא זָכָר מִן הַזְּכָרִים צָרִיךְ לְהֵרָאוֹת לְפָנָיו.</p>\n<p>אָמַר לָהֶם, עַד עַכְשָׁו לֹא סִיַּמְנוּ הַדָּבָר עַל שְׁאֵלַתְכֶם, שֶׁהֲרֵי שָׁנִינוּ וַה' הִכָּה כָל בְּכוֹר, כָּל בְּכוֹר סְתָם, כְּמוֹ שֶׁאָמַרְנוּ. וְהַכֹּל הָיָה כְּמוֹ שֶׁל אוֹתָם שֶׁמֵּתוּ, אוֹתָם קוֹשְׁרֵי הַקְּשָׁרִים שֶׁהָיוּ מִשְׁתַּמְּשִׁים בְּכִשְׁפֵיהֶם בְּאוֹתָם הַכְּתָרִים. מֵהֶם מִשְׁתַּמְּשִׁים בָּעֶלְיוֹנִים וּמֵהֶם בַּתַּחְתּוֹנִים, וְאַף עַל גַּב שֶׁכֻּלָּם הֵם תַּחְתּוֹנִים. וְכָל אֶרֶץ מִצְרַיִם מְלֵאָה הָיְתָה כְּשָׁפִים, וְכָתוּב כִּי אֵין בַּיִת אֲשֶׁר אֵין שָׁם מֵת.</p>\n<p>וְנַעָשָׂה דִין בַּכֹּל, בְּשָׁעָה שֶׁהִתְכַּנְּסוּ כֻלָּם בְּבָתֵּיהֶם וְלֹא הָיוּ מִתְפַּזְּרִים בַּמִּדְבָּר וּבַשָּׂדֶה, אֶלָּא כֻּלָּם נִמְצְאוּ בְּבָתֵּיהֶם, (ואור הגר יפה לבדיקה מבחוץ) וְעָשָׂה הַלַּיְלָה אֶת דִּינָיו בַּכֹּל בְּאוֹתָהּ שָׁעָה. וְשָׁנִינוּ שֶׁהָיָה מֵאִיר הַלַּיְלָה כְּמוֹ הַיּוֹם בִּתְקוּפַת תַּמּוּז, וְרָאָה כָּל הָעָם אֶת דִּינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב (תהלים קלט) וְלַיְלָה כַּיּוֹם יָאִיר כַּחֲשֵׁכָה כָּאוֹרָה.</p>\n<p>וּבְשָׁעָה שֶׁיָּצְאוּ, נִמְצְאוּ כֻלָּם מֵתִים בַּשְּׁוָקִים לְעֵינֵי הַכֹּל. רָצוּ לִקְבֹּר אוֹתָם וְלֹא מָצְאוּ, וְזֶה הָיָה קָשֶׁה לָהֶם מֵהַכֹּל. רָאוּ אֶת יִשְׂרָאֵל יוֹצְאִים לְעֵינֵיהֶם בְּצַד אֶחָד, וְרָאוּ אֶת מֵתֵיהֶם בַּצַּד הָאַחֵר. וּבַכֹּל הָיָה פִּרְסוּם הַנֵּס שֶׁלֹּא הָיָה כָּזֶה מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם.</p>\n<p>וּבֹא רְאֵה, כָּתוּב לֵיל שִׁמֻּרִים הוּא לַה' לְהוֹצִיאָם וְגוֹ', הוּא הַלַּיְלָה הַזֶּה לַה' שִׁמֻּרִים לְכָל בְּנֵי יִשְׂרָאֵל וְגוֹ'. פָּסוּק זֶה קָשֶׁה, כֵּיוָן שֶׁאָמַר לֵיל, מַה זֶּה שִׁמֻּרִים, וְלֹא שִׁמּוּר? שִׁמּוּר הָיָה צָרִיךְ (לכתב) ! וְכָתוּב הוּא הַלַּיְלָה הַזֶּה. לֵיל אָמַר בַּהַתְחָלָה, וְאַחַר כָּךְ לַיְלָה.</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, כָּתוּב (דברים כב) כִּי יִהְיֶה נַעֲרָה בְתוּלָה. נַעֲרָ כָּתוּב, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל זְמַן שֶׁלֹּא קִבְּלָה זָכָר, נִקְרֵאת נַעַר. מִשֶּׁקִּבְּלָה זָכָר, נִקְרֵאת נַעֲרָה. אַף כָּאן, לֵיל - עַד שֶׁלֹּא קִבְּלָה זָכָר. וְאַף עַל גַּב שֶׁכָּתוּב בּוֹ שִׁמּוּרִים - זָכָר הָיָה עָתִיד לְהִתְחַבֵּר עִמָּהּ. וּבְשָׁעָה שֶׁהִתְחַבֵּר עִמָּהּ זָכָר, כָּתוּב הוּא הַלַּיְלָה הַזֶּה לַה' שִׁמֻּרִים. שִׁמּוּרִים - זָכָר וּנְקֵבָה, וּמִשּׁוּם כָּךְ כָּתוּב הַלַּיְלָה הַזֶּה.</p>\n<p>וּבְמָקוֹם שֶׁנִּמְצְאוּ זָכָר וּנְקֵבָה אֵין שֶׁבַח אֶלָּא לַזָּכָר. וְכָךְ שִׁבְּחוּ יִשְׂרָאֵל בְּתִשְׁבְּחוֹתֵיהֶם לַזָּכָר וְלֹא לַנְּקֵבָה, זֶהוּ שֶׁכָּתוּב (שמותטו) זֶה אֵלִי וְאַנְוֵהוּ, שֶׁאֵין שֶׁבַח בְּמָקוֹם שֶׁזָּכָר וּנְקֵבָה נִמְצָאִים אֶלָּא לַזָּכָר. וְעַל זֶה (ולזה) מְחַכִּים יִשְׂרָאֵל, שֶׁכָּתוּב (ישעיה כה) זֶה ה' קִוִּינוּ לוֹ נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ. מִשּׁוּם שֶׁכָּךְ עָתִיד לַעֲשׂוֹת לָהֶם, שֶׁכָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>\n<p>וְסוֹד זֶה כָּךְ הוּא - כְּמוֹ שֶׁכָּאן לֵיל וְלַיְלָה, כָּךְ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לָהֶם, שֶׁכָּתוּב שֹׁמֵר מַה מִּלַּיְלָה שּמֵר מַה מִלֵּיל. מַה לְּהַלָּן שְׁמִירָה וְלֵיל, אַף כָּאן שְׁמִירָה וְלֵיל. מַה לְּהַלָּן שְׁמִירָה וְלַיְלָה, אַף כָּאן שְׁמִירָה וְלַיְלָה.</p>\n<p>וְלַיְלָה נִקְרָא אַגַּב זָכָר, זֶהוּ שֶׁכָּתוּב (ישעיהכא) אָתָא בֹקֶר וְגַם לָיְלָה. בֹּקֶר, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יט) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר, שֶׁהוּא מִדָּתוֹ מַמָּשׁ. וְכָתוּב (תהלים ה) ה' בֹּקֶר תִּשְׁמַע קוֹלִי, בֹּקֶר מַמָּשׁ.</p>\n<p>יָשְׁבוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי, וְלִמֵּד לָהֶם הַסּוֹד שֶׁל תּוֹרַת כֹּהֲנִים, וְהָיוּ חוֹזְרִים כָּל יוֹם וְיוֹשְׁבִים לְפָנָיו. יוֹם אֶחָד יָצָא רַבִּי שִׁמְעוֹן לַחוּץ, הָלְכוּ עִמּוֹ, הִגִּיעוּ לְשָׂדֶה אֶחָד וְיָשְׁבוּ.</p>"],[9522011588,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, בּא רְאֵה, כָּתוּב (קהלת ז) אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלֵי יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. שְׁלֹמֹה שֶׁהָיְתָה חָכְמָתוֹ יְתֵרָה (מכבדת) עַל הַכֹּל, מַה הוּא אָמַר בַּפָּסוּק הַזֶּה? אֶלָּא שְׁלֹמֹה רָמַז רֶמֶז שֶׁל חָכְמָה, שֶׁהֲרֵי רָאִינוּ שֶׁדַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינָם כָּךְ, שֶׁהֲרֵי כָּתוּב וְלָתֵת לְאִישׁ כִּדְרָכָיו וְכִפְרִי מַעֲלָלָיו. אֶלָּא שְׁנֵי עִנְיָנִים הֵם שֶׁכָּאן רָמַז.</p>\n<p>שֶׁשָּׁנִינוּ, כְּשֶׁעֵינֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצִים לְהַשְׁגִּיחַ בָּעוֹלָם וּלְעַיֵּן בּוֹ, כְּמוֹ שֶׁכָּתוּב (עיני ה' המה משוטטים בכל הארץ (זכריה ד), וכתוב כי וגו') כִּי ה' עֵינָיו מְשׁוֹטְטוֹת בְּכָל הָאָרֶץ, וְנִמְצָאִים רְשָׁעִים בָּעוֹלָם, אוֹתוֹ צַדִּיק שֶׁנִּמְצָא בַּדּוֹר נִתְפָּס בְּחֶטְאָם, וְלָרְשָׁעִים מַאֲרִיךְ הַקָּדוֹשׁ בָּרוּךְ הוּא רָגְזוֹ עִמָּהֶם עַד שֶׁיָּשׁוּבוּ, וְאִם לֹא - לֹא יִמָּצֵא מִי שֶׁיְּבַקֵּשׁ עֲלֵיהֶם רַחֲמִים. זֶהוּ שֶׁכָּתוּב יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ, מִשּׁוּם שֶׁאוֹתוֹ צַדִּיק הִסְתַּלֵּק מֵהָעוֹלָם.</p>\n<p>מִשּׁוּם כָּךְ שָׁנִינוּ, לְעוֹלָם אַל יָדוּר אָדָם אֶלָּא בְּמָקוֹם שֶׁאַנְשֵׁי מַעֲשֶׂה דָּרִים בְּתוֹכוֹ. מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹי לָזֶה שֶׁמְּדוֹרוֹ בֵּין הָרְשָׁעִים, מִשּׁוּם שֶׁהוּא נִתְפָּס בַּחֲטָאֵיהֶם, וְאִם דִּיּוּרוֹ בֵּין צַדִּיקִים, מֵיטִיבִים לוֹ בִּגְלָלָם.</p>\n<p>שֶׁהֲרֵי רַב חַסְדָּא הָיָה דִיּוּרוֹ בָּרִאשׁוֹנָה בֵּין קַפּוּטְקָאִים, וְהַשָּׁעָה הָיְתָה דְּחוּקָה לוֹ וּמַחֲלוֹת רוֹדְפוֹת אַחֲרָיו. נָסַע וְשָׂם מְדוֹרוֹ בֵּין בַּעֲלֵי מָגִנִּים שֶׁל צִפּוֹרִי, וְעָלָה וְזָכָה לְכַמָּה טוֹבוֹת, לְכַמָּה עֹשֶׁר, לְכַמָּה תּוֹרָה, וְאָמַר: כָּל זֶה זָכִיתִי עַל שֶׁנִּכְנַסְתִּי בֵּין אוֹתָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ לְהֵיטִיב לָהֶם.</p>\n<p>דָּבָר אַחֵר אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי - וְכִי שְׁלֹמֹה, שֶׁדְּרָגוֹת עֶלְיוֹנוֹת שֶׁל חָכְמָה הָיוּ בוֹ עַל כָּל בְּנֵי הַדּוֹר, שֶׁכָּתוּב וַיֶּחְכַּם מִכָּל הָאָדָם, (והשתדלותובתורהלעשותטובואמת) שֶׁכָּתוּב וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ, אָמַר בִּימֵי הֶבְלִי, וְכָתוּב (קהלת א) הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת?</p>\n<p>וְשָׁנִינוּ, שֶׁבַע שֵׁמוֹת נִקְרָא: שְׁלֹמֹה, יְדִידְיָ\"ה, אָגוּר, בֶּן יָקֶ\"א, אִיתִיאֵ\"ל, לְמוֹאֵל, קֹהֶלֶת. קֹהֶלֶת כְּנֶגֶד כֻּלָּם, וְכֻלָּם נִקְרָא כְּעֵין שֶׁל מַעְלָה. קֹהֶלֶת כִּנּוּס קָדוֹשׁ שֶׁל עֲשָׂרָה, מִשּׁוּם כָּךְ קָהָל אֵין פָּחוֹת מֵעֲשָׂרָה, וְקָהָל אֲפִלּוּ מֵאָה, וְקֹהֶלֶת כְּלָל שֶׁל הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר קְהִלַּת יַעֲקֹב.</p>\n<p>וְשָׁנִינוּ, שְׁמוֹתָיו נִקְרְאוּ עַל שֵׁם הַחָכְמָה, וּמִשּׁוּם כָּךְ עָשָׂה שְׁלֹשָׁה סְפָרִים: שִׁיר הַשִּׁירִים, קֹהֶלֶת, מִשְׁלֵי. וְכֻלָּם לְהַשְׁלִים הַחָכְמָה. שִׁיר הַשִּׁירִים כְּנֶגֶד חֶסֶד, קֹהֶלֶת כְּנֶגֶד דִּין, מִשְׁלֵי כְּנֶגֶד רַחֲמִים, כְּדֵי לְהַשְׁלִים אֶת הַחָכְמָה. וְהוּא עָשָׂה כָּל מַה שֶּׁעָשָׂה כְּדֵי לְהַרְאוֹת חָכְמָה, וּכְנֶגֶד דַּרְגָּה (וכנגד סוד) עֶלְיוֹנָה, וְהוּא אָמַר בִּימֵי הֶבְלִי, הֲבֵל הֲבָלִים.</p>\n<p>אֶלָּא, סוֹד שֶׁל הֶבֶל נִכְבָּד הוּא, וְהוּא הַהֶבֶל שֶׁיּוֹצֵא מֵהַפֶּה. וְסוֹד הַהֶבֶל שֶׁיּוֹצֵא מֵהַפֶּה נַעֲשֶׂה מִמֶּנּוּ קוֹל. וְשָׁנִינוּ, אֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא בַּהֲבֵל פִּיהֶם שֶׁל תִּינוֹקוֹת שֶׁל בֵּית רַבָּן שֶׁלֹּא חָטְאוּ. שֶׁלֹּא חָטְאוּ מַמָּשׁ. (וקול) וְהֶבֶל נַעֲשֶׂה בְּרוּחַ וּמַיִם, וְכָל מַה שֶּׁנַּעֲשֶׂה בָּעוֹלָם נַעֲשֶׂה בְּהֶבֶל. וְסוֹד (של דבר) שֶׁהֶבֶל זֶה שֶׁל תִּינוֹקוֹת נַעֲשֶׂה קוֹל, וּמִתְפַּשֵּׁט בָּעוֹלָם, וְהֵם שׁוֹמְרֵי הָעוֹלָם וְשׁוֹמְרֵי הָעִיר. זֶהוּ שֶׁכָּתוּב (תהלים קכז) אִם ה' לֹא יִשְׁמָר עִיר וְגוֹ'.</p>\n<p>וּבֹא רְאֵה, הוּא הֶבֶל, הוּא קוֹל. מַה בֵּין זֶה לָזֶה? הֶבֶל (הוא קול) עוֹמֵד בְּכֹחַ לְהוֹצִיא קוֹל. קוֹל מַמָּשׁ עוֹמֵד בְּקִיּוּמוֹ (שלא) לְהוֹצִיא דָבָר (אחר), וְאוֹתוֹ הֶבֶל שֶׁהָיָה יְרֻשַּׁת אָבִיו קְרָאוֹ הֶבֶל, וּמִמֶּנּוּ רָאָה כָּל מַה שֶּׁרָאָה. וְאַף עַל גַּב שֶׁסִּיּוּעִים רַבִּים מִלְמַעְלָה, אֲחֵרִים הָיוּ לוֹ, וּלְהוֹדִיעַ הַדָּבָר אָמַר בִּימֵי הֶבְלִי. שֶׁדָּבָר זֶה בָּא מִשָּׁם.</p>\n<p>וְסוֹד הַדָּבָר - הַכֹּל הָבֶל, אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי יֵשׁ צַדִּיק אֹבֵד בְּצִדְקוֹ. זֶהוּ סוֹד הַדָּבָר שֶׁגִּלָּה וּפִרְסֵם שֶׁהַכֹּל תָּלוּי בִּימֵי הֶבְלִי. כְּלוֹמַר, בִּזְמַן שֶׁהַהֶבֶל הַזֶּה יוֹנֵק מִן הַדִּין כְּדֵי לַעֲשׂוֹת דִּין, צַדִּיק אֹבֵד בְּצִדְקוֹ. וּבִזְמַן שֶׁהַהֶבֶל הַזֶּה יוֹנֵק מֵרַחֲמִים, רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ, וּשְׁנֵיהֶם תְּלוּיִים בַּהֶבֶל הַזֶּה. וְלָכֵן כָּתוּב בִּימֵי וְלֹא כָתוּב בְּיוֹם, וְהַכֹּל תָּלוּי בִּימֵי הֶבֶל זֶה. מִי שֶּׁנִּפְגָּשׁ בְּדִין - בְּדִין, וּמִי שֶׁנִּפְגָּשׁ בְּרַחֲמִים - בְּרַחֲמִים.</p>\n<p>וְאִם תֹּאמַר, יֵשׁ צַדִּיק אֹבֵד, וְלֹא אָמַר אָבוּד - כָּךְ הוּא אוֹבֵד מַמָּשׁ, שֶׁאוֹתוֹ הַדִּין אוֹבֵד לַצַּדִּיק מֵהָעוֹלָם וּמֵהַדּוֹר. וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ - מַאֲרִיךְ מַמָּשׁ. שֶׁכְּשֶׁאוֹתוֹ הַדִּין (הבל) יוֹנֵק מֵרַחֲמִים, עוֹשֶׂה רַחֲמִים לְאוֹתוֹ רָשָׁע וּמַאֲרִיךְ לוֹ.</p>\n<p>עֵד שֶׁהָיוּ יוֹשְׁבִים, רָאוּ קִיטוֹר שֶׁהָיָה עוֹלֶה לְמַעְלָה וְיוֹרֵד לְמַטָּה. אָמַר, הִתְעַטְּרוּת הִתְעַטֵּר בְּרֶפֶשׁ (בעניות) הָאָרֶץ מִלְמַעְלָה. בֵּין כָּךְ וְכָךְ הֶעֱלָה אוֹתוֹ שָׂדֶה רֵיחַ מִכָּל הַבְּשָׂמִים. אָמַר, נֵשֵׁב כָּאן, שֶׁשְּׁכִינָה עוֹמֶדֶת אֶצְלֵנוּ. מִשּׁוּם כָּךְ כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'.</p>"],[9522011589,"<p>פָּתַח וְאָמַר, (בראשית כז) וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי וְגוֹ'. וַיָּרַח אֶת רֵיחַ בְּגָדָיו, מַשְׁמָע שֶׁאוֹתָם לְבוּשִׁים הָיוּ מַעֲלִים רֵיחַ טוֹב, (שלאזזו) וְאַחַר כָּךְ זָז מֵהֶם אוֹתוֹ רֵיחַ. עַכְשָׁו יֵשׁ לְהִסְתַּכֵּל, כָּתוּב רֵיחַ בְּגָדָיו, וְכָתוּב רֵיחַ בְּנִי, וְלֹא אָמַר רֵיחַ הַבְּגָדִים, אֶלָּא רֵיחַ בְּנִי. אֶלָּא שָׁנִינוּ, כֵּיוָן שֶׁנִּכְנַס יַעֲקֹב, נִכְנַס עִמּוֹ גַּן עֵדֶן. וְשָׁנִינוּ, אוֹתָם בְּגָדִים הָיוּ שֶׁל אָדָם הָרִאשׁוֹן, שֶׁכָּתוּב (שם ג) וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּשֵׁם, וְהוֹצִיאָם מִגַּן עֵדֶן.</p>\n<p>וְאִם תֹּאמַר שֶׁכָּתוּב וַיִּתְפְּרוּ עֲלֵה תְאֵנָה, שֶׁאֵלֶּה הָיוּ, אִם כָּךְ לָמָּה כָּתוּב וַיַּעַשׂ ה' אֱלֹהִים, וְכָתוּב כָּתְנוֹת עוֹר, הֲרֵי לֹא הָיוּ אֶלָּא עֲלֵה תְאֵנָה? אֶלָּא כְּתַרְגּוּמוֹ: לְבוּשֵׁי כָבוֹד, וְהָיוּ מַעֲלִים רֵיחוֹת מִבֹּשֶׂם שֶׁל גַּן עֵדֶן.</p>\n<p>וְשָׁנִינוּ, בְּשֵׁם מָלֵא נַעֲשׂוּ, שֶׁכָּתוּב וַיַּעַשׂ ה' אֱלֹהִים, מַה שֶּׁלֹּא נַעֲשׂוּ בוֹ שָׁמַיִם וָאָרֶץ. וְלֹא? וַהֲרֵי כָּתוּב (שם ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם? לֹא קָשֶׁה. זֶה כְּשֶׁנַּעֲשׂוּ, לֹא נַעֲשׂוּ בְּשֵׁם מָלֵא, פְּרָט לִכְשֶׁהִתְקַיְּמוּ, בְּשֵׁם מָלֵא הִתְקַיְּמוּ.</p>\n<p>וּמַה שֶּׁאָמְרוּ שֶׁאוֹתָם לְבוּשִׁים הָיוּ לְאוֹתוֹ עֵשָׂו הָרָשָׁע שֶׁלָּקַח אוֹתָם מִנִּמְרוֹד - כָּךְ בֵּאַרְנוּ. וְהַדָּבָר קָשֶׁה, שֶׁאִם כָּךְ, הֲרֵי כָּתוּב לְאָדָם וּלְאִשְׁתּוֹ. לְבוּשִׁים לְאָדָם וּלְבוּשִׁים לְחַוָּה. לְבוּשִׁים שֶׁל חַוָּה מַה נַּעֲשׂוּ? וְעוֹד, שֶׁאִם כָּךְ, בַּמֶּה נִקְבְּרוּ? הַאִם תַּעֲלֶה עַל דַּעְתְּךְ שֶׁהֵם עָזְבוּ וְזָרְקוּ מֵהֶם הַזֹּהַר הָעֶלְיוֹן שֶׁנָּתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא?</p>\n<p>אֶלָּא אוֹתָם לְבוּשִׁים שֶׁהִתְלַבְּשׁוּ בָהֶם אָדָם וְאִשְׁתּוֹ, לֹא הִתְלַבֵּשׁ בָּהֶם אָדָם אַחֵר, שֶׁבְּאוֹתָם לְבוּשִׁים דָּמוּ כְּמוֹ שֶׁלְּמַעְלָה. וְאִם תַּעֲלֶה בְּדַעְתְּךְ שֶׁהֵם מֵעַצְמָם הִתְלַבְּשׁוּ בָהֶם - בֹּא רְאֵה, כָּתוּב וַיַּלְבִּשֵׁם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִלְבִּישׁ אוֹתָם, אַשְׁרֵי חֶלְקָם.</p>\n<p>כָּתוּב (תהלים קד) ה' אֱלֹהַי גָּדַלְתָּ מְאֹד הוֹד וְהָדָר לָבָשְׁתָּ. וְכָתוּב (שם צו) הוֹד וְהָדָר לְפָנָיו. וְכָתוּב (שם קד) עוֹטֶה אוֹר כַּשַּׂלְמָה וְגוֹ'. כֵּיוָן שֶׁהִתְלַבֵּשׁ (מה שהתלבש), עָשָׂה מַה שֶּׁעָשָׂה. מְלַמֵּד שֶׁהִתְעַטֵּף הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאוֹר וּבָרָא אֶת הַשָּׁמַיִם. אֶלָּא בַּמֶּה בֵּאַרְנוּ הַחֲמֻדת אֲשֶׁר אִתָּהּ בַּבָּיִת? הַחֲמֻדת - בִּגְדֵי מַלְכוּת בְּמֶשִׁי וְזָהָב, וְדֶרֶךְ הָעוֹלָם שֶׁגּוֹנְזִים אוֹתָם בִּבְשָׂמִים וְרֵיחוֹת לִכְבוֹד הַלְּבוּשִׁים שֶׁלָּהֶם.</p>\n<p>בֹּא רְאֵה, וַיָּרַח אֶת רֵיחַ בְּגָדָיו - בַּתְּחִלָּה. וּכְשֶׁהִרְגִּישׁ אָמַר, רְאֵה רֵיחַ בְּנִי, שֶׁיָּדַע שֶׁבּוֹ הַדָּבָר הָיָה תָּלוּי, שֶׁבִּגְלָלוֹ הֶעֱלָה רֵיחַ. כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה', וְכִי מִנַּיִן הָיָה יוֹדֵעַ יִצְחָק רֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'?</p>\n<p>אֶלָּא שְׁנֵי דְבָרִים הֵם, וְהַכֹּל הוּא אֶחָד, שֶׁכָּתוּב (בראשית כד) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עָרֶב. וְכִי לֹא הָיָה לוֹ בַּיִת אוֹ מָקוֹם אַחֵר לְהִתְפַּלֵּל? אֶלָּא אוֹתוֹ הַשָּׂדֶה הָיָה אֲשֶׁר קָנָה אַבְרָהָם סָמוּךְ לַמְּעָרָה, שֶׁכָּתוּב הַשָּׂדֶה אֲשֶׁר קָנָה אַבְרָהָם מֵאֵת בְּנֵי חֵת. וּבְשָׁעָה שֶׁהָיָה יִצְחָק נִכְנָס אֵלָיו, רָאָה שְׁכִינָה עָלָיו, וְהֶעֱלָה רֵיחוֹת עֶלְיוֹנִים קְדוֹשִׁים, וּמִשּׁוּם כָּךְ הָיָה מִתְפַּלֵּל שָׁם, וּקְבָעוֹ לִתְפִלָּתוֹ.</p>\n<p>וְלָמָּה אַבְרָהָם לֹא הָיָה מִתְפַּלֵּל שָׁם? מִשּׁוּם שֶׁקְּבִיעוּת שֶׁל מָקוֹם אַחֵר הָיְתָה לוֹ בַּתְּחִלָּה, וְדָבָר אַחֵר רֵיחַ שֶׁרָאָה בְּהַר הַמּוֹרִיָּה. וְלָמָּה נִקְרָא מוֹרִיָּה? עַל שֵׁם הַמֹּר הַטּוֹב שֶׁהָיָה שָׁם.</p>\n<p>וְהַסֹל הָיָה, וְגַן עֵדֶן שֶׁנִּכְנַס עִמּוֹ וּבֵרְכוֹ, וּמִשּׁוּם כָּךְ לֹא תָלָה הַדָּבָר בַּלְּבוּשִׁים, אֶלָּא בְּיַעֲקֹב מַמָּשׁ, שֶׁרָאָה שֶׁבּוֹ הָיָה הַדָּבָר תָּלוּי (וראוי היה להתברך) וְנִרְאֶה, וּזְכוּתוֹ עוֹלָה לְהִתְבָּרֵךְ, וְנִכְנַס עִמּוֹ גַּן עֵדֶן. וּמִשּׁוּם כָּךְ, כְּשֶׁהִתְרַעֵם עֵשָׂו, אָמַר גַּם בָּרוּךְ יִהְיֶה.</p>\n<p>אָמַר רַבִּי יִצְחָק, לֹא הִצְטָרְכָה תּוֹרָה לִכְתֹּב אֶלָּא מֵהַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים. מָה הַטַּעַם? מִשּׁוּם שֶׁזֶּה הָיָה תְּחִלַּת הַלְּבָנָה, וְעַל זֶה הַתּוֹרָה הִצְטָרְכָה לִכְתֹּב מִכָּאן, שֶׁהֲרֵי בַּקָּדוֹשׁ-בָּרוּךְ-הוּא נִקְשָׁר הַדָּבָר.</p>\n<p>וְלֹא קָשֶׁה שֶׁלֹּא כָתוּב זֹאת, הַחֹדֶשׁ הַ את, שֶׁהֲרֵי זֶה וְזֹאת מִתְקַשְּׁרִים כְּאֶחָד. וּבְמָקוֹם שֶׁיֵּשׁ זָכָר וּנְקֵבָה כְּאֶחָד, אֵין הַשֶּׁבַח אֶלָּא לַזָּכָר, וְעַל זֶה רִאשׁוֹן הוּא לָכֶם לְחָדְשֵׁי הַשָּׁנָה, לְחָדְשֵׁי הַשָּׁנָה וַדַּאי. אָמַר רַבִּי יְהוּדָה, לָמָּה פַּעֲמַיִם לָכֶם? אָמַר רַבִּי יִצְחָק, מֵהֶם נִשְׁמָע יוֹתֵר, כְּמוֹ שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ. הִתְקַשְּׁרוּת זוֹ לָכֶם, וְלֹא לִשְׁאָר הָעַמִּים.</p>"],[9522011590,"<p>דַּבְּרוּ אֶל כָּל עֲדַת יִשְׂרָאֵל לֵאמֹר בֶּעָשּר לַחֹדֶשׁ הַזֶּה וְיִקְחוּ לָהֶם אִישׁ שֶׂה וְגוֹ'. בֶּעָשּר, לָמָּה בֶּעָשּר? אָמַר רַבִּי אַבָּא, בִּזְמַן שֶׁמֵּאִיר הַיּוֹבֵל לַלְּבָנָה, שֶׁכָּתוּב בַּיּוֹבֵל, בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפּוּרִים הוּא.</p>\n<p>וְיִקְחוּ לָהֶם אִישׁ שֶׂה לְבֵית אָבת, לָמָּה? מִשּׁוּם שֶׁבִּזְמַן זֶה צָרִיךְ לִמְשֹׁךְ אוֹתוֹ, שֶׁהֲרֵי שָׁנִינוּ, בְּדָבָר זֶה נִשְׁבָּר הַכֶּתֶר (אחד) הַתַּחְתּוֹן שֶׁנֶּאֱחָזִים בּוֹ כָּל שְׁאָר הַכְּתָרִים הַתַּחְתּוֹנִים. וְעַל זֶה פֵּרַשׁ מֹשֶׁה וְאָמַר מִשְׁכוּ וּקְחוּ לָכֶם צֹאן, כְּמוֹ שֶׁכָּתוּב צֹאן וְעֶבֶד וְשִׁפְחָה.</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, עֲשׂוּ אַתֶּם מַעֲשֶׂה לְמַטָּה, וַאֲנִי אֶשְׁבֹּר אֶת כֹּחָם לְמַעְלָה. וּכְמוֹ שֶׁאַתֶּם תַּעֲשׂוּ בָּאֵשׁ, שֶׁכָּתוּב כִּי אִם צְלִי אֵשׁ - אַף אֲנִי כָּךְ אַעֲבִיר אוֹתוֹ בָּאֵשׁ בִּנְהַר דִּינוּר.</p>\n<p>לָמָּה נִמְשַׁךְ בַּעֲשָׂרָה וְנִשְׁחַט בְּאַרְבָּעָה עָשָׂר? אָמַר רַבִּי אַבָּא, בָּזֶה הִתְקַשְּׁרוּ יִשְׂרָאֵל אַרְבַּע מֵאוֹת שָׁנָה. וְאַף עַל גַּב שֶׁאַרְבַּע מֵאוֹת שָׁנָה לֹא הִשְׁתַּעְבְּדוּ בָהֶם, מִכָּל מָקוֹם, הוֹאִיל וְהָיָה עָתִיד לְהִתְקַשֵּׁר בָּהֶם, נֶחְשָׁב עָלָיו כְּאִלּוּ הִשְׁתַּעְבֵּד בָּהֶם כָּל אַרְבַּע מֵאוֹת שָׁנִים. מִשּׁוּם זֶה מְעַכְּבִים אוֹתוֹ אַרְבָּעָה יָמִים קָשׁוּר בִּרְשׁוּתָם שֶׁל יִשְׂרָאֵל, וְאַחַר כָּךְ וְשָׁחֲטוּ אֹתוֹ כֹּל קְהַל עֲדַת יִשְׂרָאֵל בֵּין הָעַרְבָּיִם.</p>\n<p>לָמָּה בֵּין הָעַרְבַּיִם? בְּשָׁעָה שֶׁהַדִּין תָּלוּי וּבְשָׁעָה שֶׁדָּבָר זֶה נִמְסַר לוֹ עַל יְדֵי אַבְרָהָם, שֶׁכָּתוּב (בראשית טו) וַיְהִי הַשֶּׁמֶשׁ לָבוֹא וְתַרְדֵּמָה נָפְלָה עַל אַבְרָם וְהִנֵּה אֵימָה חֲשֵׁכָה גְדֹלָה נֹפֶלֶת עָלָיו. אֵימָה - כֶּתֶר אֶחָד. חֲשֵׁכָה - כֶּתֶר אַחֵר. גְּדלָה - זוֹ הִיא הַגְּדוֹלָה מֵהַכֹּל. וְאַף עַל גַּב שֶׁבֵּאַרְנוּ פָּסוּק זֶה עַל שְׁאָר שִׁעְבּוּדֵיהֶם שֶׁל יִשְׂרָאֵל, וְהַכֹּל הָיָה. כְּמוֹ זֶה כִּי מָחֹה אֶמְחֶה, אַתֶּם מִלְּמַטָּה, וַאֲנִי מִלְמַעְלָה.</p>\n<p>שָׁנִינוּ, לֹא יָצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם עַד שֶׁנִּשְׁבְּרוּ כָּל הַשַּׁלִּיטִים שֶׁלְּמַעְלָה (מהשתלשלותם) מִשְּׁלִיטָתָם, וְיָצְאוּ יִשְׂרָאֵל מֵרְשׁוּתָם, וְנִכְנְסוּ לָרָשׁוּת הַקְּדוֹשָׁה הָעֶלְיוֹנָה בַּקָּדוֹשׁ- בָּרוּךְ-הוּא וְנִקְשְׁרוּ בוֹ. זֶהוּ שֶׁכָּתוּב כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים עֲבָדַי הֵם. מָה הַטַּעַם עֲבָדַי הֵם? אֲשֶׁר הוֹצֵאתִי אוֹתָם מֵאֶרֶץ מִצְרָיִם, שֶׁהוֹצֵאתִי אוֹתָם מֵרָשׁוּת אַחֶרֶת, וְהִכְנַסְתִּים בִּרְשׁוּתִי.</p>"],[9522011591,"<p>וְהַיְנוּ שֶׁאָמַר רַבִּי שִׁמְעוֹן, מַה זֶּה שֶׁכָּתוּב אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאֹר מִבָּתֵּיכֶם, כִּי כָּל אֹכֵל מַחְמֶצֶת? אֶלָּא כָּךְ בֵּאַרְנוּ, שְׂאוֹר זֶה וּמַחְמֶצֶת זוֹ הֵן דַּרְגָּה אַחַת, וְכֻלָּם אֶחָד. רָשֻׁיּוֹת אֲחֵרוֹת, אוֹתָם שַׁלִּיטִים הַמְמֻנִּים עַל שְׁאָר עַמִּים, וְקוֹרְאִים לָהֶם יֵצֶר הָרָע, רְשׁוּת אַחֶרֶת, אֵל נֵכָר, אֱלֹהִים אֲחֵרִים - אַף כָּךְ שְׂאוֹר וּמַחְמֶצֶת וְחָמֵץ, וְהַכֹּל אֶחָד. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל הַשָּׁנִים הַלָּלוּ עֲמַדְתֶּם בְּרָשׁוּת אַחֶרֶת, עֲבָדִים לְעַם אַחֵר. מִכָּאן וָהָלְאָה שֶׁאַתֶּם בְּנֵי חוֹרִין, אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאֹר מִבָּתֵּיכֶם. כָּל מַחְמֶצֶת לֹא תֹאכֵלוּ. וְלֹא יֵרָאֶה לְךְ חָמֵץ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם כָּךְ אָז גַּם כָּל יְמֵי הַשָּׁנָה, לָמָּה שִׁבְעַת יָמִים, שֶׁכָּתוּב שִׁבְעַת יָמִים שְׂאֹר לֹא יִמָּצֵא בְּבָתֵּיכֶם, שִׁבְעַת יָמִים וְלֹא יוֹתֵר? אָמַר לוֹ, כָּל זְמַן שֶׁהִתְחַיֵּב אָדָם לְהַרְאוֹת אֶת עַצְמוֹ בֶּן חוֹרִין - כָּךְ צָרִיךְ. כָּל זְמַן שֶׁלֹּא הִתְחַיֵּב - לֹא צָרִיךְ.</p>\n<p>לְמֶלֶךְ שֶׁעָשָׂה אָדָם אֶחָד קָצִין. כָּל אוֹתָם יָמִים שֶׁעָלָה לְדַרְגָּה זוֹ שָׂמַח, וְלָבַשׁ בִּגְדֵי כָבוֹד. אַחַר כָּךְ לֹא צָרִיךְ. לְשָׁנָה אַחֶרֶת שׁוֹמֵר אוֹתָם יָמִים שֶׁעָלָה לְכָבוֹד זֶה, וְלוֹבֵשׁ אוֹתָם בְּגָדִים, וְכָךְ כָּל שָׁנָה וְשָׁנָה. כָּךְ יִשְׂרָאֵל, כָּתוּב שִׁבְעַת יָמִים שְׂאֹר לֹא יִמָּצֵא, שֶׁהֵם יְמֵי שִׂמִחָה, יָמִים שֶׁעָלוּ לְכָבוֹד זֶה וְיָצְאוּ מִשִּׁעְבּוּד אַחֵר, וְלָכֵן שׁוֹמְרִים בְּכָל שָׁנָה וְשָׁנָה אֶת הַיָּמִים שֶׁעָלוּ לַכָּבוֹד הַזֶּה, וְיָצְאוּ מֵרָשׁוּת אַחֶרֶת וְנִכְנְסוּ בָּרָשׁוּת הַקְּדוֹשָׁה. וְעַל זֶה כָּתוּב שִׁבְעַת יָמִים מַצּוֹת תֹּאכֵלוּ.</p>"],[9522011592,"<p>אָמַר רַבִּי שִׁמְעוֹן, מַצַּת כָּתוּב, כְּמוֹ שֶׁנֶּאֱמַר מַרְאֹת אֱלֹהִים. וְלָמָּה נִקְרְאוּ מַצַּת? דִּין, דִּין קָדוֹשׁ, דִּין שֶׁנֶּאֱחָז בַּשֵּׁם הַקָדוֹשׁ, דִּין שֶׁלֹּא הָיָה קָשֶׁה כָּל אוֹתוֹ זְמַן בְּתוֹךְ יִשְׂרָאֵל, שֶׁהֲרֵי הַלְּבָנָה עוֹמֶדֶת בִּפְגָם, וְעַל שֶׁעוֹמֶדֶת הַלְּבָנָה בִּפְגִימָתָהּ כָּתוּב לֶחֶם עֹנִי.</p>\n<p>מָה הַטַּעַם עוֹמֶדֶת בִּפְגָם? מִשּׁוּם שֶׁלֹּא נִפְרְעוּ וְלֹא הִתְגַּלָּה אוֹת הַבְּרִית הַקָּדוֹשׁ. מְהוּלִים הָיוּ וְלֹא נִפְרְעוּ. מָתַי נִפְרְעוּ? בְּשָׁעָה שֶׁכָּתוּב (שמותטו) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. וְאַף עַל גַּב שֶׁבֵּאַרְנוּ פָּסוּק זֶה בְּדָבָר אַחֵר - הַכֹּל הָיָה וְרָאוּי.</p>\n<p>וְאִם תֹּאמַר שֶׁנִּפְרְעוּ בִּימֵי יְהוֹשֻׁעַ - לֹא כָּךְ, אֶלָּא אוֹתָם שֶׁכָּתוּב (יהושע ה) וְכָל הָעָם הַיִּלּוֹדִים בַּמִּדְבָּר בַּדֶּרֶךְ וְגוֹ'. אַחַר שֶׁנִּפְרְעוּ, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּהַתְחָלָה אֲכַלְתֶּם מַצּוֹת, כְּשֶׁעָמְדָה הַלְּבָנָה בִּפְגִימָתָהּ, וְנִקְרָא לֶחֶם עֹנִי. מִכָּאן וָהָלְאָה לֶחֶם זֶה יִהְיֶה מִמָּקוֹם אַחֵר. מַה הוּא? שֶׁכָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. לֹא מֵהַלְּבָנָה כְּמוֹ אוֹתוֹ זְמַן, אֶלָּא מִן הַשָּׁמַיִם מַמָּשׁ, כְּמוֹ שֶׁכָּתוּב וְיִתֵּן לְךְ הָאֱלֹהִים מִטַּל הַשָּׁמַים.</p>\n<p>וְיִשְׂרָאֵל הַקְּדוֹשִׁים שׁוֹמְרִים אוֹתָם יָמִים שֶׁנִּכְנְסוּ תַּחַת כַּנְפֵי הַשְּׁכִינָה, וְשׁוֹמְרִים אוֹתוֹ לֶחֶם שֶׁבָּא מִצִּדָּהּ, וְעַל זֶה כָּתוּב אֶת חַג הַמַּצּוֹת תִּשְׁמֹר וְגוֹ', וְכָתוּב וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת. מַה זֶּה וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת? כְּמוֹ שֶׁנֶּאֱמַר (שם יט) וּשְׁמַרְתֶּם אֶת בְּרִיתִי, וְהַכֹּל בְּדַרְגָּה אַחַת עוֹלֶה וְנֶאֱחָז.</p>\n<p>וְאִם תֹּאמַר, אֵיךְ מֹשֶׁה לֹא פָרַע אוֹתָם? אֶלָּא כְּדֵי שֶׁלֹּא יִתְעַכְּבוּ שָׁם יִשְׂרָאֵל עַד שֶׁיִּתְרַפְּאוּ, וְעַל זֶה כָּתוּב שִׁבְעַת יָמִים תֹּאכַל עָלָיו מַצּוֹת לֶחֶם עֹנִי. מָה הַטַּעַם לֶחֶם עֹנִי? מִשּׁוּם כִּי בְּחִפָּזוֹן יָצָאתָ וְגוֹ', וְכָתוּב וְלֹא יָכְלוּ לְהִתְמַהְמֵהַּ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁנִּכְנְסוּ יִשְׂרָאֵל לָאָרֶץ, נִכְנְסוּ מְהוּלִים וְנִפְרְעוּ, וּמַה כָּתוּב? (דברים ח) אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנֻת תֹּאכַל בָּהּ לֶחֶם. מַה זֶּה בְּמִסְכֵּנֻת? לֶחֶם עֹנִי. לָמָּה נִקְרָא לֶחֶם עֹנִי? מִשּׁוּם שֶׁהַלְּבָנָה עוֹמֶדֶת בִּפְגִימָתָהּ וְלֹא מִתְבָּרֶכֶת מִן הַשֶּׁמֶשׁ, וְלֹא מוּאֶרֶת מִן הַשֶּׁמֶשׁ, כְּמוֹ שֶׁנֶּאֱמַר כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְלֹא מוּאֶרֶת (מכל) מִיּוֹבֵל. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא נִפְרְעוּ. אֲבָל כָּאן שֶׁנִּמּוֹלוּ יִשְׂרָאֵל וְנִפְרְעוּ, לֹא תֶחְסַר כֹּל בָּהּ כָּתוּב, וְעַל זֶה לֹא בְמִסְכֵּנֻת תֹּאכַל בָּהּ לֶחֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא תֶחְסַר כֹּ\"ל בָּהּ. כְּמוֹ שֶׁחָסְרוּ לָהּ בְּמִצְרַיִם.</p>\n<p>וּבְכָל שָׁנָה וְשָׁנָה עוֹשִׂים יִשְׂרָאֵל זִכָּרוֹן שֶׁל מִצְרַיִם וְאוֹכְלִים, וְלֹא מִתְכַּלֶּה מִדּוֹרֵי דוֹרוֹת. וּמִשּׁוּם שֶׁלֹּא נִפְרְעוּ כָּאן בְּמִצְרַיִם, חָסְרוּ אוֹתוֹ, אֶת הַכֹּל הַזֶּה, וְהַלְּבָנָה עוֹמֶדֶת בִּפְגִימוּת. וְנִקְרֵאת לֶחֶם עֹנִי. עֹנִי כְּתַרְגּוּמוֹ מִסְכֵּנוּת. וּמַה שֶּׁאָכְלוּ אוֹתוֹ שָׁם בָּאָרֶץ, זֶה הָיָה בִּשְׁבִיל זִכְרוֹן מִצְרַיִם, וְזֶה לְדוֹרֵי דוֹרוֹת, וְלֶעָתִיד לָבא כָּתוּב (ישעיה ס) לֹא יָבֹא עוֹד שִׁמְשֵׁךְ וִירֵחֵךְ וְגוֹ'.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב בֶּעָשֹׂר לַחֹדֶשׁ הַזֶּה וְיִקְחוּ לָהֶם וְגוֹ'. וְכָתוּב אַךְ בֶּעָשּר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפּוּרִים הוּא. נִשְׁמָע כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב בֶּעָשֹׂר לַחֹדֶשׁ הַזֶּה. מַה זֶּה אוֹמֵר? אֶלָּא בֶּעָשֹׂר, דָּבָר זֶה תָּלוּי בֶּעָשׂוֹר. לַחֹדֶשׁ הַזֶּה? בַּחֹדֶשׁ הַזֶּה הָיָה צָרִיךְ (לכתב) ! אֶלָּא כְּשֶׁבָּא הַמִּנְהָג לַדַּרְגָּה הַזּוֹ, כָּתוּב לַחֹדֶשׁ הַזֶּה דַּוְקָא.</p>\n<p>וְיִקְחוּ לָהֶם שֶׂה לְבֵית אָבֹת שֶׂה לַבָּיִת. שָׁנִינוּ, שְׁלֹשָׁה קְשָׁרִים הֵם: בְּכוֹר בְּהֵמָה, בְּכוֹר הַשְּׁבִי, בְּכוֹר הַשִּׁפְחָה. (ששלשה קשרים) שֶׁכָּל הַשְּׁאָר נִקְשָׁרִים בִּשְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ שֶׁל מַעְלָה. וּבָזֶה שֶׁנִּקְרָא צֹאן הַכֹּל נִקְשָׁר, וְהַכֹּל כָּלוּל בְּצֹאן. נִקְשָׁר צֹאן בְּצֹאן, וְלֹא יָכוֹל לְהִפָּרֵד מִקְּשָׁרָיו, וּבָזֶה כֻּלָּם נִקְשְׁרוּ. וְעַל זֶה כָּתוּב וְהָיָה לָכֶם לְמִשְׁמֶרֶת. קִשְׁרוּ אוֹתוֹ בְּקֶשֶׁר, וְיִהְיֶה מָסוּר בְּיֶדְכֶם בִּרְשׁוּתְכֶם עַד שֶׁתִּשְׁחֲטוּ אוֹתוֹ וְתַעֲשׂוּ בוֹ דִּין. וְלֶעָתִיד לָבֹא כָּתוּב (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם. וְכָתוּב כִּי זֶבַח לַה' בְּבָצְרָה. וְכָתוּב (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9522011593,"<p>וַיִּשָּׂא הָעָם אֶת בְּצֵקוֹ טֶרֶם יֶחְמָץ וְגוֹ'. כ\"ה - מִצְוָה זוֹ לְבָעֵר חָמֵץ, שֶׁהֲרֵי מִצְוָה זוֹ נִמְסְרָה לְיִשְׂרָאֵל, וַיִּשָּׂא הָעָם אֶת בְּצֵקוֹ טֶרֶם יֶחְמָץ, וְכָתוּב שְׂאֹר לֹא יִמָּצֵא בְּבָתֵּיכֶם, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, וְהַסּוֹד בֵּאַרְנוּ, בֵּין חָמֵץ וּמַצָּה שֶׁל כַּמָּה מְקוֹמוֹת, זֶה יֵצֶר רַע, וְזֶה יֵצֶר טוֹב.</p>\n<p>כ\"ו - מִצְוָה אַחַר זוֹ לְסַפֵּר בְּשֶׁבַח יְצִיאַת מִצְרַיִם, שֶׁהִיא חוֹבָה עַל בֶּן אָדָם לְדַבֵּר בְּשֶׁבַח זֶה לְעוֹלָמִים. כָּךְ בֵּאַרְנוּ, כָּל אָדָם שֶׁמְּדַבֵּר בִּיצִיאַת מִצְרַיִם וּבְאוֹתוֹ סִפּוּר שָׂמֵחַ בְּשִׂמְחָה, עָתִיד הוּא לִשְׂמֹחַ בַּשְּׁכִינָה בָּעוֹלָם הַבָּא שֶׁהוּא שִׂמְחַת הַכֹּל, שֶׁהֲרֵי הוּא אָדָם שֶׁשָּׂמֵחַ בַּאֲדוֹנוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ בְּאוֹתוֹ סִפּוּר.</p>\n<p>בְּאוֹתָהּ שָׁעָה כּוֹנֵס הַקָּדוֹשׁ בָּרוּךְ הוּא לְכָל הַפָּמַלְיָא שֶׁלּוֹ, וְאָמַר לָהֶם: לְכוּ וְתִשְׁמְעוּ אֶת סִפּוּר הַשֶּׁבַח שֶׁלִּי שֶׁמְּדַבְּרִים הַבָּנִים שֶׁלִּי וּשְׂמֵחִים בִּגְאֻלָּתִי. אָז כֻּלָּם מִתְכַּנְּסִים, וּבָאִים וּמִתְחַבְּרִים עִם יִשְׂרָאֵל, וְשׁוֹמְעִים סִפּוּר הַשֶּׁבַח שֶׁשְּׂמֵחִים בְּחֶדְוַת גְּאֻלַּת אֲדוֹנָם. אָז בָּאִים וּמוֹדִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא עַל כָּל אוֹתָם נִסִּים וּגְבוּרוֹת, וּמוֹדִים לוֹ עַל הָעָם הַקָּדוֹשׁ שֶׁיֵּשׁ לוֹ בָּאָרֶץ שֶׁשְּׂמֵחִים בְּשִׂמְחַת הַגְּאֻלָּה שֶׁל אֲדוֹנָם.</p>\n<p>אָז מִתּוֹסֵף לוֹ כֹּחַ וּגְבוּרָה לְמַעְלָה, וְיִשְׂרָאֵל בְּאוֹתוֹ סִפּוּר נוֹתְנִים כֹּחַ לְרִבּוֹנָם, כְּמוֹ מֶלֶךְ שֶׁמּוֹסִיף כֹּחַ וּגְבוּרָה כְּשֶׁמְּשַׁבְּחִים גְּבוּרָתוֹ וּמוֹדִים לוֹ, וְכֻלָּם פּוֹחֲדִים מִפָּנָיו, וּמִתְעַלֶּה כְבוֹדוֹ עַל כֻּלָּם. וְלָכֵן יֵשׁ לְשַׁבֵּחַ וּלְדַבֵּר בְּסִפּוּר זֶה כְּמוֹ שֶׁנֶּאֱמַר. כְּמוֹ זֶה חוֹבָה עַל בֶּן אָדָם לְדַבֵּר תָּמִיד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְפַרְסֵם אֶת הַנֵּס בְּכָל אוֹתָם נִסִּים שֶׁעָשָׂה.</p>\n<p>וְאִם תֹּאמַר, לָמָּה זֶה חוֹבָה, וַהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ הַכֹּל, כָּל מַה שֶּׁהָיָה וְשֶׁיִּהְיֶה לְאַחַר מִכֵּן, מַדּוּעַ פִּרְסוּם זֶה לְפָנָיו, עַל מַה שֶּׁהוּא עוֹשֶׂה, וְהוּא יוֹדֵעַ? אֶלָּא וַדַּאי צָרִיךְ אָדָם לְפַרְסֵם אֶת הַנֵּס וּלְדַבֵּר לְפָנָיו בְּכָל מַה שֶּׁהוּא עָשָׂה, מִשּׁוּם שֶׁאוֹתָם דְּבָרִים עוֹלִים, וְכָל הַפָּמַלְיָא שֶׁלְּמַעְלָה מִתְכַּנֶּסֶת, וְרוֹאִים אוֹתָם וּמוֹדִים כֻּלָּם לַקָּדוֹשׁ- בָּרוּךְ-הוּא, וּמִתְעַלֶּה כְבוֹדוֹ עֲלֵיהֶם לְמַעְלָה וּלְמַטָּה.</p>\n<p>כְּמוֹ זֶה מִי שֶׁמְּדַבֵּר וּמְפָרֵט חֲטָאָיו עַל כָּל מַה שֶּׁעָשָׂה, אִם תֹּאמַר לְשֵׁם מָה צָרִיךְ? אֶלָּא הַמְקַטְרֵג עוֹמֵד תָּמִיד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי לְדַבֵּר וְלִתְבּעַ חֲטָאֵי בְּנֵי אָדָם וּלְבַקֵּשׁ עֲלֵיהֶם דִּין. כֵּיוָן שֶׁמַּקְדִּים אָדָם וּמְפָרֵט אֶת חֲטָאָיו כָּל אֶחָד וְאֶחָד, אֵינוֹ מַשְׁאִיר פִּתְחוֹן פֶּה לְאוֹתוֹ מְקַטְרֵג, וְלֹא יָכוֹל לְבַקֵּשׁ עָלָיו דִּין, שֶׁהֲרֵי תָּמִיד תּוֹבֵעַ דִּין בַּתְּחִלָּה, וְאַחַר כָּךְ מְדַבֵּר וּמְקַטְרֵג שֶׁפְּלוֹנִי עָשָׂה כָּךְ. וְלָכֵן צָרִיךְ לָאָדָם לְהַקְדִּים וּלְפָרֵט חֲטָאָיו.</p>\n<p>כֵּיוָן שֶׁהַמְקַטְרֵג רוֹאֶה אֶת זֶה, אֵין לוֹ עָלָיו פִּתְחוֹן פֶּה, וְאָז נִפְרָד מִמֶּנּוּ מִכֹּל וָכֹל. אִם שָׁב בִּתְשׁוּבָה - יָפֶה, וְאִם לֹא - הֲרֵי הַמְקַטְרֵג נִמְצָא עָלָיו וְאוֹמֵר: פְּלוֹנִי שֶׁבָּא לְפָנֶיךְ בְּעַזּוּת פָּנִים, בָּעַט בַּאֲדוֹנוֹ, חֲטָאָיו כָּךְ וְכָךְ. עַל זֶה יָפֶה שֶׁיִּזָּהֵר הָאָדָם בְּכָל אֵלֶּה, כְּדֵי שֶׁיִּמָּצֵא עֶבֶד נֶאֱמָן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>כ\"ז - מִצְוָה אַחַר זוֹ לֶאֱכֹל מַצָּה בְּפֶסַח, מִשּׁוּם שֶׁהוּא זִכָּרוֹן לְדוֹרֵי דוֹרוֹת עַל סוֹד הָאֱמוּנָה, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁיִּשְׂרָאֵל יָצְאוּ בְּאוֹתוֹ זְמַן מִסּוֹד שֶׁל אֱלִילִים אֲחֵרִים, וְנִכְנְסוּ בְּסוֹד הָאֱמוּנָה, וַהֲרֵי בֵּאֲרוּ אֶת הַסּוֹד הַזֶּה בְּכַמָּה מְקוֹמוֹת.</p>"],[9522011594,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה וְאַהֲרֹן זֹאת חֻקַּת הַפָּסַח וְגוֹ'. כ\"ח - מִצְוָה זוֹ לִשְׁחֹט פֶּסַח בֵּין הָעַרְבַּיִם בְּי\"ד בְּנִיסָן, זִכָּרוֹן לְאוֹתוֹ פֶּסַח מִצְרַיִם, וְזוֹהִי חוֹבָה עַל כֻּלָּם, כְּמוֹ שֶׁנֶּאֱמַר וְשָׁחֲטוּ אֹתוֹ כֹּל קְהַל עֲדַת יִשְׂרָאֵל בֵּין הָעַרְבָּיִם.</p>\n<p>פֶּסַח זֶה צָרִיךְ לִהְיוֹת שָׁמוּר מֵעֲשָׂרָה יָמִים וָהָלְאָה, שֶׁכָּתוּב בֶּעָשּר לַחֹדֶשׁ הַזֶּה וְיִקְחוּ לָהֶם וְגוֹ'. מָה הַטַּעַם? מִשּׁוּם שֶׁהֲרֵי אָז מַתְחִילָה הַלְּבָנָה לְהָאִיר מֵעֲשָׂרָה יָמִים וָהָלְאָה, עַד שֶׁנִּשְׁלֶמֶת בַּחֲמִשָּׁה עָשָׂר, וּבְאַרְבָּעָה עָשָׂר שֶׁיִּהְיֶה נִשְׁחָט בְּשָׁעָה שֶׁהַדִּין תָּלוּי עַל הָעוֹלָם.</p>\n<p>סוֹד זֶה לְהַעֲבִיר הַזֻּהֲמָה מִלִּפְנֵי הַבְּרִית הַקְּדוֹשָׁה, וְלֵהָנוֹת מֵאוֹתוֹ רֵיחַ שֶׁנּוֹדֵף מִצְּלִי הָאֵשׁ, וְעַל זֶה לֹא בָא אֶלָּא עַל הַשָּׂבָע, וְעַל זֶה וְכָל עָרֵל לֹא יֹאכַל בּוֹ. מִי שֶׁיֵּשׁ בּוֹ בְּרִית קֹדֶשׁ, יֹאכַל בּוֹ. מִי שֶׁאֵין בּוֹ בְּרִית קֹדֶשׁ, לֹא יֹאכַל בּוֹ. שֶׁזֶּה מִבְּנֵי הַבְּרִית הוּא לִשְׁבֹּר כֹּחַ שֶׁל חַיִל אַחֵר, לְהַעֲבִיר עָרְלָה מִלִּפְנֵי בְרִית. מִשּׁוּם כָּךְ זֶהוּ לַעֲשׂוֹת בִּבְנֵי בְרִית וְלֹא בִּבְנֵי עָרְלָה.</p>\n<p>כְּשֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְמִצְרַיִם, רָאָה אֶת הַדָּם שֶׁל אוֹתוֹ פֶּסַח שֶׁהָיָה רָשׁוּם עַל הַפֶּתַח, וְדַם הַבְּרִית, אֵיךְ הָיוּ עוֹמְדִים עַל הַפֶּתַח, שֶׁכָּתוּב וּלְקַחְתֶּם אֲגֻדַּת אֵזוֹב וּטְבַלְתֶּם בַּדָּם אֲשֶׁר בַּסַּף וְהִגַּעְתֶּם וְגוֹ'. אֵזוֹב, הֲרֵי בֵּאַרְנוּ שֶׁהוּא מַעֲבִיר רוּחוֹת רָעוֹת, וְכָל צַד שֶׁל רוּחַ רַע מַעֲבִיר בַּהִתְעוֹרְרוּת שֶׁלּוֹ, בַּגְּאֻלָּה הָעֶלְיוֹנָה שֶׁל יִשְׂרָאֵל.</p>\n<p>לֶעָתִיד לָבא יָבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא לַיֵּצֶר הָרָע וְיִשְׁחַט אוֹתוֹ. וְעַתָּה בִּגְאֻלָּה זוֹ כָּתוּב, וְשָׁחֲטוּ אֹתוֹ כֹּל קְהַל עֲדַת יִשְׂרָאֵל וְגוֹ'. זִכָּרוֹן שֶׁל לֶעָתִיד לָבא, בַּגְּאֻלָּה הָעֶלְיוֹנָה הַהִיא.</p>\n<p>עַל שְׁתֵּי הַמְּזוּזֹת וְעַל הַמַּשְׁקוֹף, בָּרֹשֶׁם הַזֶּה שֶׁל אוֹת יוֹ\"ד, וּבָרֹשֶׁם הַזֶּה שֶׁל הָאוֹת יוֹ\"ד, לְהַרְאוֹת אֶת רֹשֶׁם הַבְּרִית הַקָּדוֹשׁ, וְנִשְׁבֶּרֶת עָרְלָה מִלִּפְנֵי דַּם הַבְּרִית, רָשׁוּם עַל הַכֹּל, וּבָא דָם עַל דָּם. כְּשֶׁעוֹבֵר אוֹתוֹ הַמַּשְׁחִית, הָיָה רוֹאֶה דָם וּמִתְרַחֵק מֵהַבַּיִת, כְּמוֹ שֶׁנֶּאֱמַר וְלֹא יִתֵּן הַמַּשְׁחִית וְגוֹ'.</p>\n<p>אִם הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ הוֹרֵג, אָז לָמָּה כָּתוּב וְלֹא יִתֵּן הַמַּשְׁחִית, שֶׁמַּשְׁמָע שֶׁהַמַּשְׁחִית הָיָה הוֹלֵךְ, וְלֹא הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה הוֹרֵג, וְהַמַּשְׁחִית הָיָה הוֹלֵךְ לִמְצֹא עִלָּה לְיִשְׂרָאֵל. כֵּיוָן שֶׁהָיָה רוֹאֶה אוֹתוֹ שִׁבְרוֹן הָעָרְלָה בִּשְׁנֵי צְדָדִים, הָיָה בּוֹרֵחַ וְנִפְרָד מֵהֶם.</p>\n<p>וְעַל שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל אוֹתָם בְּכוֹרוֹת שֶׁל אוֹתוֹ הַצַּד, נָתַן בְּכוֹרוֹת שֶׁל יִשְׂרָאֵל לִגְאֻלָּה, שֶׁלֹּא יִמְצָא עֲלֵיהֶם הַצַּד הָאַחֵר עִלָּה כְּלָל, וּבַכֹּל שׁוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל כְּאָב עַל בָּנִים.</p>\n<p>בְּבַיִת אֶחָד יֵאָכֵל לֹא תוֹצִיא מִן הַבַּיִת וְגוֹ'. מִצְוָה כ\"ט זוֹ לֶאֱכֹל אֶת הַפֶּסַח הַזֶּה עַל מַצּוֹת וּמְרוֹרִים. מַצּוֹת - מַצַּת כָּתוּב. מַה זֶּה כְּנֶגֶד זֶה? אֶלָּא לְהַרְאוֹת גָּלוּת הַשְּׁכִינָה עִם יִשְׂרָאֵל בְּאוֹתָהּ הַמְּרִירוּת שֶׁלָּהֶם, שֶׁכָּתוּב וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה וְגוֹ'. כְּשֶׁאוֹכְלִים אֶת הַפֶּסַח הַזֶּה, לְהַרְאוֹת אֶת כָּל מַה שֶּׁעָשׂוּ לָהֶם בְּמִצְרַיִם בְּאוֹתָהּ גָּלוּת וּבְאוֹתוֹ שִׁעְבּוּד.</p>\n<p>מַה כָּתוּב? וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ, לְהַרְאוֹת בּוֹ קָלוֹן, וּבְכָל אוֹתָם אֱלִילֵי מִצְרַיִם. שֶׁהֲרֵי הָיוּ זוֹרְקִים בַּשּׁוּק אֶת הָעֲצָמוֹת שֶׁלּוֹ, וּבָאוּ הַכְּלָבִים וְגָרְרוּ אוֹתָם מִמָּקוֹם לְמָקוֹם, וְזֶה הָיָה קָשֶׁה לָהֶם מֵהַכֹּל, שֶׁהֲרֵי הָעֲצָמוֹת הֵן תִּקּוּן הַגּוּף, וְדוֹמִים לְגָוֶן אַחֵר, וְיִשְׂרָאֵל זָרְקוּ אוֹתָם לַשּׁוּק בְּדֶרֶךְ קָלוֹן, וְלָכֵן כָּתוּב וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ. אַתֶּם לֹא תִשְׁבְּרוּ, אֲבָל הַכְּלָבִים הָיוּ בָּאִים וּמְשַׁבְּרִים אוֹתוֹ.</p>\n<p>עוֹד, הַמִּצְרִים הָיוּ בָּאִים אַחַר כָּךְ וְהָיוּ רוֹאִים אוֹתָם עַצְמוֹת שֶׁהָיוּ לוֹקְחִים הַכְּלָבִים מִמָּקוֹם לְמָקוֹם וְשׁוֹבְרִים אוֹתָם, וְהָיוּ הַמִּצְרִים טוֹמְנִים אוֹתָם בֶּעָפָר, כְּדֵי שֶׁהַכְּלָבִים לֹא יִמְצְאוּ אוֹתָם, וְזֶהוּ בִּטּוּל שֶׁל עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת יוֹתֵר מֵהַצַּד שֶׁלָּהֶם. וּבָזֶה הִתְעַלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ וְנִכְפּוּ כָּל הַכֹּחוֹת הָאֲחֵרִים, שֶׁהֲרֵי אָז נִכְפּוּ יוֹתֵר, כְּשֶׁהַבִּטּוּל נִמְצָא מֵהַצַּד שֶׁלָּהֶם, וְלָכֵן יִשְׂרָאֵל לֹא בִטְּלוּ אוֹתָם, שֶׁכָּתוּב וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ.</p>"],[9522011595,"<p>קַדֶּשׁ לִי כָל בְּכוֹר פֶּטֶר רֶחֶם וְגוֹ'. מִצְוָה זוֹ לְקַדֵּשׁ בְּכוֹר בְּהֵמָה. וְעַם הָאָרֶץ צָרִיךְ שְׁנֵי דְבָרִים: אֶחָד שֶׁיִּהְיֶה פָּדוּי מִתַּחַת שִׁלְטוֹן הַיֵּצֶר הָרָע, שֶׁהוּא אֲדוֹנוֹ, כְּמוֹ שֶׁאָמַר יַעֲקֹב לְעֵשָׂו (בראשית לג) יַעֲבָר נָא אֲדנִי לִפְנֵי עַבְדּוֹ, בָּעוֹלָם הַזֶּה. אָדוֹן מִצַּד הָעֲווֹנוֹת, שֶׁהֵם רַבִּים עַל הַגּוּף. כְּמוֹ שֶׁבֵּאֲרוּהָ, רָשָׁע - יֵצֶר הָרָע שׁוֹפְטוֹ. צַדִּיק - יֵצֶר הַטּוֹב שׁוֹפְטוֹ. בֵּינוֹנִי - זֶה וָזֶה שׁוֹפְטוֹ. בֵּינוֹנִי הוּא אָח שֶׁל יֵצֶר הָרָע וְאָח שֶׁל יֵצֶר הַטּוֹב. אָחִי יְהִי לְךְ אֲשֶׁר לָךְ.</p>\n<p>וּכְשֶׁרַבּוֹת הַזְּכֻיּוֹת, הָרוּחַ שׁוֹבֵר שְׁתֵּי מִשְׁמָרוֹת - שֶׁל חֲמוֹר נוֹעֵר, וּכְלָבִים צוֹעֲקִים, וְעוֹלֶה לְמִשְׁמֶרֶת הַשַּׁחַר שֶׁבּוֹ הָאָדָם, וְחוֹזֵר הָאָדָם לִהְיוֹת אָדוֹן. זֶהוּ שֶׁכָּתוּב (שם לב) וַיְהִי לִי שׁוֹר וַחֲמוֹר צֹאן וְעֶבֶד וְשִׁפְחָה. וְעוֹלֶה לְדַרְגַּת אָדָם, שֶׁנֶּאֱמַר בּוֹ (שם א) וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹ', (שם ט) וּמוֹרַאֲכֶם וְחִתְּכֶם וְגוֹ'.</p>\n<p>וּכְשֶׁהַזְּכֻיּוֹת בֵּינוֹנִיּוֹת - (שם לב) וַיֵּאָבֵק אִישׁ עִמּוֹ, זְכֻיּוֹת וְחוֹבוֹת מִתְחַבְּקוֹת לַעֲרֹךְ קְרָב. מִצַּד הַזְּכֻיּוֹת - וַיַּרְא כִּי לֹא יָכֹל לוֹ. מִצַּד הָעֲבֵרוֹת - וַיִּגַּע בְּכַף יְרֵכוֹ, בְּגִיד הַנָּשֶׁה. נָשֶׁה לְשׁוֹן (שם מא) כִּי נַשַּׁנִי אֱלֹהִים אֶת כָּל עֲמָלִי. וְהוּא לְשׁוֹן נְשִׁיָּה. מָדוֹר אֶחָד מֵאוֹתָן שֶׁבַע הָאֲרָצוֹת. מִי שֶׁיּוֹרֵד לְשָׁם, נִשְׁכַּחַת מִמֶּנּוּ הַתּוֹרָה.</p>"],[9522011596,"<p>וְקֹדֶם שֶׁיָּבֹא אָדָם לָעוֹלָם הַזֶּה וְיֵצֵא מֵרֶחֶם אִמּוֹ - וַיֵּאָבֵק אִישׁ עִמּוֹ. זֶה גַּבְרִיאֵל, בְּאוֹתוֹ אָבָק שֶׁל עָפָר שֶׁנֶּאֱמַר (שם ב) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה. וְלִמֵּד אוֹתוֹ שִׁבְעִים לָשׁוֹן, וּמִשּׁוּם זֶה וַיִּיצֶר, אֶחָד יֵצֶר טוֹב, שֶׁלִּמֵּד אוֹתוֹ שִׁבְעִים לָשׁוֹן, וְאֶחָד יֵצֶר הָרָע שֶׁנֶּאֱבַק עִמּוֹ, שֶׁנֶּאֱמַר כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב בְּגִיד הַנָּשֶׁה, וּמָצָא מִמֶּנּוּ שִׁבְעִים לָשׁוֹן שֶׁלִּמֵּד אוֹתוֹ יֵצֶר הַטּוֹב.</p>\n<p>וְקֹדֶם כָּל זֶה יָרְדוּ עִמּוֹ אַרְבָּעָה מַלְאָכִים, שֶׁנֶּאֱמַר בָּהֶם (תהלים צא) כִּי מַלְאָכָיו יְצַוֶּה לָךְ. אִם יֵשׁ לוֹ זְכוּת אָבוֹת - אֶחָד מִיכָאֵל בִּזְכוּת אַבְרָהָם, וְהַשֵּׁנִי גַּבְרִיאֵל בִּזְכוּת יִצְחָק, וְהַשְּׁלִישִׁי שֶׁיּוֹרֵד עִמּוֹ נוּרִיאֵל בִּזְכוּת יַעֲקֹב, וְהָרְבִיעִי רְפָאֵל בִּזְכוּת אָדָם הָרִאשׁוֹן, וְיֵצֶר הַטּוֹב מֵעָלָיו.</p>\n<p>וְאִם אֵין לוֹ זְכוּת - הוֹלְכִים עִמּוֹ אַרְבָּעָה: עָון, מַשְׁחִית, אַף וְחֵמָה, וְיֵצֶר הָרָע מֵעֲלֵיהֶם לָדוּן אוֹתוֹ לָעוֹלָם הַבָּא. וְלָכֵן פֵּרְשׁוּהָ, רָשָׁע - יֵצֶר הָרָע שׁוֹפְטוֹ. צַדִּיק - יֵצֶר הַטּוֹב שׁוֹפְטוֹ. בֵּינוֹנִי - זֶה וָזֶה שׁוֹפְטוֹ. וְלָכֵן אִם הוּא בֵּינוֹנִי, גַּבְרִיאֵל שֶׁהוּא יֵצֶר טוֹב, וְסמא\"ל שֶׁהוּא יֵצֶר הָרָע, זֶה וָזֶה שׁוֹפְטוֹ.</p>\n<p>שֶׁבְּכָל אָדָם יֵשׁ אַרְבָּעָה יְסוֹדוֹת, אַרְבָּעָה מַלְאָכִים יוֹרְדִים עִמּוֹ מִיָּמִין, וְאַרְבָּעָה מִשְּׂמֹאל. אַרְבָּעָה מִיָּמִין: מִיכָאֵ\"ל, גַּבְרִיאֵ\"ל, רְפָאֵ\"ל, נוּרִיאֵ\"ל. וְאַרְבָּעָה מִשְּׂמֹאל: עָוֹ\"ן, מַשְׁחִי\"ת, אַ\"ף וְחֵמָ\"ה. מִצַּד הַגּוּף מְטַטְרוֹ\"ן יוֹרֵד עָלָיו מִיָּמִין, וְסמא\"ל מִשְּׂמֹאל.</p>\n<p>וְאֵין אָדָם שֶׁאֵין בּוֹ אַרְבָּעָה יְסוֹדוֹת, אֲבָל כְּפִי הַיְסוֹד שֶׁיַּקְדִּים בּוֹ, כָּךְ מַתְחִילִים הָאַרְבָּעָה הַלָּלוּ. אִם הַמַּזָּל שֶׁלּוֹ אַרְיֵ\"ה - מַקְדִּים מִיכָאֵ\"ל, וְאַחֲרָיו גַּבְרִיאֵ\"ל, וְאַחֲרָיו נוּרִיאֵ\"ל, וְאַחֲרָיו רְפָאֵ\"ל. וְאִם מַזָּלוֹ שׁוֹ\"ר - מַקְדִּים גַּבְרִיאֵ\"ל, וְאַחֲרָיו מִיכָאֵ\"ל, וְאַחֲרָיו נוּרִיאֵ\"ל, וְאַחֲרָיו רְפָאֵ\"ל. וְאִם מַזָּלוֹ נֶשֶׁ\"ר - מַקְדִּים נוּרִיאֵ\"ל, וְאַחֲרָיו מִיכָאֵ\"ל, וְאַחֲרָיו גַּבְרִיאֵ\"ל, וְאַחֲרָיו רְפָאֵ\"ל. וְאִם מַזָּלוֹ אָדָם - מַקְדִּים רְפָאֵ\"ל, וְאַחֲרָיו מִיכָאֵ\"ל, וְאַחֲרָיו גַּבְרִיאֵ\"ל, וְאַחֲרָיו נוּרִיאֵ\"ל.</p>\n<p>וְאוֹתָם שֶׁמִּצַּד יָמִין, מִצַּד שֶׁל מִיכָאֵל, כָּל הַפָּנִים שֶׁלּוֹ הֵם רַחֲמִים, בַּעַל גְּמִילוּת חֲסָדִים, פָּנִים לְבָנִים, וְאָדָם זֶה גּוֹמֵל חֶסֶד, חָסִיד וְחָכָם, אִם הִשְׁתַּדֵּל בַּתּוֹרָה. וְאִם לֹא - בְּהֵפֶךְ, מִצַּד שֶׁל יֵצֶר הָרָע, גַּזְלָן, טִפֵּשׁ, אֵין בּוֹ חֶסֶד. שֶׁלֹּא עַם הָאָרֶץ חָסִיד.</p>\n<p>מִצַד שֶׁל גַּבְרִיאֵל, אַרְבַּעַת הַפָּנִים שֶׁלּוֹ דִּין, מִדַּת הַדִּין עַל הָרְשָׁעִים, וּמִתְגָּרֶה בָּהֶם, כְּמוֹ שֶׁבֵּאֲרוּהָ, מֻתָּר לְהִתְגָּרוֹת בָּרְשָׁעִים בָּעוֹלָם הַזֶּה. גִּבּוֹר בְּיִצְרוֹ, יְרֵא חֵטְא, יִהְיֶה דַּיָּן, אִם יִתְעַסֵּק בַּתּוֹרָה וְגִבּוֹר בְּתַלְמוּדוֹ. בְּהֵפֶךְ מִצַּד שֶׁל יֵצֶר הָרָע - מִתְגָּרֶה בַּצַּדִּיקִים, דִּין קָשֶׁה לָהֶם, גִּבּוֹר בַּעֲבֵרָה לַעֲשׂוֹת אוֹתָהּ, אֵינוֹ יְרֵא חֵטְא, וְגוֹנֵי פָנָיו אֲדֻמִּים, עֵשָׂו שׁוֹפֵךְ דָּמִים.</p>\n<p>מִי שֶׁמַּזָּלוֹ נֶשֶׁ\"ר אֵינוֹ רַחֲמָן הַרְבֵּה, וְלֹא מִדַּת הַדִּין הַרְבֵּה, אֶלָּא בֵּינוֹנִי בַּיֵּצֶר הַטּוֹב בַּמִּדּוֹת הַטּוֹבוֹת שֶׁלּוֹ, וּבֵינוֹנִי בַּיֵּצֶר הָרָע בַּמִּדּוֹת הָרָעוֹת, וְלוֹ פָּנִים לְבָנִים וַאֲדֻמִּים.</p>\n<p>מִי שֶׁמַּזָּלוֹ אָדָם, מִצַּד הַטּוֹב, כָּלוּל מִכָּל מִדּוֹת טוֹבוֹת, חָסִיד וְחָכָם וְגִבּוֹר בַּתּוֹרָה, יְרֵא חֵטְא, מְמֻלָּא בְּכָל מִדּוֹת טוֹבוֹת, וְגוֹן פָּנָיו שְׁחוֹרִים. וּמִצַּד שֶׁל יֵצֶר הָרָע מְמֻלָּא מִכָּל הַמִּדּוֹת הָרָעוֹת.</p>\n<p>וְאִם חֲטָאֵי הָאָדָם רַבִּים, שׁוֹלְטִים עָלָיו כָּל הַמַּחֲנוֹת שֶׁל הַיֵּצֶר הָרָע, עַד שֶׁמִּסְתַּלְּקִים מִמֶּנּוּ כָּל מַחֲנוֹת הַיֵּצֶר הַטּוֹב, וּמַמְלִיךְ עַל אֵיבָרָיו אֶת סמא\"ל וְכָל מַחֲנוֹתָיו.</p>\n<p>וְאִם זְכֻיּוֹתָיו רַבִּים, שׁוֹלְטִים כָּל מַחֲנוֹת יֵצֶר הַטּוֹב, עַד שֶׁיִּסְתַּלְּקוּ כָּל מַחֲנוֹת יֵצֶר הָרָע, וּמַמְלִיךְ עַל כָּל אֵיבָרָיו הַמַּחֲנוֹת שֶׁל הַיֵּצֶר הַטּוֹב. בְּאוֹתוֹ זְמַן שׁוֹלֵט עָלָיו שֵׁם יְהֹוָ\"ה.</p>\n<p>וְאִם הוּא בֵּינוֹנִי, צְבָא הַשָּׁמַיִם עוֹמְדִים עָלָיו מִימִינוֹ וּמִשְּׂמֹאלוֹ. אֵלּוּ מַיְמִינִים לִזְכוּת, וְאֵלּוּ מַשְׂמְאִילִים לְחוֹבָה, וּמִי שֶׁאַלִּים - גּוֹבֵר. וְלָכֵן פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, לְעוֹלָם יִרְאֶה אָדָם עַצְמוֹ כְּאִלּוּ כָּל הָעוֹלָם כֻּלּוֹ תָּלוּי בּוֹ.</p>\n<p>וּמִצַד שֶׁל מִיכָאֵל נִקְרָא בְּכוֹר, שֶׁדַּרְגָּתוֹ כֶּסֶף לָבָן, וּמִשּׁוּם כָּךְ פִּדְיוֹן הַבְּכוֹר כֶּסֶף, ה' סְלָעִים, כְּחֶשְׁבּוֹן ה' שֶׁל אַבְרָהָם, שֶׁאִם יַחְכִּים בַּתּוֹרָה, תִּתּוֹסֵף עָלָיו י', שֶׁהוּא קֹדֶשׁ, שֶׁבּוֹ צָרִיךְ לְקַדֵּשׁ בְּכוֹר בְּהֵמָה, שֶׁהַיְנוּ (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה'. וּבוֹ צָרִיךְ לְעַשֵּׂר וְלָדוֹת, שֶׁכָּל וָלָד הוּא מִצַּד שֶׁל בֶּן י\"ה, וְהוּא ו'.</p>\n<p>שֶׁכָּל הַחַיּוֹת שֶׁהֵן חַיּוֹת הַקֹּדֶשׁ, נִקְרְאוּ בְּאוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ. זֶהוּ שֶׁכָּתוּב (ישעיה מג) כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו. אֲפִלּוּ כָּל הַבְּרִיּוֹת שֶׁנִּבְרְאוּ בָהֶם, וְאֵין בְּרִיאָה שֶׁלֹּא נִרְשְׁמָה בַּשֵּׁם הַזֶּה, כְּדֵי לְהוֹדִיעַ לְמִי שֶׁבָּרָא אוֹתוֹ, וְהַיּוֹ\"ד הַזּוֹ הִיא דְּיוֹקָן שֶׁל רֹאשׁ שֶׁל כָּל הַבְּרִיּוֹת. ה' ה' דְּיוֹקָן שֶׁל חָמֵשׁ אֶצְבְּעוֹת הַיָּמִין, וְה' שֶׁל שְׂמֹאל. ו' דְּיוֹקַן הַגּוּף.</p>"],[9522011597,"<p>וְלָכֵן אָמַר, וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוֶה יֹאמַר קָדוֹשׁ. אֵין בְּכָל בְּרִיָּה שֶׁתִּשְׁוֶה כְּמוֹתִי, וְאַף עַל גַּב שֶׁבָּרָאתִי אוֹתָהּ כִּדְמוּת הָאוֹתִיּוֹת שֶׁלִּי, שֶׁאֲנִי יָכוֹל לִמְחוֹת אֶת אוֹתָהּ צוּרָה, וְלַעֲשׂוֹת אוֹתָהּ כַּמָּה פְעָמִים, וְאֵין אֱלוֹהַּ אַחֵר עָלַי שֶׁיָּכוֹל לִמְחוֹת אֶת צוּרָתִי, וְלָכֵן (דברים לב) כִּי לֹא כְצוּרֵנוּ צוּרָם וְאֹיְבֵינוּ פְּלִילִים.</p>\n<p>וְאִם יַקְשֶׁה אָדָם, שֶׁהֲרֵי כָּתוּב (שם ד) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה - הוּא יְתָרֵץ לוֹ, הֲרֵי תְּמוּנָה רָאִיתִי, שֶׁהֲרֵי כָּתוּב וּתְמוּנַת ה' יַבִּיט. וְלֹא בְּכָל תְּמוּנָה אַחֶרֶת (שברא ויצר באותיותיו) שֶׁל אָדָם שֶׁיָּצַר בְּאוֹתִיּוֹתָיו, וְלָכֵן אָמַר וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוֶה וְאֶל מִי תְדַמְּיוּן אֵל וּמַה דְּמוּת תַּעַרְכוּ לוֹ.</p>\n<p>וַאֲפִלּוּ תְּמוּנָה זוֹ אֵין לוֹ בִּמְקוֹמוֹ, אֶלָּא כְּשֶׁיּוֹרֵד לִמְלֹךְ עַל הַבְּרִיּוֹת וּמִתְפַּשֵּׁט עֲלֵיהֶם, יֵרָאֶה לָהֶם לְכָל אֶחָד כְּפִי מַרְאֶה וְחִזָּיוֹן וְדִמְיוֹן שֶׁלָּהֶם, וְזֶהוּ וּבְיַד הַנְּבִיאִים אֲדַמֶּה.</p>\n<p>וְלָכֵן הוּא יֹאמַר, אַף עַל פִּי שֶׁאֲנִי אֲדַמֶּה לָכֶם בִּדְיוֹקַנְכֶם, אֶל מִי תְדַמְּיוּנִי וְאֶשְׁוֶה. שֶׁהֲרֵי קֹדֶם שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא דְּיוֹקָן בָּעוֹלָם וְצִיֵּר צוּרָה, הָיָה הוּא יְחִידִי בְּלִי צוּרָה וְדִמְיוֹן, וּמִי (ויש) שֶׁנּוֹדַע לוֹ קֹדֶם בְּרִיאָה שֶׁהוּא מִחוּץ לַדְּיוֹקָן, אָסוּר לַעֲשׂוֹת לוֹ צוּרָה וּדְמוּת אוֹ דְיוֹקָן בָּעוֹלָם, לֹא בָּאוֹת ה' וְלֹא בָּאוֹת י', וַאֲפִלּוּ בַּשֵּׁם הַקָּדוֹשׁ, וְלֹא בְּשׁוּם אוֹת וּנְקֻדָּה בָּעוֹלָם, וְזֶהוּ כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה, מִכָּל דָּבָר שֶׁיֵּשׁ בּוֹ תְּמוּנָה וְדִמְיוֹן לֹא רְאִיתֶם.</p>\n<p>אֲבָל אַחַר שֶׁעָשָׂה דְּיוֹקָן זֶה שֶׁל הַמֶּרְכָּבָה שֶׁל אָדָם עֶלְיוֹן, יָרַד לְשָׁם, וְנִקְרָא בְּאוֹתוֹ דְּיוֹקָן יְהֹוָ\"ה, כְּדֵי שֶׁיֵּדְעוּ אוֹתוֹ בַּמִּדּוֹת שֶׁלּוֹ בְּכָל מִדָּה וּמִדָּה, וְקָרָא: אֵל, אֱלֹהִים, שַׁדַּי, צְבָאוֹת, אהי\"ה. כְּדֵי שֶׁיֵּדְעוּ אוֹתוֹ בְּכָל מִדָּה וּמִדָּה אֵיךְ יִתְנַהֵג הָעוֹלָם, בְּחֶסֶ\"ד וּבְדִין, כְּפִי מַעֲשֵׂי בְּנֵי הָאָדָם, שֶׁאִם לֹא יִתְפַּשֵּׁט אוֹרוֹ עַל כָּל הַבְּרִיּוֹת, אֵיךְ יֵדְעוּ אוֹתוֹ וְאֵיךְ יִתְקַיֵּם? (ישעיה ז) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ.</p>\n<p>אוֹי לְמִי שֶׁיַּשְׁוֶה אוֹתוֹ לְשׁוּם מִדָּה, וַאֲפִלּוּ מֵעֶשֶׂר הַמִּדּוֹת הַלָּלוּ שֶׁלּוֹ, כָּל שֶׁכֵּן לִבְנֵי הָאָדָם (איוב ד) אֲשֶׁר בֶּעָפָר יְסוֹדָם, שֶׁכָּלִים וְנִפְסָדִים. אֶלָּא הַדִּמְיוֹן שֶׁלּוֹ כְּפִי שִׁלְטוֹנוֹ עַל אוֹתָהּ הַמִּדָּה, וַאֲפִלּוּ עַל כָּל הַבְּרִיּוֹת, וּלְמַעְלָה מֵאוֹתָהּ מִדָּה. וּכְשֶׁמִּסְתַּלֵּק מִמֶּנָּה, אֵין לוֹ מִדָּה וְלֹא דִמְיוֹן וְלֹא צוּרָה.</p>\n<p>כְּמוֹ שֶׁהַיָּם, שֶׁאֵין בַּמַּיִם שֶׁל הַיָּם שֶׁיּוֹצְאִים מִמֶּנּוּ תְּפִיסָה כְּלָל וְלֹא צוּרָה, אֶלָּא שֶׁהִתְפַּשְּׁטוּת שֶׁל הַמַּיִם שֶׁל הַיָּם עַל כְּלִי שֶׁהוּא אֶרֶץ, נַעֲשֶׂה דִמְיוֹן, וְיָכֹלְנוּ לַעֲשׂוֹת חֶשְׁבּוֹן שָׁם, כְּמוֹ הַמָּקוֹר שֶׁל הַיָּם - הֲרֵי אֶחָד. יוֹצֵא מִמֶּנּוּ מַעְיָן כְּפִי הִתְפַּשְּׁטוּתוֹ בְּאוֹתוֹ הַכְּלִי, כְּמוֹ עִגּוּל שֶׁהוּא י' - הֲרֵי מָקוֹר אֶחָד, וּמַעְיָן שֶׁיּוֹצֵא מִמֶּנּוּ - הֲרֵי שְׁנַיִם.</p>\n<p>אַחַר כָּךְ עוֹשֶׂה כְּלִי גָּדוֹל כְּמוֹ מִי שֶׁעוֹשֶׂה (שחפר) חֲפִירָה גְּדוֹלָה שֶׁמִּתְמַלֵּאת מִמַּיִם שֶׁיּוֹצְאִים מִמַּעְיָן. אוֹתוֹ כְּלִי נִקְרָא יָם, וְהוּא כְּלִי שְׁלִישִׁי, וְאוֹתוֹ כְּלִי גָּדוֹל שֶׁנֶּחֱלָק לְשִׁבְעָה נְחָלִים כְּפִי כֵּלִים אֲרֻכִּים. כָּךְ מִתְפַּשְּׁטִים הַמַּיִם מִן הַיָּם לְשִׁבְעָה נְחָלִים (כלים), וַהֲרֵי מָקוֹר וּמַעְיָן וְיָם וְשִׁבְעָה נְחָלִים הֵם עֲשָׂרָה. וְאִם יִשְׁבֹּר הָאֻמָּן אֶת הַכֵּלִים הַלָּלוּ שֶׁתִּקֵּן, יַחְזְרוּ הַמַּיִם לַמָּקוֹר, וְיִשָּׁאֲרוּ כֵלִים שְׁבוּרִים יְבֵשִׁים בְּלִי מַיִם.</p>\n<p>כָּךָ עִלַּת הָעִלּוֹת עָשָׂה עֶשֶׂר סְפִירוֹת, וְקָרָא לַכֶּתֶר מָקוֹר, וּבוֹ אֵין סוֹף לִנְבִיעַת אוֹרוֹ, וְלָכֵן קָרָא לְעַצְמוֹ אֵין סוֹף, וְאֵין לוֹ דְּמוּת וְצוּרָה, וְשָׁם אֵין כְּלִי לִתְפֹּס אוֹתוֹ, לָדַעַת בּוֹ יְדִיעָה כְּלָל. וְלָכֵן אָמְרוּ בּוֹ, בַּמֻּפְלָא מִמְּךְ אַל תִּדְרשׁ וּבַמְכֻסֶּה מִמְּךְ אַל תַּחְקֹר.</p>\n<p>אַחַר כָּךְ עָשָׂה כְּלִי קָטָן, וְזֶה י', וְהִתְמַלֵּא מִמֶּנּוּ, וְקָרָא לוֹ מַעְיָן נוֹבֵעַ חָכְמָה, וְקָרָא אֶת עַצְמוֹ בּוֹ חָכָם, וּלְאוֹתוֹ הַכְּלִי קָרָא לוֹ חָכְמָ\"ה. וְאַחַר כָּךְ עָשָׂה כְּלִי גָּדוֹל, וְקָרָא לוֹ יָם, וְקָרָא לוֹ בִּינָה, וְהוּא קָרָא אֶת עַצְמוֹ מֵבִין בָּהּ.</p>\n<p>חָכָם מֵעַצְמוֹ וּמֵבִין מֵעַצְמוֹ, כִּי חָכְמָה לֹא נִקְרֵאת חָכְמָה מֵעַצְמָהּ, אֶלָּא מִשּׁוּם אוֹתוֹ חָכָם שֶׁמִּלֵּא אוֹתָהּ מִמַּעְיָנוֹ. וְהִיא לֹא נִקְרֵאת בִּינָה מֵעַצְמָהּ, אֶלָּא עַל שֵׁם (בגלל) אוֹתוֹ מֵבִין שֶׁמִּלֵּא אוֹתָהּ מִמֶּנּוּ, שֶׁאִם הָיָה מִסְתַּלֵּק מִמֶּנָּה, הִיא תִּשָּׁאֵר יְבֵשָׁה. זֶהוּ שֶׁכָּתוּב (איוב יד) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחֱרַב וְיָבֵשׁ.</p>\n<p>גְּדֻלָּ\"ה, גְּבוּרָ\"ה, תִּפְאֶרֶ\"ת, נֵצַ\"ח, הוֹ\"ד, יְסוֹ\"ד, מַלְכוּ\"ת. וְקָרָא אֶת עַצְמוֹ גָּדוֹל בַּגְּדֻלָּ\"ה וְחָסִי\"ד. גִּבּוֹר בַּגְּבוּרָ\"ה. מְפֹאָר בַּתִּפְאֶרֶ\"ת. בַּעַל נִצְחוֹן קְרָבוֹת בְּנֵצַ\"ח נְצָחִים. וּבַהוֹ\"ד קָרָא אֶת שְׁמוֹ הוֹד יוֹצְרֵנוּ. וּבַיְסוֹד קָרָא שְׁמוֹ צַדִּיק. וּבַיְסוֹ\"ד הַכֹּל סָמוּךְ בּוֹ, כָּל הַכֵּלִים וְכָל הָעוֹלָמוֹת. וּבַמַּלְכוּת קָרָא שְׁמוֹ מֶלֶךְ. וְלוֹ הַגְּדֻלָּ\"ה וְהַגְּבוּרָ\"ה וְהַתִּפְאֶרֶ\"ת וְהַנֵּצַ\"ח וְהַהוֹ\"ד כִּי כֹל בַּשָּׁמַיִם, שֶׁהוּא צַדִּי\"ק. וְלוֹ הַמַּמְלָכָה, שֶׁהִיא מַלְכוּ\"ת.</p>\n<p>הַכֹּל בִּרְשׁוּתוֹ לְחַסֵּר בַּכֵּלִים וּלְהוֹסִיף בָּהֶם נְבִיעָה וּלְחַסֵּר כְּפִי רְצוֹנוֹ (בהם), וְאֵין עָלָיו אֱלוֹהַּ שֶׁיּוֹסִיף בּוֹ אוֹ יִגְרַע בּוֹ.</p>\n<p>אַחַר כָּךְ עָשָׂה מְשַׁמְּשִׁים לַכֵּלִים הַלָּלוּ, כִּסֵּא בְּאַרְבָּעָה עַמּוּדִים, וְשֵׁשׁ דְּרָגוֹת לַכִּסֵּא - הֲרֵי עֶשֶׂר. וְהַכֹּל הוּא בַּכִּסֵּא. כְּמוֹ כּוֹס שֶׁל בְּרָכָה שֶׁתִּקְּנוּ בוֹ עֲשָׂרָה דְבָרִים מִשּׁוּם הַתּוֹרָה שֶׁנִּתְּנָה בְּעֶשֶׂר דִּבְּרוֹת, וּמִשּׁוּם הָעוֹלָם שֶׁהוּא מַעֲשֵׂה בְרֵאשִׁית שֶׁנִּבְרָא בַּעֲשָׂרָה מַאֲמָרוֹת.</p>\n<p>וְתִקֵּן לַכִּסֵּא כִּתּוֹת לְשַׁמֵּשׁ אוֹתוֹ, שֶׁל אוֹתָם מַלְאָכִים, אֶרְאֶלִּים, שְׂרָפִים, חַיּוֹת, אוֹפַנִּים, חַשְׁמַלִּים, אֵלִים, אֱלֹהִים, בְּנֵי אֱלֹהִי\"ם, אִישִׁי\"ם. וּלְאֵלֶּה הוּא עָשָׂה שַׁמָּשִׁים, סמא\"ל וְכָל הַכִּתּוֹת שֶׁלּוֹ, שֶׁהֵם כְּמוֹ עֲנָנִים לִרְכַּב בָּהֶם לָרֶדֶת לָאָרֶץ, וְהֵם כְּמוֹ סוּסִים לָהֶם.</p>\n<p>וּמִנַּיִן לָנוּ שֶׁעֲנָנִים נִקְרְאוּ מֶרְכָּב? זֶהוּ שֶׁכָּתוּב (ישעיה יט) הִנֵּה ה' רֹכֵב עַל עָב קַל וּבָא מִצְרַיִם. וְזֶהוּ מְמֻנֶּה שֶׁל מִצְרַיִם. וּמִיָּד שֶׁרָאוּ (ממגה) שֶׁאֱלוֹהַּ שֶׁהוּא אֱלוֹהַּ מְמֻנֶּה שֶׁלָּהֶם, רָאוּ אוֹתוֹ כְּמוֹ סוּס תַּחַת מֶרְכַּבְתּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִיָּד וְנָעוּ אֱלִילֵי מִצְרַיִם מִפָּנָיו, וּלְבַב מִצְרַיִם יִמַּס, נָעוּ מֵאֱמוּנָה שֶׁלָּהֶם, וְלִבָּם נָמַס כַּדּוֹנַג מֵאוֹתָהּ אֱמוּנָה, וְאוֹמְרִים: וְכִי עַד עַכְשָׁו אֱמוּנָה מְמֻנֶּה שֶׁלָּנוּ כְּמוֹ סוּס, הָיָה נָע לֵב שֶׁלָּהֶם מֵהָאֱמוּנָה שֶׁלָּהֶם וְנָמֵס כַּדּוֹנַג. וּמִנַּיִן לָנוּ שֶׁיִּמַּס לְשׁוֹן נָמֵס כַּדּוֹנַג הוּא? כְּמוֹ שֶׁנֶּאֱמַר (תהלים כב) הָיָה לִבִּי כַּדּוֹנַג נָמֵס בְּתוֹךְ מֵעָי.</p>"],[9522011598,"<p>וְכָל פֶּטֶר חֲמֹר תִּפְדֶּה בְשֶׂה וְגוֹ' (שמות יג). (מצוה להביא קרבן) מִצְוָה זוֹ לִפְדּוֹת פֶּטֶר חֲמוֹר, וְלַעֲרֹף פֶּטֶר חֲמוֹר אִם לֹא יִפְדֶּה אוֹתוֹ, זֶהוּ שֶׁכָּתוּב וְאִם לֹא תִפְדֶּה וַעֲרַפְתּוֹ. וְסוֹד זֶה יֵצֶר הָרָע, שֶׁיָּכוֹל לַחֲזֹר בִּתְשׁוּבָה, (ואחר כך יצר הטוב) וְאַחַר כָּךְ יַחֲזֹר לִהְיוֹת יֵצֶר טוֹב, כְּמוֹ שֶׁבֵּאֲרוּהָ, אִם זָכָה - עֵזֶר, אִם לֹא זָכָה - כְּנֶגְדּוֹ. מִשּׁוּם שֶׁהֵם דְּיוֹקָן, אֶחָד שֶׁל שֶׂה, וְאֶחָד שֶׁל חֲמוֹר. וְאִם זָכָה לַחֲזר בִּתְשׁוּבָה, אַף עַל גַּב שֶׁהוּא חֲמוֹר עַם הָאָרֶץ, תִּפְדֶּה מִן הַגָּלוּת בְּשֶׂה, שֶׁהוּא (ירמיהנ) שֶׂה פְזוּרָה יִשְׂרָאֵל. וְאִם לֹא חָזַר בִּתְשׁוּבָה - וַעֲרַפְתּוֹ. הִשְׁוָה אוֹתוֹ לְעַם קְשֵׁה עֹרֶף, שֶׁעֲתִידִים לְהִמָּחוֹת מִסֵּפֶר הַחַיִּים, שֶׁעֲלֵיהֶם נֶאֱמַר (שמות לב) מִי אֲשֶׁר חָטָא לִי אֶמְחֶנּוּ מִסִּפְרִי.</p>"],[9522011599,"<p>וְהָיָה לְאוֹת עַל יָדְכָה וּלְטוֹטָפֹת בֵּין עֵינֶיךְ וְגוֹ'. מִצְוָה זוֹ מִצְוָה שֶׁנִּקְרֵאת בְּגָוֶן אַחֵר, שֶׁלֹּא נִקְרֵאת מִצְוָה אֶלָּא קְדֻשָּׁה, וְאֵלּוּ הֵן תְּפִלִּין, תְּפִלָּה שֶׁל יָד וּתְפִלָּה שֶׁל רֹאשׁ. תִּקּוּן פְּאֵר הַיֹּפִי שֶׁל גְּוָנִים עֶלְיוֹנִים, וְלָכֵן נִקְרָאִים טוֹטָפֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>וְכָתוּב כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ, יִשְׂרָאֵל הַקָּטָן, שְׁמַע יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא, הַיֹּפִי שֶׁל הַגְּוָנִים, לְמַעְלָה וּלְמַטָּה. יוֹסֵף עָלָה וְהִתְעַטֵּר בִּשְׁנֵי גְוָנִים (דרגות) - בַּתְּחִלָּה נַעַ\"ר, וּבַסּוֹף צַדִּי\"ק. כַּמָּה נָאִים לוֹ הַגְּוָנִים לְמַרְאֶה, וְסוֹד זֶה (בראשית לט) וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה. יָפֶה בִּשְׁנֵי צְדָדִים בִּשְׁתֵּי דְרָגוֹת וּבִשְׁנֵי גְוָנִים, עֶלְיוֹן וְתַחְתּוֹן.</p>\n<p>כָּתוּב (דברים ו) וְעָשִׂיתָ הַיָּשָׁר וְהַטּוֹב. הַיָּשָׁר - זוֹ תְּפִלָּה שֶׁל יָד, לְהַמְשִׁיךְ (להסמיך) אוֹתוֹ לִתְפִלִּין שֶׁל רֹאשׁ לְהִתְיַחֵד כְּאֶחָד. וּתְפִלָּה שֶׁל יָד מַקְדִּים לְשֶׁל רֹאשׁ, וְצָרִיךְ שֶׁלֹּא יִהְיֶה בָהֶם פֵּרוּד כְּלָל.</p>\n<p>מִי שֶׁמִּתְעַטֵּר בִּתְפִלִּין, עוֹמֵד בְּסוֹד שֶׁל גָּוֶן עֶלְיוֹן, וְעוֹמֵד בְּאוֹתָם שְׁנֵי סוֹדוֹת שֶׁאָמַרְנוּ כְּמוֹ יוֹסֵף, שֶׁנִּקְרָא נַעַר וְנִקְרָא צַדִּיק, בְּסוֹד שֶׁל עֶבֶד נֶאֱמָן, בְּסוֹד שֶׁל בֵּן יְחִידִי, וְאֵלֶּה הֵם תְּפִלָּה שֶׁל יָד וּתְפִלָּה שֶׁל רֹאשׁ, וְהֵם כְּלָל אֶחָד בְּלִי פֵרוּד.</p>\n<p>אַרְבַּע פָּרָשִׁיּוֹת שֶׁל תְּפִלִּין בְּאַרְבָּעָה בָּתִּים בְּאוֹתָן תְּפִלִּין שֶׁל רֹאשׁ, וּכְמוֹ שֶׁהֵם אַרְבַּע פָּרָשִׁיּוֹת בְּאוֹתָן תְּפִלִּין שֶׁל רֹאשׁ, אַף כָּךְ כֻּלָּן בִּתְפִלִּין שֶׁל יָד בְּבַיִת אֶחָד, שֶׁהֲרֵי בִּתְפִלָּה שֶׁל יָד אֵין לָהּ מֵעַצְמָהּ כְּלוּם, אֶלָּא מַה שֶּׁאוֹחֶזֶת מִלְמַעְלָה, וְסוֹד זֶה - (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. וּמִתּוֹךְ שֶׁאוֹחֶזֶת אוֹתָם מִלְמַעְלָה נִקְרֵאת תְּפִלָּה, וּמִתְקַדֶּשֶׁת בִּקְדֻשָּׁתָם (והכל) נִקְרֵאת קְדֻשָּׁה, וְנִקְרֵאת תְּפִלָּה, וְאָז נִקְרֵאת מַלְכוּת, מַלְכוּת שָׁמַיִם שְׁלֵמָה.</p>\n<p>אַרְבַּע פָּרָשִׁיּוֹת הֲרֵי בֵּאַרְנוּ אֶת הַסּוֹד שֶׁלָּהֶם בְּכַמָּה מְקוֹמוֹת, אֲבָל פָּרָשָׁה רִאשׁוֹנָה, קַדֶּשׁ לִי כָל בְּכוֹר, זֶהוּ סוֹד עֶלְיוֹן שֶׁכּוֹלֵל כָּל אַרְבָּעָה הַבָּתִּים בְּסוֹד הָאוֹר הָעֶלְיוֹן שֶׁיּוֹצֵא מֵאַיִן.</p>\n<p>וְכָל אוֹתָן אַרְבַּע נִרְמְזוּ כָּאן. קַדֶּשׁ - זוֹ קְדֻשָּׁה הָעֶלְיוֹנָה. סוֹד הַחָכְמָה הָעֶלְיוֹנָה, שֶׁמִּשָּׁם הַכֹּל מִתְקַדֵּשׁ בְּסוֹד הַגְּנִיזָה הָעֶלְיוֹנָה שֶׁנִּקְרֵאת קַדֶּשׁ. לִי - זוֹ בִּינָה, סוֹד הָעוֹלָם הָעֶלְיוֹן, הַהֵיכָל הַפְּנִימִי. (וסוד זה, (ויקרא כה) כי לי בני ישראל עבדים. (במדבר ג) כי לי כל בכור. (שמות יט) והייתם לי סגלה) כָּ\"ל - סוֹד הַחֶסֶד, בְּכָל מָקוֹם, בֵּין לְמַעְלָה בֵּין לְמַטָּה. בְּכוֹ\"ר - זֶה בֵּן בְּכוֹר, שֶׁכָּתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וּבֵן בְּכוֹר זֶה כּוֹלֵל כָּל הַצְּדָדִים וְכָל הַגְּוָנִים, וְלָכֵן הַכָּתוּב כּוֹלֵל אֶת כָּל הָאַרְבַּע בְּסוֹד הַחָכְמָה הָעֶלְיוֹנָה. אֲבָל זֶה בְּדֶרֶךְ כְּלָל, לָדַעַת שֶׁהַכֹּל כָּלוּל בָּזֶה. אֲבָל בְּדֶרֶךְ פְּרָט כָּל אֶחָד לְבַדּוֹ, זוֹהִי פָּרָשָׁה רִאשׁוֹנָה הַכּוֹלֶלֶת כָּל שְׁאָר הַפָּרָשִׁיּוֹת.</p>\n<p>פָּרָשָׁה שְׁנִיָּה - וְהָיָה כִּי יְבִיאֲךְ וְגוֹ'. זוֹ בִּינָה. שֶׁהֲרֵי בַּפָּרָשָׁה הַזּוֹ הִיא יְצִיאַת מִצְרַיִם, שֶׁהָיְתָה מִצַּד שֶׁל יוֹבֵל. וְלָכֵן הָרֵאשִׁית שֶׁלָּהּ וְהָיָ\"ה, שֶׁהֲרֵי דָבָר זֶה הוּא בַּיּוֹבֵל, וְלָכֵן שְׁמָהּ וְהָיָ\"ה (הויה), שֶׁאֵין וְהָיָה אֶלָּא בְּמָקוֹם זֶה, שֶׁהוּא עָתִיד לְהִמָּשֵׁךְ לְמַטָּה וּלְהָאִיר מְנוֹרוֹת וּלְהִמָּצֵא בְּדַרְגָּה תַּחְתּוֹנָה, (והיה, כמי שאומר על המלך שהוא קים (שיּהיה), עתיד להמשך למטה ולהאיר מנורות) וְהַכֹּל בְּסוֹד אֶחָד. וּמִשּׁוּם שֶׁהוּא בְּדֶרֶךְ טָמִיר, לֹא נִקְרָא בְגָלוּי בְּשֵׁם זֶה, אֶלָּא נִמְסַר לַחֲכָמִים לָדַעַת, וְעַל זֶה נִרְשַׁם בַּשֵּׁם הַקָּדוֹשׁ בַּדָּבָר הַזֶּה.</p>\n<p>פָּרָשָׁה שְׁלִישִׁית - שְׁמַע. זֶהוּ סוֹד הַיָּמִין, שֶׁנִּקְרָא חֶסֶד עֶלְיוֹן, שֶׁהוּא מְיַחֵד אֶת הַיִּחוּד שֶׁל הַכֹּל לְאַרְבָּעָה צְדָדִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְסַדֵּר בּוֹ אֶת סִדּוּר כָּל הָעוֹלָם, וְזֶהוּ שֶׁמִּתְפַּשֵּׁט לְכָל הַצְּדָדִים, אֲפִלּוּ בְּתוֹךְ הַתְּהוֹמוֹת הַתַּחְתּוֹנִים. בָּזֶה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הָעוֹלָם, כְּשֶׁהִתְעַטֵּף הַקָּדוֹשׁ בָּרוּךְ</p>\n<p>הוּא בְּעִטּוּף שֶׁל זהַר, וְזֶה שֶׁמְּיַחֵד אֶת הַיִּחוּד, וּמִשּׁוּם כָּךְ שְׁמַע סָמוּךְ לִוְהָיָ\"ה. הַיִּחוּד שֶׁל כָּל יוֹם הוּא יִחוּד לָדַעַת וְלָשִׂים אֶת הָרָצוֹן. הַיִּחוּד הַזֶּה הֲרֵי אָמַרְנוּ בְּכַמָּה מְקוֹמוֹת, יִחוּד שֶׁל כָּל יוֹם הוּא הַיִּחוּד שֶׁבְּפָסוּק שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה'. הֲרֵי כֻּלָּם אֶחָד, וְלָכֵן נִקְרָא אֶחָד. הֲרֵי הֵם שְׁלֹשָׁה שֵׁמוֹת, אֵיךְ הֵם אֶחָד? וְאַף עַל גַּב שֶׁקּוֹרְאִים אֶחָד, אֵיךְ הֵם אֶחָד?</p>\n<p>אֶלָּא בְּחֶזְיוֹן רוּחַ הַקֹּדֶשׁ נוֹדַע, וְהֵם בְּמַרְאֶה שֶׁל עַיִן סְתוּמָה, לָדַעַת שֶׁשְּׁלֹשָׁה אֵלֶּה אֶחָד. וְזֶהוּ סוֹד שֶׁל קוֹל שֶׁנִּשְׁמַע, קוֹל הוּא אֶחָד, וְהוּא שְׁלֹשָׁה גְוָנִים, אֵשׁ רוּחַ וּמַיִם, וְכֻלָּם אֶחָד בְּסוֹד שֶׁל הַקּוֹל. (ואינם אלא אחד) אַף כָּאן - ה' אֱלֹהֵינוּ ה' הֵם אֶחָד. שְׁלֹשָׁה גְוָנִים, וְהֵם אֶחָד.</p>\n<p>וְזְהִוּ הַקּוֹל שֶׁעָשָׂה הָאָדָם בְּיִחוּד, וְלָשִׂים אֶת רְצוֹנוֹ בַּיִּחוּד שֶׁל הַכֹּל, מֵאֵין סוֹף עַד סוֹף הַכֹּל, בַּקּוֹל הַזֶּה שֶׁעוֹשֶׂה בִּשְׁלֹשֶׁת אֵלֶּה שֶׁהֵם אֶחָד. וְזֶהוּ הַיִּחוּד שֶׁל כָּל יוֹם שֶׁהִתְגַּלָּה בַּסּוֹד שֶׁל רוּחַ הַקֹּדֶשׁ.</p>\n<p>וְכַמָּה גְוָנִים שֶׁל יִחוּד הִתְעוֹרְרוּ, וְכֻלָּם אֱמֶת. מִי שֶׁעוֹשֶׂה זֶה עוֹשֶׂה, וּמִי שֶׁעוֹשֶׂה זֶה עוֹשֶׂה. אֲבָל הַיִּחוּד הַזֶּה שֶׁאָנוּ מְעוֹרְרִים מִלְּמַטָּה בְּסוֹד שֶׁל קוֹל שֶׁהוּא אֶחָד, זֶהוּ בֵּרוּר הַדָּבָר, זֶה בִּכְלָל, וְאַחַר כָּךְ פְּרָט, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>פָּרָשָׁה רְבִיעִית הוּא סוֹד הַדִּין הַקָּשֶׁה - הִשָּׁמְרוּ לָכֶם. אֵלֶּה הֵן תְּפִלִּין שֶׁל רֹאשׁ, וּתְפִלִּין שֶׁל זְרוֹעַ כְּמוֹ זֶה בְּבַיִת אֶחָד, וַהֲרֵי הִתְעוֹרַרְנוּ בָהֶם, וְכֻלָּם סוֹד אֶחָד.</p>\n<p>קֶשֶׁר הַתְּפִלִּין שֶׁל רֹאשׁ הוּא דָּלֶ\"ת, וְעַל זֶה כָּתוּב (שמות לג) וְרָאִיתָ אֶת אֲחֹרָי. וְלָכֵן הוּא לְאָחוֹר, וְשָׁם נִקְשָׁר הַכֹּל בְּקֶשֶׁר אֶחָד.</p>\n<p>וְהִיא, כְּשֶׁמְּנִיחָה תְּפִלִּין אֵלּוּ שֶׁל זְרוֹעַ לְהִתְקַשֵּׁר, (יש קשר) אַחֵר, סוֹד הַבְּרִית הַקָּדוֹשׁ, סוֹד זֶה כְּמוֹ שֶׁהִתְעוֹרֵר בְּכַמָּה מְקוֹמוֹת, וְהַכֹּל סוֹד אֶחָד. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁיּוֹדְעִים סוֹד זֶה, וְצָרִיךְ אָדָם לַהֲנִיחָם כָּל יוֹם לִהְיוֹת בִּדְיוֹקָן עֶלְיוֹן, וְעָלָיו כָּתוּב וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךְ וְיָרְאוּ מִמֶּךָּ. (ע\"כ רעיא מהימנא) בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן:</p>"],[9522011600,"<p>וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְלֹא נָחָם אֱלֹהִים דֶּרֶךְ אֶרֶץ פְּלִשְׁתִּים וְגוֹ'. רַבִי שִׁמְעוֹן פָּתַח, (חבקוק ב) תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא עַל שִׁגְינוֹת. פָּסוּק זֶה קָשֶׁה, וְיֵשׁ לְהִסְתַּכֵּל בּוֹ מַה שּׁוֹנָה תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא יוֹתֵר מִכָּל שְׁאָר נְבִיאֵי הָעוֹלָם שֶׁלֹּא כָתוּב בָּהֶם תְּפִלָּה לִישַׁעְיָה הַנָּבִיא, אוֹ לְיִרְמְיָה, אוֹ לִיחֶזְקֵאל, אוֹ לְהוֹשֵׁעַ, אוֹ לִשְׁאָר נְבִיאֵי הָעוֹלָם?</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, אֱלִישָׁע זָכָה בָּעוֹלָם הַזֶּה מַה שֶּׁלֹּא זָכָה נָבִיא אַחֵר, פְּרָט לְמֹשֶׁה. (ועם כל זה לא רצה להטריח את רבונו) בא ראה מה כתוב, (מלכים בד) ויהי היום ויעבר אלישע אל שונם ושם אשה גדולה. מה זה אשה גדולה? אלא גדולה במעשיה, שכל בני (הדּור) הבית משתבחים בה, והיא עקר הבית. ומשום שבעלה לא היה מצוי בבית להיות עקר, לא נזכר הוא, אלא היא.</p>\n<p>וְעוֹד, וְשָׁם אִשָּׁה גְדוֹלָה - גְּדוֹלָה עַל כָּל שְׁאָר נְשׁוֹת הָעוֹלָם. שֶׁהֲרֵי שְׁאָר נְשׁוֹת הָעוֹלָם, כְּשֶׁרוֹאוֹת אוֹרֵחַ בַּבַּיִת, מִצְטַעֲרוֹת בּוֹ וְדוֹחֲקוֹת אוֹתוֹ, וְכָל שֶׁכֵּן לְהוֹצִיא עָלָיו מָמוֹן, וְהִיא שָׂמְחָה בָּאוֹרֵחַ וּלְהוֹצִיא עָלָיו מָמוֹן, כָּל שֶׁכֵּן כֵּיוָן שֶׁרָאֲתָה אֶת אֱלִישָׁע, שָׂמְחָה בּוֹ מְאֹד. וְעַל כֵּן הַשֶּׁבַח שֶׁל הַכֹּל הוּא שֶׁל הָאִשָּׁה, שֶׁהֲרֵי הָאוֹרֵחַ שֶׁל הַבַּיִת הוּא שֶׁל הָאִשָּׁה, וְלָכֵן כָּתוּב וְשָׁם אִשָּׁה גְדוֹלָה, גְּדוֹלָה עַל שְׁאָר הַנָּשִׁים.</p>\n<p>וַתֹּאמֶר אֶל אִישָׁהּ הִנֵּה נָא יָדַעְתִּי כִּי אִישׁ אֱלֹהִים קָדוֹשׁ הוּא. בַּמֶּה יָדְעָה? אֶלָּא הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁסָּדִין לָבָן שָׂמָה לוֹ בְּמִטָּתוֹ, וְלֹא רָאֲתָה בּוֹ קֶרִי מֵעוֹלָם, וְלֹא עָבַר זְבוּב עַל שֻׁלְחָנוֹ.</p>\n<p>הַדְּבָרִים הַלָּלוּ קָשִׁים. אִם תֹּאמַר שֶׁלֹּא רָאֲתָה בּוֹ קֶרִי, הֲרֵי רַבִּים הֵם בְּנֵי אָדָם כָּאֵלֶּה בָּעוֹלָם. מָה הַשֹּׁנִי כָּאן? וְאִם תֹּאמַר שֶׁלֹּא עָבַר זְבוּב עַל שֻׁלְחָנוֹ, לָמָּה כָּתוּב הִנֵּה נָא יָדַעְתִּי? וְכִי הִיא יָדְעָה וְלֹא אַחֵר? וַהֲרֵי כָּל אֵלּוּ שֶׁרָאוּהוּ אוֹכֵל בְּשֻׁלְחָנוֹ הָיוּ יוֹדְעִים!</p>\n<p>אֶלָּא יָפֶה אָמְרָה, אֲבָל הִנֵּה נָא יָדַעְתִּי - הִיא יָדְעָה וְלֹא אַחֵר, מִשּׁוּם שֶׁהִיא תִּקְנָה אֶת מִטָּתוֹ בְּשָׁעָה שֶׁשָּׁכַב בַּלַּיְלָה וּבְשָׁעָה שֶׁקָּם בַּבּקֶר. וְזֶה שֶׁאָמְרוּ שֶׁסָּדִין לָבָן שָׂמָה לוֹ בְּמִטָּתוֹ, כָּךְ הָיָה, וּבָזֶה הִיא יָדְעָה. שֶׁדֶּרֶךְ הָעוֹלָם, כֵּיוָן שֶׁעוֹמֵד אָדָם מִמִּטָּתוֹ, מַעֲלֶה הַסָּדִין שֶׁיָּשַׁן בּוֹ רֵיחַ מְנֻוָּל. וְזֶה, בְּשָׁעָה שֶׁלָּקְחָה אוֹתוֹ סָדִין מִמִּטָּתוֹ, הָיָה מַעֲלֶה רֵיחוֹת כְּרֵיחוֹת גַּן עֵדֶן. אָמְרָה, אִלּוּלֵי שֶׁקָּדוֹשׁ הוּא וּקְדֻשַּׁת אֲדוֹנוֹ עָלָיו, לֹא הָיָה מַעֲלֶה כָּזֶה רֵיחַ קָדוֹשׁ.</p>\n<p>מִשּׁוּם כָּךְ צָרִיךְ לִפְר!שׁ מִן הַבַּיִת, כִּי לֹא נִזְהָר אָדָם כָּל כָּךְ בַּבַּיִת. אֲבָל אָמְרָה, נַעֲשֶׂה נָּא עֲלִיַּת קִיר קְטַנָּה וְנָשִׂים לוֹ שָׁם מִטָּה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה. אַרְבָּעָה אֵלֶּה לָמָּה? אֶלָּא מִשּׁוּם שֶׁהֵם תִּקּוּן שֶׁל כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת עֲלִיַּת קִיר, וְכָךְ נִקְרֵאת, כְּמוֹ שֶׁכָּתוּב וַיַּסֵּב חִזְקִיָּה פָּנָיו אֶל הַקִּיר.</p>\n<p>מִטָה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה, הֵם אֵינָם כְּמוֹ תִּקּוּן הַשִּׁמּוּשׁ, שֶׁהֲרֵי צָרִיךְ בַּתְּחִלָּה כִּסֵּא, וְאַחַר כָּךְ שֻׁלְחָן, אַחַר כָּךְ מְנוֹרָה, אַחַר כָּךְ מִטָּה. לָמָּה הִקְדִּימָה מִטָּה? מִשּׁוּם שֶׁהִיא חֲבִיבָה עָלָיו יוֹתֵר מֵהַכֹּל, וּמַקְדִּים אָדָם מַה שֶּׁחָבִיב עָלָיו.</p>\n<p>וַיְהִי הַיּוֹם וַיָּבֹא שָׁמָּה. וַיְהִי הַיּוֹם, אֵיזֶהוּ יוֹם זֶה? אֶלָּא כְּמוֹ שֶׁבֵּאֲרוּהָ. וּבֹא רְאֵה, אוֹתוֹ יוֹם, יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה הָיָה, שֶׁבּוֹ נִפְקְדוּ עַקְרוֹת הָעוֹלָם וְנִפְקָדִים בּוֹ בְּנֵי הָעוֹלָם, קָרָא לַשּׁוּנַמִּית וְאָמַר, הִנֵּה חָרַדְתְּ אֵלֵינוּ אֶת כָּל הַחֲרָדָה הַזֹּאת. מִשּׁוּם כָּךְ הִצְטַעַרְתִּי לְעַיֵּן הַיּוֹם הַזֶּה בְּדִינֵי הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן בַּיּוֹם הַזֶּה אֶת הָעוֹלָם. וּמִשּׁוּם שֶׁנִּפְרַדְתִּי לְבַד בְּמָקוֹם זֶה, הִצְטָרַכְתִּי לְהִסְתַּכֵּל בָּרֹגֶז שֶׁל הָעוֹלָם.</p>\n<p>וּמֶה לַעֲשׂוֹת לָךְ הֲיֵשׁ לְדַבֶּר לָךְ אֶל הַמֶּלֶךְ אוֹ אֶל שַׂר הַצָּבָא, וְכִי דָבָר זֶה לְשֵׁם מָה הָאִשָּׁה צְרִיכָה, שֶׁהֲרֵי אֵינָהּ יוֹצֵאת וְלֹא הוֹלֶכֶת וְלֹא נִכְנֶסֶת לְהֵיכַל הַמֶּלֶךְ? אֶלָּא יוֹם זֶה הָיָה גּוֹרֵם, שֶׁכָּל בְּנֵי הָעוֹלָם יוֹשְׁבִים (עומדים) בְּדִין, וּבְאוֹתוֹ יוֹם נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ. הַמֶּלֶךְ הַמִּשְׁפָּט. אָמַר לָהּ, אִם אַתְּ צְרִיכָה בִּשְׁבִילֵךְ אֵצֶל הַמֶּלֶךְ הָעֶלְיוֹן עַל הַמַּעֲשִׂים שֶׁבְּיָדַיִךְ?</p>\n<p>וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת. מָה אָמְרָה? אֶלָּא בְּשָׁעָה (בזמן) שֶׁהַדִּין תָּלוּי בָּעוֹלָם, שֶׁלֹּא יִפָּרֵד אָדָם לְבַדּוֹ, וְלֹא יִהְיֶה רָשׁוּם לְמַעְלָה וְלֹא יַכִּירוּ אוֹתוֹ לְבַדּוֹ, שֶׁהֲרֵי בִּזְמַן (אחר) שֶׁהַדִּין תָּלוּי בָּעוֹלָם, אוֹתָם שֶׁרְשׁוּמִים וְנוֹדָעִים לְבַדָּם - אַף עַל גַּב שֶׁהֵם צַדִּיקִים, הֵם נִתְפָּסִים בָּרִאשׁוֹנָה. וְעַל כָּךְ לֹא צָרִיךְ לָאָדָם לְהִפָּרֵד מִן הָעָם לְעוֹלָם, שֶׁבְּכָל זְמַן רַחֲמֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעָם כֻּלָּם כְּאֶחָד. (ואין צריך האדם לפרש מן העם לעולם) וְלָכֵן אָמְרָה בְּתוֹךְ עַמִּי אָנֹכִי ישָׁבֶת, וְלֹא רוֹצָה לְהִפָּרֵד מֵהֶם, כְּמוֹ שֶׁעָשִׂיתִי עַד הַיּוֹם הַזֶּה.</p>\n<p>וַיֹּאמֶר גֵּיחֲזִי אֲבָל בֵּן אֵין לָהּ וְגוֹ'. אָמַר לָהּ אֱלִישָׁע, הֲרֵי וַדַּאי שֶׁהַשָּׁעָה עוֹמֶדֶת, שֶׁהֲרֵי הַיּוֹם גּוֹרֵם. וַיֹּאמֶר לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אַתְּ חֹבֶקֶת בֵּן. וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֵּן לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אֲשֶׁר דִּבֶּר אֵלֶיהָ אֱלִישָׁע. לַמּוֹעֵד וַדַּאי. אַחַר כָּךְ מֵת. מָה הַטַּעַם מֵת? אֶלָּא מִשּׁוּם שֶׁנִּתַּן לָהּ וְלֹא לְבַעְלָהּ. וְנִקְשַׁר מִמָּקוֹם שֶׁל נְקֵבָה. וּמִי שֶׁמִּתְקַשֵּׁר בִּנְקֵבָה, הַמָּוֶת מְזֻמָּן לְפָנָיו. מִנַּיִן לָנוּ שֶׁלָּהּ הוּא נִתַּן? שֶׁכָּתוּב אַתְּ חֹבֶקֶת בֵּן.</p>\n<p>בֹּא רְאֵה, בְּאַבְרָהָם כָּתוּב (בראשית יח) שׁוֹב אָשׁוּב אֵלֶיךְ, וְלֹא אֵלֶיהָ. אֵלֶיךְ וַדַּאי, בְּךְ נִקְשַׁר, וְלֹא בִּנְקֵבָה. מִי שֶׁבָּא מִצַּד הַנְּקֵבָה, הַמָּוֶת מַקְדִּים לְרַגְלָיו. וַתַּעַל וַתַּשְׁכִּבֵהוּ עַל מִטַּת אִישׁ הָאֱלֹהִים, מִשּׁוּם שֶׁשָּׁם רָאֲתָה קְדֻשָּׁה עֶלְיוֹנָה מֵהַכֹּל.</p>\n<p>וֶאֱמָר לָהּ הֲשָׁלוֹם לָךְ הֲשָׁלוֹם לְאִישֵׁךְ הֲשָׁלוֹם לַיָּלֶד. מִכָּאן שֶׁהִיא עִקַּר הַבַּיִת, וְלֹא עוֹד, אֶלָּא שֶׁהִיא הָלְכָה אַחֲרָיו, וְלֹא בַּעְלָהּ. וַיִּגַּשׁ גֵּיחֲזִי לְהָדְפָהּ, הֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וַיֹּאמֶר אִישׁ הָאֱלֹהִים הַרְפֵּה לָהּ. מַה שּׁוֹנֶה כָּאן שֶׁאָמַר אִישׁ הָאֱלֹהִים, וּכְשֶׁהָיָה בָּעִיר אֱלִישָׁע? אֶלָּא כָּאן וַדַּאי אִישׁ הָאֱלֹהִים, שֶׁכָּאן (הוא) מְקוֹמוֹ וְלֹא בָּעִיר, וְלֹא בְּשָׁעָה שֶׁהָיוּ בְּנֵי הַנְּבִיאִים לְפָנָיו.</p>\n<p>וַה' הֶעְלִים מִמֶּנִּי וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר (שם יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה, זֶה בֵּית דִּין שֶׁל מַטָּה. וְלֹא הִגִּיד לִי, מָה הַטַּעַם לֹא יָדַע אֱלִישָׁע? אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמָה אֲנִי אֶהֱרֹג אֶת זֶה? אִם אֹמַר לוֹ - לֹא יָמוּת, כִּי הַמַּתָּנָה שֶׁלּוֹ הִיא. וַדַּאי שֶׁיֵּשׁ לוֹ לָמוּת, שֶׁהֲרֵי נֶאֱמַר, שֶׁכָּתוּב אַתְּ חֹבֶקֶת בֵּן, וּמִמְּקוֹם הַנְּקֵבָה גּוֹרֵם מָוֶת, וְלָכֵן לֹא אָמַר לוֹ.</p>\n<p>וַיֹּאמֶר לְגֵיחֲזִי חֲגֹר מָתְנֶיךְ וְקַח מִשְׁעַנְתִּי בְיָדְךְ וָלֵךְ. וַהֲרֵי פֵּרְשׁוּהָ שֶׁהִסְתַּלֵּק הַנֵּס מִמֶּנּוּ. חַי ה' וְחֵי נַפְשְׁךְ אִם אֶעֶזְבֶךָּ, לָמָּה? כֵּיוָן שֶׁגֵּיחֲזִי הָיָה הוֹלֵךְ. אֶלָּא שֶׁהִיא יָדְעָה אֶת דַּרְכֵי אוֹתוֹ גֵּיחֲזִי הָרָשָׁע, שֶׁאֵינוֹ כְּדָאִי שֶׁיִּמָּצֵא נֵס עַל יָדוֹ.</p>\n<p>וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו וְגוֹ', לָמָּה? אֶלָּא שֶׁאֱלִישָׁע הִשְׁגִּיחַ וְיָדַע שֶׁמָּקוֹם (שהאשה הוא) זֶה הוּא שֶׁגָּרַם, שֶׁנִּקְשָׁר בּוֹ כָּעֵת. וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו, לִקְשֹׁר אוֹתוֹ לְמָקוֹם אַחֵר עֶלְיוֹן, הַמָּקוֹם שֶׁנִּמְצָאִים בּוֹ חַיִּים.</p>\n<p>וְלֹא יָכֹל לַעֲקֹר אוֹתוֹ מִמָּקוֹם שֶׁנִּקְשַׁר בּוֹ בַּתְּחִלָּה, אֶלָּא עוֹרֵר רוּחַ אַחַת מִלְמַעְלָה, וְנִקְשַׁר בְּמָקוֹם זֶה וְהֵשִׁיב לוֹ אֶת נַפְשׁוֹ, שֶׁאִם לֹא כָּךְ, לֹא הָיָה עוֹמֵד לְעוֹלָמִים. וַיְזוֹרֵר הַנַּעַר עַד שֶׁבַע פְּעָמִים, וְלֹא עָלָה יוֹתֵר, כְּמוֹ שֶׁנֶּאֱמַר יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה.</p>\n<p>וְזְהִ הוּא חֲבַקּוּק הַנָּבִיא, כְּמוֹ שֶׁנֶּאֱמַר אַתְּ חֹבֶקֶת בֵּן. אִם כָּךְ, הָיָה צָרִיךְ לִהְיוֹת חָבוּק, לָמָּה פַּעֲמַיִם - חֲבַקּוּק? אֶלָּא אֶחָד שֶׁל אִמּוֹ, וְאֶחָד שֶׁל אֱלִישָׁע שֶׁהִתְחַבֵּק עִמּוֹ. דָּבָר אַחֵר, שְׁנֵי חִבּוּקִים הָיוּ בוֹ, בֵּין לְצַד זֶה בֵּין לְצַד זֶה. חִבּוּק אֶחָד, אוֹתוֹ מָקוֹם שֶׁהָיָה תָּלוּי בּוֹ בַּתְּחִלָּה. חִבּוּר אַחֵר, שֶׁהֶעֱלָה אוֹתוֹ לִדְרָגוֹת יוֹתֵר עֶלְיוֹנוֹת, וְלָכֵן חֲבַקּוּק-שְׁנַיִם.</p>\n<p>תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא (חבקוק ג) - אֵיזוֹ תְפִלָּה? אֶלָּא זֶהוּ מָקוֹם שֶׁהָיָה קָשׁוּר בּוֹ בַּתְּחִלָּה, וְזֶהוּ תְּפִלָּה שֶׁל יָד. עַל שִׁגְיֹנוֹת - שֶׁאוֹתוֹ יוֹם שֶׁנִּקְשַׁר בּוֹ, הָיוּ תְלוּיִים שִׁגְיוֹנוֹת הָעוֹלָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּגְבוּרָה הָיְתָה שׁוֹלֶטֶת, וְלָכֵן נִקְשְׁרָה בּוֹ תְּפִלָּה זוֹ (בזו התפלה).</p>\n<p>דָּבָר אַחֵר תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא - תְּפִלָּה לַחֲבַקּוּק, מִשּׁוּם חֲבַקּוּק שֶׁהוּא עָשָׂה בִּשְׁבִילוֹ. ה' שָׁמַעְתִּי שִׁמְעֲךְ יָרֵאתִי וְגוֹ', בּא רְאֵה, כְּשֶׁמִּתְעוֹרֶרֶת עָלָיו רוּחַ נְבוּאָה עַל מָקוֹם זֶה שֶׁהוּא תְּפִלָּה, הָיָה בָּא וְהָיָה פּוֹחֵד וּמִזְדַּעֲזֵעַ. מָשָׁל אוֹמְרִים, מִי שֶׁנִּנְשַׁךְ מִכֶּלֶב, מִקּוֹלוֹ הוּא מִזְדַּעֲזֵעַ.</p>\n<p>ה' פָּעָלְךְ בְּקֶרֶב שָׁנִים חַיֵּיהוּ, מִי זֶה פָּעָלְךְ? אֶלָּא עָלָיו אָמַר, שֶׁהוּא פֹּעַל שֶׁלּוֹ. בְּקֶרֶב שָׁנִים חַיֵּיהוּ, תֵּן לוֹ חַיִּים לְפָעָלְךְ זֶה בְּקֶרֶב שָׁנִים עֶלְיוֹנוֹת. דָּבָר אַחֵר חַיֵּיהוּ - שֶׁלֹּא יָמוּת כְּמוֹ שֶׁבַּתְּחִלָּה.</p>\n<p>עַל שִׁגְינוֹת, מַה זֶּה עַל שִׁגְינוֹת? עַל שְׁגִיאוֹת הָיָה צָרִיךְ (לכתב), כְּמוֹ שֶׁנֶּאֱמַר (תהלים יט) שְׁגִיאוֹת מִי יָבִין. אֶלָּא (הכל הוא. אבל) שִׁגְיֹנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם ז) שִׁגָּיוֹן לְדָוִד. מִינֵי תִשְׁבָּחוֹת הָיוּ לִפְנֵי הַנְּבִיאִים לְהַשְׁרוֹת עֲלֵיהֶם רוּחַ נְבוּאָה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א י) וּפָגַעְתָּ חֶבֶל נְבִיאִים יֹרְדִים מֵהַבָּמָה וְלִפְנֵיהֶם נֵבֶל וְתֹף וְגוֹ', וְכָתוּב וְעַתָּה קְחוּ לִי מְנַגֵּן וְגוֹ'. וְכָל שֶׁכֵּן חֲבַקּוּק שֶׁהִצְטָרֵךְ לוֹ יוֹתֵר מִכֻּלָּם, לְנַחַת הָרוּחַ, וּלְבַשֵּׂם אֶת אוֹתוֹ מָקוֹם, לְהַמְשִׁיךְ עָלָיו רוּחַ נְבוּאָה. וְכֵן כְּמוֹ כָּךְ כָּל הַנְּבִיאִים, פְּרָט לְמֹשֶׁה שֶׁעָלָה עַל כָּל שְׁאָר נְבִיאֵי הָעוֹלָם. אַשְׁרֵי חֶלְקוֹ!</p>\n<p>בֹּא רְאֵה, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, רוּחָם הָיְתָה שְׁבוּרָה בְתוֹכָם, וְהָיוּ שׁוֹמְעִים אוֹתָם תִּשְׁבָּחוֹת וְלֹא יְכוֹלִים לִשְׂמֹחַ. וּבְשָׁעָה שֶׁכָּל הָאוּכְלוּסִין וְהַמֶּרְכָּבוֹת יָצְאוּ עִם הַשְּׁכִינָה, כֻּלָּם הֵרִימוּ שִׁירִים וְתִשְׁבָּחוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת רוּחָם שֶׁל יִשְׂרָאֵל, וְהָיוּ שׁוֹמְעִים אֶת אוֹתָם תִּשְׁבָּחוֹת, וְעָמְדָה רוּחָם בְּתוֹכָם שֶׁלֹּא פָרְחוּ.</p>\n<p>כְּשֶׁאָדָם עוֹזֵב עֲבוֹדָה, אָז יוֹדֵעַ אֶת שִׁבְרוֹן הָעֲצָמוֹת וְשִׁבְרוֹן הָרוּחַ. כָּךְ יִשְׂרָאֵל, כְּשֶׁיָּצְאוּ מִמִּצְרַיִם, אָז טָעֲמוּ טַעַם הַמָּוֶת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רִפֵּא אוֹתָם, שֶׁכָּתוּב (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגוֹ'. וְכָל הַדְּרָכִים הָיוּ מַעֲלוֹת רֵיחוֹת שֶׁל רְפוּאָה, וְנִכְנָסִים לְגוּפָם וּמִתְרַפְּאִים, וְקוֹל הַתִּשְׁבָּחוֹת שֶׁהיוּ שׁוֹמְעִים, הָיוּ שְׂמֵחִים וְנָחִים בְּרוּחָם.</p>\n<p>וּפַרְעֹה וְכָל אוֹתָם הָאוּכְלוּסִים שֶׁלּוֹ הָיוּ הוֹלְכִים אַחֲרֵיהֶם לְלַוּוֹת אוֹתָם עַד שֶׁיָּצְאוּ מֵאֶרֶץ מִצְרַיִם, וְכָל כָּל אוֹתָם גְּדוֹלִים שָׂרִים הַמְמֻנִּים עֲלֵיהֶם וְעַל שְׁאָר הָעַמִּים, לִוּוּ אֶת הַשְּׁכִינָה וְאֶת יִשְׂרָאֵל כֻּלָּם, עַד שֶׁחָנוּ בְּאֵיתָם בִּקְצֵה הַמִּדְבָּר. זֶהוּ שֶׁכָּתוּב וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְגוֹ', כִּי קָרוֹב הוּא. כִּי קָרוֹב הוּא, אוֹתָהּ שְׁבוּעָה שֶׁנִּשְׁבַּע אֲבִימֶלֶךְ לָאָבוֹת עַל אוֹתוֹ טוֹב שֶׁעָשׂוּ הַפְּלִשְׁתִּים לָאָבוֹת, שֶׁכָּתוּב (בראשית כא) כַּחֶסֶד אֲשֶׁר עָשִׂיתִי עִמְּךְ תַּעֲשֶׂה עִמָּדִי וְעִם הָאָרֶץ אֲשֶׁר גַּרְתָּה בָּהּ.</p>"],[9522011601,"<p>וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם. מַה כָּתוּב לְמַעְלָה? וַיָּקָם פַּרְעֹה לַיְלָה הוּא וְכָל עֲבָדָיו. בֹּא רְאֵה, הַנְּקָמָה הָעֶלְיוֹנָה שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, שְׁלֹשָׁה סוּגֵי מָוֶת הָיוּ: אֶחָד שֶׁעָשׂוּ הַבְּכוֹרִים בְּמִצְרַיִם, שֶׁהָרְגוּ כָּל אוֹתָם שֶׁנִּמְצְאוּ. וְאֶחָד שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲצוֹת הַלַּיְלָה. וְאֶחָד כְּשֶׁרָאָה פַרְעֹה אֶת הַמָּוֶת בְּבֵיתוֹ בְּבָנָיו וּבַעֲבָדָיו, קָם וְזֵרַז אֶת עַצְמוֹ, וְהָרַג שָׂרִים וּמוֹשְׁלִים וְכָל מִי שֶׁיָּעַץ לוֹ לְסָרֵב לָעָם, עַד שֶׁהַתּוֹרָה מְעִידָה עָלָיו שֶׁהוּא קָם בַּלַּיְלָה מַמָּשׁ, כְּמוֹ (שהקדושברוך הואבחצות) שֶׁהַלַּיְלָה הָרַג בְּכוֹרוֹת וְעָשָׂה נְקָמוֹת, כָּךְ קָם פַּרְעֹה בְּאֶרֶץ מִצְרַיִם וְהָרַג וְעָשָּׂה נְקָמוֹת בְּשָׂרָיו וּמוֹשְׁלָיו וַאֲמַרְכְּלָיו וּבְכָל אוֹתָם גְּדוֹלִים. זֶהוּ שֶׁכָּתוּב (שמות יב) וַיָּקָם פַּרְעֹה לַיְלָה (לילה ממש), שֶׁקָּם לַהֲרֹג וּלְהַשְׁמִיד.</p>\n<p>דֶּרֶךָ הַכֶּלֶב, כְּשֶׁמַּכִּים אוֹתוֹ בְּאֶבֶן, הוּא בָּא וְנוֹשֵׁךְ אֶת חֲבֵרוֹ. כָּךְ פַּרְעֹה, אַחַר הוּא הָיָה הוֹלֵךְ בַּשְּׁוָקִים, וְהָיָה מַכְרִיז וְאוֹמֵר: קוּמוּ צְּאוּ מִתּוֹךְ עַמִּי, אַתֶּם הֲרַגְתֶּם לְכָל בְּנֵי הָעִיר, אַתֶּם הֲרַגְתֶּם הַשָּׂרִים וְהַמּוֹשְׁלִים וְכָל בְּנֵי בֵיתִי. זֶהוּ שֶׁכָּתוּב וַיִּקְרָא לְמֹשֶׁה וּלְאַהֲרֹן לַיְלָה. כֵּיוָן שֶׁבְּיֶדְכֶם הָיָה הַכֹּל - וּבֵרַכְתֶּם גַּם אֹתִי, שֶׁלֹּא תַהַרְגוּ אוֹתִי. אַחַר כָּךְ הוּא בְּעַצְמוֹ לִוָּה אוֹתָם וְהוֹצִיא אוֹתָם מֵהָאָרֶץ. זֶהוּ שֶׁכָּתוּב וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְגוֹ'.</p>"],[9522011602,"<p>וַיַּסֵּב אֱלֹהִים אֶת הָעָם דֶּרֶךְ הַמִּדְבָּר יַם סוּף, לְתַקֵּן דֶּרֶךְ לִמְקוֹמָהּ. רַבִּי יְהוּדָה אָמַר, מַה שּׁוֹנֶה כְּשֶׁהָיוּ יִשְׂרָאֵל בְּמִצְרַיִם, שֶׁכָּתוּב (שם ה) שַׁלַּח אֶת עַמִּי, (שם ט) כִּי אִם מָאֵן אַתָּה לְשַׁלֵּחַ אֶת עַמִּי, (שם ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וּבְאוֹתוֹ זְמַן לֹא הָיוּ מְהוּלִים וְלֹא נִקְשְׁרוּ בוֹ כָּרָאוּי, וְכָאן, שֶׁהָיוּ מְהוּלִים וְעָשׂוּ פֶסַח וְנִקְשְׁרוּ בוֹ, קָרָא לָהֶם אֶת הָעָם?</p>\n<p>אֶלָּא מִשּׁוּם עֵרֶב רַב שֶׁנִּדְבְּקוּ בָהֶם וְהִתְעָרְבוּ עִמָּהֶם, קָרָא לָהֶם אֶת הָעָם סְתָם, כְּמוֹ שֶׁנֶּאֱמַר (שם לג) וַיִּגֹּף ה' אֶת הָעָם עַל אֲשֶׁר עָשׂוּ אֶת הָעֵגֶל. וַיִּקָּהֵל הָעָם עַל אַהֲרֹן. וַיַּרְא הָעָם כִּי בֹשֵׁשׁ מֹשֶׁה. וְכֵן כֻּלָּם.</p>\n<p>רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים מֵאוּשָׁא לְלוֹד, וְהָיָה עִמָּהֶם יוֹסֵי הַסּוֹחֵר עִם גְּמַלִּים קְשׁוּרִים וּמַשָּׂאוֹת עַל כִּתְפֵיהֶם. עַד שֶׁהָיוּ הוֹלְכִים, מָצָא יוֹסֵי הַסּוֹחֵר אִשָּׁה אַחַת מִשְּׁאָר הָעַמִּים שֶׁלִּקְּטָה יְרָקוֹת בַּשָּׂדֶה. נִשְׁמַט מֵהֶם וְהֶחֱזִיק בָּהּ וּבָא עָלֶיהָ. תָּמְהוּ רַבִּי יִצְחָק וְרַבִּי יְהוּדָה. אָמְרוּ, נָשׁוּב מֵהַדֶּרֶךְ הַזּוֹ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְהַרְאוֹת לָנוּ שֶׁלֹּא נִתְחַבֵּר עִמּוֹ. שָׁבוּ מֵהַדֶּרֶךְ, בָּדְקוּ אַחֲרָיו, וּמָצְאוּ שֶׁהָיָה בֵּן שֶׁל בַּת אֵל נֵכָר, וְאָבִיו זֶרַע פָּסוּל הָיָה. אָמְרוּ: בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילָנוּ.</p>\n<p>פָּתַח רַבִּי יִצְחָק וְאָמַר, (תהלים לז) אַל תִּתְחַר בַּמְּרֵעִים. מִי הֵם הַמְּרֵעִים, שֶׁלֹּא כָתוּב חַטָּאִים אוֹ רְשָׁעִים? אֶלָּא מְרֵעִים, שֶׁמְּרֵעִים לְעַצְמָם וּלְאוֹתָם שֶׁמִּתְחַבְּרִים עִמָּם. רַבִּי יְהוּדָה אָמַר, מְרֵעִים - הַרְחֵק עַצְמְךְ מִמְּרֵעִים, שֶׁלֹּא תִהְיוּ רֵעִים וַחֲבֵרִים כְּאֶחָד, שֶׁלֹּא יָרֵעוּ לְךְ מַעֲשָׂיו וְתִתָּפֵס בַּחֲטָאָיו.</p>\n<p>בֹּא רְאֵה, אִלּוּלֵי הָיוּ אוֹתָם עֵרֶב רַב שֶׁהִתְחַבְּרוּ עִם יִשְׂרָאֵל, לֹא נַעֲשֶׂה הָיָה אוֹתוֹ מַעֲשֶׂה, וְלֹא מֵתוּ מִיִּשְׂרָאֵל כָּל אוֹתָם שֶׁמֵּתוּ, וְלֹא גָרַם לְיִשְׂרָאֵל מַה שֶּׁגָּרַם. וּבֹא רְאֵה, אוֹתוֹ מַעֲשֶׂה וְאוֹתוֹ חֵטְא מַמָּשׁ גָּרַם לְגָלוּת יִשְׂרָאֵל.</p>\n<p>שֶׁשָּׁנִינוּ, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּמָּצְאוּ יִשְׂרָאֵל בְּאוֹתָהּ שָׁעָה כְּמוֹ מַלְאָכִים עֶלְיוֹנִים וְלַעֲשׂוֹת אוֹתָם חוֹרִין מֵהַכֹּל, בְּנֵי חֵרוּת מִמָּוֶת, וְלִהְיוֹת בְּנֵי חוֹרִין מִשִּׁעְבּוּד שֶׁל שְׁאָר הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (שמות לב) חָרוּת עַל הַלֻּחֹת. אַל תִּקְרֵי חָרוּת אֶלָּא חֵרוּת.</p>\n<p>כֵּיוָן שֶׁנַּעֲשָׂה אוֹתוֹ מַעֲשֶׂה - גָּרְמוּ הַכֹּל. גָּרְמוּ מָוֶת, גָּרְמוּ שִׁעְבּוּד מַלְכֻיּוֹת, גָּרְמוּ שֶׁנִּשְׁבְּרוּ אוֹתָם לוּחוֹת רִאשׁוֹנִים, גָּרְמוּ שֶׁמֵּתוּ מִיִּשְׂרָאֵל כַּמָּה אֲלָפִים מֵהֶם. וְכָל זֶה מִשּׁוּם הַהִתְחַבְּרוּת שֶׁל אוֹתָם עֵרֶב רַב שֶׁהִתְחַבְּרוּ בָהֶם.</p>\n<p>אַף כָּאן בִּגְלָלָם לֹא נִקְרְאוּ בְּנֵי יִשְׂרָאֵל, וְלֹא יִשְׂרָאֵל, וְלֹא עַמִּי, אֶלָּא הָעָם סְתָם. וְאִם תֹּאמַר, וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל? כְּשֶׁהָיוּ עוֹלִים מִמִּצְרַיִם וְלֹא הִתְחַבְּרוּ עִמָּם אוֹתָם עֵרֶב רַב, קָרָא לָהֶם בְּנֵי יִשְׂרָאֵל. כֵּיוָן שֶׁהִתְחַבְּרוּ עִמָּם, שֶׁכָּתוּב וְגַם עֵרֶב רַב עָלָה עִמָּם, קָרָא לָהֶם הָעָם.</p>\n<p>רַבִּי יוֹסֵי הִקְשָׁה וְאָמַר, כָּתוּב כִּי אֲשֶׁר רְאִיתֶם אֶת מִצְרַיִם הַיּוֹם לֹא תוֹסִיפוּ לִרְאוֹתָם עוֹד עַד עוֹלָם. אִם כָּךְ, כָּל יוֹם הָיוּ רוֹאִים אֶת אוֹתוֹ עֵרֶב רַב? אָמַר רַבִּי יְהוּדָה, עֵרֶב רַב כָּתוּב, וְלֹא מִצְרַיִם, שֶׁהֲרֵי כַּמָּה שְׁאָר עַמִּים הָיוּ דָרִים בְּמִצְרַיִם, וְלֹא עוֹד, אֶלָּא שֶׁכֻּלָּם נִמּוֹלוּ, וְכֵיוָן שֶׁנִּמּוֹלוּ, יוֹתֵר לֹא נִקְרְאוּ מִצְרִים.</p>\n<p>וְעַל פִּי מֹשֶׁה קִבְּלוּ אוֹתָם, וְהַיְנוּ מַה שֶּׁאָמַר הַכָּתוּב לֶךְ רֵד כִּי שִׁחֵת עַמְּךְ סָרוּ מַהֵר מִן הַדֶּרֶךְ אֲשֶׁר צִוִּיתִם. צִוִּיתָם כָּתוּב. וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם - אֶחָד מֵחֲמִשָּׁה הָיוּ. וְרַבִּי יוֹסֵי אוֹמֵר, חֲמִשָּׁה מִיִּשְׂרָאֵל, וְאֶחָד מֵהֶם. רַבִּי יְהוּדָה אוֹמֵר, וַחֲמֻשִׁים - אֶחָד מֵחֲמִשִּׁים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, מִשּׁוּם שֶׁאוֹתוֹ יוֹבֵל הֶעֱלָה אוֹתָם מִמִּצְרַיִם, מִשּׁוּם כָּךְ וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם, וְאִם לֹא - לֹא עָלוּ, וְלָכֵן הִתְעַכְּבוּ חֲמִשִּׁים יוֹם לְקַבֵּל תּוֹרָה. וּמֵאוֹתוֹ מָקוֹם יוֹצֵאת תּוֹרָה וְנִתְּנָה, וְעַל זֶה וַחֲמֻשִׁים חָסֵר, שֶׁבִּגְלַל זֶה עָלוּ בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרַיִם.</p>\n<p>וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף וְגוֹ'. לָמָּה הֶעֱלָה עַצְמוֹתָיו? אֶלָּא מִשּׁוּם שֶׁהָיָה רֹאשׁ לָרֶדֶת לַגָּלוּת, וְלֹא עוֹד, אֶלָּא שֶׁהוּא סִימַן הַגְּאֻלָּה הָיָה לוֹ, וְהִשְׁבִּיעַ אֶת יִשְׂרָאֵל עַל זֶה. זֶהוּ שֶׁכָּתוּב כִּי הַשְׁבֵּעַ הִשְׁבִּיעַ אֶת בְּנֵי יִשְׂרָאֵל, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁיִּשְׂרָאֵל הָיוּ עוֹסְקִים לְבַקֵּשׁ מָמוֹן מִן הַמִּצְרִים, וּמֹשֶׁה הָיָה עָסוּק בִּשְׁבוּעַת יוֹסֵף. וְיֵשׁ אוֹמְרִים שֶׁהָאָרוֹן הָיָה בַּנִּילוּס, וְהֶעֱלָה אוֹתוֹ בַּשֵּׁם הַקָּדוֹשׁ. וְעוֹד אָמַר מֹשֶׁה: יוֹסֵף, הִגִּיעַ זְמַן גְּאֻלַּת יִשְׂרָאֵל. וְאָמַר: עֲלֵה שׁוֹר. וְעָלָה. וְיֵשׁ שֶׁאוֹמְרִים שֶׁהָיָה בֵּין מַלְכֵי מִצְרַיִם, וּמִשָּׁם הֶעֱלָה (אותו). וְיֵשׁ אוֹמְרִים, כְּדֵי שֶׁלֹּא יַעֲשׂוּ אוֹתוֹ עֲבוֹדָה זָרָה שָׂמוּ אוֹתוֹ בַּנִּילוּס, וְשֶׂרַח בַּת אָשֵׁר הֶרְאֲתָה לְמֹשֶׁה.</p>"],[9522011603,"<p>וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם. רַבִּי יוֹסֵי פָּתַח, (תהלים כב) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר מִזְמוֹר לְדָוִד. כַּמָּה חֲבִיבָה הַתּוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אָהוּב הוּא לְמַעְלָה וְאָהוּב הוּא לְמַטָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְשִׁיב לִדְבָרָיו, וְלֹא עוֹזֵב אוֹתוֹ בָּעוֹלָם הַזֶּה, וְלֹא עוֹזֵב אוֹתוֹ לָעוֹלָם הַבָּא.</p>\n<p>וּבַתּוֹרָה צָרִיךְ לַעֲסֹק בַּיּוֹם וּבַלַּיְלָה, שֶׁכָּתוּב (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וְכָתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה וְגוֹ'. מֵילָא בַּיּוֹם, אֲבָל לָמָּה בַּלַּיְלָה? כְּדֵי שֶׁיִּהְיֶה מָצוּי אֶל הַשֵּׁם הַקָּדוֹשׁ שָׁלֵם. כְּמוֹ שֶׁאֵין יוֹם בְּלִי לַיְלָה, וְאֵינוֹ שָׁלֵם אֶלָּא זֶה עִם זֶה, כָּךְ צָרִיךְ בַּתּוֹרָה לְהִמָּצֵא עִם הָאָדָם יוֹם וָלַיְלָה, לִהְיוֹת שְׁלֵמוּת לָאָדָם יוֹמָם וָלַיְלָה.</p>\n<p>וַהֲרֵי נֶאֱמַר שֶׁעִקַּר הַלַּיְלָה מֵחֲצוֹת וְאֵילָךְ, וְאַף עַל גַּב שֶׁמַּחֲצִית הָרִאשׁוֹנָה בִּכְלַל הַלַּיְלָה הִיא, אֲבָל בַּחֲצוֹת הַלַּיְלָה נִכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, וְאָז צָרִיךְ לָאָדָם לָקוּם וְלַעֲסֹק בַּתּוֹרָה.</p>\n<p>וַהֲרֵי נֶאֱמַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, כֻּלָּם מַקְשִׁיבִים לְקוֹלוֹ. זֶהוּ שֶׁכּתוּב (שיר ח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי. וַהֲרֵי פֵּרְשׁוּהָ, הַיּוֹשֶׁבֶת בַּגַּנִּים - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁמְּשַׁבַּחַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשֶׁבַח הַתּוֹרָה בַּלַּיְלָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּשְׁתַּתֵּף עִמָּהּ לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשֶׁבַח הַתּוֹרָה.</p>\n<p>וּכְשֶׁבָּא הַבֹּקֶר, כְּנֶסֶת יִשְׂרָאֵל בָּאָה וּמִשְׁתַּעֲשֵׁעַ בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמוֹשִׁיט לָהּ שַׁרְבִיט שֶׁל חֶסֶד, וְלֹא רַק עָלֶיהָ לְבַדָּהּ, אֶלָּא עָלֶיהָ וְעַל אֵלּוּ שֶׁמִּשְׁתַּתְּפִים עִמָּהּ, וַהֲרֵי נֶאֱמַר שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה וְגוֹ'. וְעַל זֶה נִקְרֵאת אַיֶּלֶת הַשַּׁחַר.</p>\n<p>וְאָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁרוֹצֶה לְהָאִיר הַבּקֶר, נֶחְשָׁךְ, וְהָאוֹר נִהְיָה קוֹדֵר, וְקַדְרוּת נִמְצֵאת. אָז מִתְחַבֶּרֶת אִשָּׁה בְּבַעְלָהּ, שֶׁשָּׁנִינוּ, אִשָּׁה מְסַפֶּרֶת עִם בַּעְלָהּ לְדַבֵּר עִמּוֹ וְנִכְנֶסֶת לְהֵיכָלוֹ.</p>\n<p>אַחַר כָּךְ כְּשֶׁרוֹצָה הַשֶּׁמֶשׁ לְהִכָּנֵס, מֵאִיר וּבָא הַלַּיְלָה, וְנוֹטֵל אוֹתוֹ. אָז כָּל הַשְּׁעָרִים סְתוּמִים, וַחֲמוֹרִים נוֹעֲרִים, וּכְלָבִים נוֹבְחִים. כְּשֶׁנֶּחֱצֶה הַלַּיְלָה מַתְחִיל הַמֶּלֶךְ (לקרא) לָקוּם וְהַגְּבִירָה לְזַמֵּר, וּבָא הַמֶּלֶךְ וּמַקִּישׁ עַל שַׁעַר הַהֵיכָל, וְאוֹמֵר פִּתְחִי לִי אֲחוֹתִי רַעְיָתִי וְגוֹ'. וְאָז מִשְׁתַּעֲשֵׁעַ בְּנִשְׁמוֹת הַצַּדִּיקִים.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ שֶׁמִּתְעוֹרֵר בְּאוֹתוֹ זְמַן בְּדִבְרֵי תוֹרָה. וְלָכֵן כָּל אוֹתָם בְּנֵי הֵיכַל הַגְּבִירָה, כֻּלָּם צְרִיכִים לָקוּם בְּאוֹתוֹ זְמַן לְשַׁבֵּחַ אֶת הַמֶּלֶךְ, וְכֻלָּם מְשַׁבְּחִים לְפָנָיו. וְהַשֶּׁבַח שֶׁעוֹלֶה מֵהָעוֹלָם הַזֶּה, זֶה שֶׁהוּא רָחוֹק, (יותר) זֶה נַחַת רוּחַ לַקָּדוֹשׁ-בָּרוּךְ-הוּא מֵהַכֹּל.</p>\n<p>כְּשֶׁמִּסְתַּלֵּק הַלַּיְלָה וּבָא הַבֹּקֶר (ומחשיך) וְהִתְקַדֵּר, אָז הַמֶּלֶךְ וְהַגְּבִירָה בְּסוֹד בְּחֶדְוָה, וְנוֹתֵן לָהּ מַתָּנוֹת וּלְכָל בְּנֵי הֵיכָלָהּ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁהוּא בְּמִנְיָן.</p>\n<p>וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם - הַקָּדוֹשׁ בָּרוּךְ הוּא וּבֵית דִּינוֹ. אָמַר רַבִּי יִצְחָק, הַיְנוּ שֶׁשָּׁנִינוּ, שְׁכִינָה נוֹסַעַת בָּאָבוֹת. הֹלֵךְ לִפְנֵיהֶם יוֹמָם - זֶה אַבְרָהָם. בְּעַמּוּד עָנָן - זֶה יִצְחָק. לַנְחֹתָם הַדֶּרֶךְ - זֶה יַעֲקֹב, שֶׁכָּתוּב בּוֹ (בראשית לב) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ. וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם - זֶה דָּוִד הַמֶּלֶךְ.</p>\n<p>וְכֻלָּם מֶרְכָּבָה עֶלְיוֹנָה קְדוֹשָׁה לָלֶכֶת עִם יִשְׂרָאֵל בִּשְׁלֵמוּת הַכֹּל, כְּדֵי שֶׁהָאָבוֹת יִרְאוּ אֶת גְּאֻלָּתָם, שֶׁכָּתוּב וְאָנֹכִי אֲעַלְךְ גַּם עָלֹה, עִם הַמֶּרְכָּבָה. וְכָתוּב וַה' הֹלֵךְ וְגוֹ' לָלֶכֶת יוֹמָם וָלָיְלָה. וְכִי לָמָּה הָיוּ הוֹלְכִים יוֹמָם וָלַיְלָה? יֵלְכוּ בַּיּוֹם, וְלֹא יֵלְכוּ בַּלַּיְלָה כַּאֲנָשִׁים שֶׁבּוֹרְחִים, כֵּיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁמַר אוֹתָם, לָמָּה הָלְכוּ בַּיּוֹם וּבַלַּיְלָה? אֶלָּא כְּדֵי לְהִמָּצֵא בָהֶם שְׁלֵמוּת הַכֹּל, שֶׁאֵין שְׁלֵמוּת אֶלָּא יוֹם וָלַיְלָה.</p>\n<p>אָמַר רַבִּי אַבָּא, כָּךְ בֵּאַרְנוּ, וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן - זֶה אַבְרָהָם. וְלַיְלָה בְּעַמּוּד אֵשׁ - זֶה יִצְחָק. וְאִם כָּךְ, אֵיפֹה יַעֲקֹב? אֶלָּא שֶׁנֶּאֱמַר בַּדִּבּוּר הָרִאשׁוֹן, וְשָׁם הִתְחִיל, כְּמוֹ שֶׁכָּתוּב וַה'.</p>\n<p>וְלַיְלָה בְּעַמּוּד אֵשׁ, הָיָה מֵאִיר בְּצַד זֶה וּבָזֶה, כְּדֵי שֶׁהַמִּצְרִים יִרְדְּפוּ אַחֲרֵיהֶם, שֶׁיִּתְכַּבֵּד שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַרְכְּבוֹתָיו וּפָרָשָׁיו. כְּדֵי לָלֶכֶת יוֹמָם וָלַיְלָה, אַסְפַּקְלַרְיָה הַמְּאִירָה, וְשֶׁלֹּא מְאִירָה. וְעוֹד, כְּדֵי לְהַטְעוֹת אֶת הַמִּצְרִים, שֶׁיֹּאמְרוּ מִקְרֶה הוּא, שֶׁכָּתוּב (ישעיה יט) נוֹאֲלוּ שָׂרֵי צוֹעַן, וְכָתוּב (שם מד) מֵשִׁיב חֲכָמִים אָחוֹר, וְעַל כֵּן הָלְכוּ בַּיּוֹם וּבַלַּיְלָה.</p>\n<p>רַבִּי אַבָּא אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא אוֹתָם מִמִּצְרַיִם לִהְיוֹת חֶלְקוֹ וְנַחֲלָתוֹ. וּבֹא רְאֵה, בְּצַד הַיּוֹבֵל נִמְצְאָה חֵרוּת לְיִשְׂרָאֵל, וְכֵן לֶעָתִיד לָבא, שֶׁכָּתוּב (ישעיה כז) וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וְגוֹ'.</p>\n<p>וּמִשּׁוּם אוֹתוֹ יוֹבֵל עֶלְיוֹן, הִתְעַכְּבוּ חֲמִשִּׁים יוֹם לְקַבֵּל הַתּוֹרָה וְלִקְרַב לְהַר סִינַי. וְכֵיוָן שֶׁהָלְכוּ בַּיּוֹם, הָלְכוּ בַּלַּיְלָה, לִהְיוֹת הַכֹּל יוֹם אֶחָד בֵּין יוֹם וָלַיְלָה, וְלֹא נִמְצֵאת הַפְרָדָה.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁכֻּלָּם הָלְכוּ בִמְנוּחָה לִרְצוֹן נַפְשָׁם, בַּיּוֹם שֶׁקִּבְּלוּ הַתּוֹרָה, הָיוּ חֲמִשִּׁים יָמִים שְׁלֵמִים, יָמִים וְלֵילוֹת כָּרָאוּי, שֶׁאֵין יוֹם בְּלִי לַיְלָה, וְאֵין לַיְלָה בְּלִי יוֹם, וְלַיְלָה וָיוֹם נִקְרָא יוֹם אֶחָד. וְכֵיוָן שֶׁהָלְכוּ חֲמִשִּׁים יָמִים שְׁלֵמִים, אָז שָׁרוּ עֲלֵיהֶם אוֹתָם חֲמִשִּׁים יְמֵי הַיּוֹבֵל, וּמִצַּד שֶׁל הַיּוֹבֵל (בינה) נִתְּנָה לָהֶם תּוֹרָה, וְלָכֵן הָלְכוּ יוֹמָם וָלַיְלָה.</p>\n<p>וְאָמַר רַבִּי אַבָּא, כָּתוּב וַיְהִי כִּי זָקֵן יִצְחָק וַתִּכְהֶיןָ עֵינָיו, לָמָּה? הֲרֵי בֵּאַרְנוּ, שֶׁמִּי שֶׁאוֹהֵב רְשָׁעִים, כָּךְ הוּא. וּבא רְאֵה, בְּיִצְחָק נִכְלָל הַלַּיְלָה, וְלַיְלָה לֹא בָהִיר, וְעַל זֶה וַתִּכְהֶיןָ עֵינָיו, וְהַכֹּל אֶחָד.</p>\n<p>רַבִּי יִצְחָק פָּתַח וְאָמַר, וַיֵּגּד לְמֶלֶךְ מִצְרַיִם כִּי בָרַח הָעָם. וַיֵּגּד - מִי אָמַר לוֹ? אֶלָּא כָּךְ פֵּרְשׁוּהָ. אֲבָל חֲכָמָיו וּמְכַשְּׁפָיו הִתְכַּנְּסוּ אֵלָיו וְהוֹדִיעוּהוּ כִּי בָרַח הָעָם. וְלָמָּה אָמְרוּ אֶת זֶה? אֶלָּא רָאוּ בַּחָכְמָה שֶׁלָּהֶם שֶׁהָיוּ הוֹלְכִים יוֹמָם וָלַיִל, אָמְרוּ וַדַּאי שֶׁהֵם בּוֹרְחִים. וְלֹא עוֹד, אֶלָּא שֶׁרָאוּ שֶׁאֵינָם הוֹלְכִים בְּדֶרֶךְ יְשָׁרָה, כְּמוֹ שֶׁכָּתוּב וְיָשֻׁבוּ וְיַחֲנוּ לִפְנֵי פִּי הַחִירֹת.</p>"],[9522011604,"<p>וַיִּקַּח שֵׁשׁ מֵאוֹת וְגוֹ'. שֵׁשׁ מֵאוֹת לָמָּה? אָמַר רַבִּי יוֹסֵי, כְּנֶגֶד הַמִּנְיָן שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי. בָּחוּר - כְּנֶגֶד הַגְּבָרִים שֶׁהֵם הָעִקָּר שֶׁל כָּל יִשְׂרָאֵל. וְכֹל רֶכֶב מִצְרָיִם - שְׁאָר הַמֶּרְכָּבוֹת, שֶׁהֵם טְפֵלִים לַאֲחוֹרַיִם (לאחרים), כְּנֶגֶד הַטַּף, שֶׁכָּתוּב לְבַד מִטָּף. וְהַכֹּל עָשָׂה בַּעֲצַת מְכַשְּׁפָיו וַחֲכָמָיו. וְשָׁלִשִׁם עַל כֻּלּוֹ - הַכֹּל בְּחָכְמָה, כְּנֶגֶד דְּרָגוֹת הָעֶלְיוֹנוֹת שְׁנַיִם וְאֶחָד. רַבִּי יִצְחָק אָמַר, כְּתַרְגּוּמוֹ - וּמְזָרְזִין. שֶׁהָיוּ זְרִיזִים בַּכֹּל.</p>\n<p>וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר. רַבִּי חִיָּיא אָמַר, כָּתוּב יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה. בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן שִׁלְטוֹן לִגְדוֹלֵי הָעַמִּים לְמַעְלָה, נוֹתֵן לָהֶם לָעָם שֶׁלָּהֶם לְמַטָּה. וּבְשָׁעָה שֶׁמּוֹרִיד אוֹתָם מִדַּרְגָּתָם שֶׁלְּמַעְלָה, מוֹרִיד אֶת הָעָם לְמַטָּה. וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר - הֲרֵי הַמְמֻנֶּה שֶׁלָּהֶם, וּפֵרְשׁוּהָ, שֶׁהִנְהִיג אֶת מַרְכְּבוֹת שְׁאָר הָעַמִּים, וְכֻלָּם נָפְלוּ בְּמַחֲנֵה סִיסְרָא אַחַר כָּךְ, וְהַיְנוּ בָּחוּר (ואחר כך) וְכֹל רֶכֶב מִצְרָיִם.</p>\n<p>כָּתוּב (שיר א) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי. בּא רְאֵה, כְּדֻגְמַת סוּסָה נְקֵבָה נִרְאֲתָה לַסּוּסִים שֶׁל פַּרְעֹה, וּפֵרְשׁוּהָ. אֶלָּא לְסֻסָתִי בְּרִכְבֵי פַרְעֹה - בֹּא רְאֵה, בְּשָׁעָה שֶׁפַּרְעֹה הָיָה רוֹדֵף אַחַר יִשְׂרָאֵל, מֶה עָשָׂה? נָטַל סוּסוֹת נְקֵבוֹת, וְכָפַת אוֹתָן בְּמַרְכְּבוֹתָיו בַּתְּחִלָּה, וְאֶת הַסּוּסִים הַזְּכָרִים כָּפַת מֵאָחוֹר, וְהָיוּ הַזְּכָרִים מִתְחַמְּמִים כְּנֶגֶד הַנְּקֵבוֹת, וְהַנְּקֵבוֹת מְסָרְבוֹת, וּמִהֲרוּ לָרוּץ. כֵּיוָן שֶׁקָּרַב (וכאשר הדביק) אֶל יִשְׂרָאֵל, נָטַל אֶת הַנְּקֵבוֹת וְשָׂם אוֹתָם לְאָחוֹר, וְהַסּוּסִים הַזְּכָרִים לְפָנִים, כְּדֵי לְהָרַע לְיִשְׂרָאֵל וְלַעֲרֹךְ בָּהֶם קְרָב.</p>\n<p>כְּמוֹ זֶה, וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם, וְאַחַר כָּךְ חָזְרָה הַשְּׁכִינָה לַאֲחוֹרֵי יִשְׂרָאֵל, שֶׁכָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים וְגוֹ'. מִשּׁוּם כָּךְ דִּמִּיתִיךְ רַעְיָתִי.</p>"],[9522011605,"<p>וּפָסוּק זֶה הֲרֵי פֵּרְשׁוּהוּ, שֶׁהִקְרִיב אֶת כָּל חֵילוֹתָיו וּמַרְכְּבוֹתָיו לַעֲרֹךְ קְרָב. וְעוֹד וּפַרְעֹה הִקְרִיב, רַבִּי יוֹסֵי אָמַר, הֲרֵי נִתְבָּאֵר שֶׁהִקְרִיב אוֹתָם לִתְשׁוּבָה. וּפַרְעֹה הִקְרִיב.</p>\n<p>כָּתוּב (ישעיה כו) ה' בַּצַּר פְּקָדוּךְ צָקוּן לַחַשׁ וְגוֹ'. בַּצַּר פְּקָדוּךְ - לֹא פוֹקְדִים יִשְׂרָאֵל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁעַת מְנוּחָה, אֶלָּא בְּשָׁעָה שֶׁמְּצִיקִים לָהֶם, וְאָז כֻּלָּם פּוֹקְדִים אוֹתוֹ. צָקוּן לַחַשׁ - וְכֻלָּם מִתְפַּלְלִים בִּתְפִלּוֹת וּבְבַקָּשׁוֹת, וּמְרִיקִים לְפָנָיו תְּפִלּוֹת. אֵימָתַי? מוּסָרְךְ לָמוֹ. בְּשָׁעָה שֶׁפּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בִּרְצוּעָתוֹ, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד עֲלֵיהֶם בְּרַחֲמִים, וְאוֹתוֹ הַקּוֹל שֶׁלָּהֶם נוֹחַ לְפָנָיו כְּדֵי לְהִפָּרַע מִשּׂוֹנְאֵיהֶם, וּמִתְמַלֵּא עֲלֵיהֶם בְּרַחֲמִים.</p>\n<p>כְּמוֹ שֶׁפֵּרַשְׁנוּ, מָשָׁל לְיוֹנָה עִם הַנֵּץ וְכוּ', כָּךְ יִשְׂרָאֵל הָיוּ קְרֵבִים לַיָּם, וְהָיוּ רוֹאִים אֶת הַיָּם לִפְנֵיהֶם הוֹלֵךְ וְסוֹעֵר וְגַלָּיו עוֹלִים לְמַעְלָה, הָיוּ פּוֹחֲדִים. זָקְפוּ עֵינֵיהֶם וְרָאוּ אֶת פַּרְעֹה וּמַרְכְּבוֹתָיו, וַאֲבָנִים, חִצִּים וּבַלִּיסְטְרָאוֹת, וְאָז וַיִּירְאוּ מְאֹד. מֶה עָשׂוּ? וַיִּצְעֲקוּ בְנֵי יִשְׂרָאֵל. מִי גָרַם אֶת זֶה שֶׁקָּרְבוּ יִשְׂרָאֵל לַאֲבִיהֶם שֶׁל מַעְלָה? פַּרְעֹה. זֶהוּ שֶׁכָּתוּב וּפַרְעֹה הִקְרִיב, וַהֲרֵי זֶה נִתְבָּאֵר.</p>\n<p>וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ הִתְיַצְּבוּ וּרְאוּ אֶת יְשׁוּעַת ה'. אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהֲרֵי רוֹעֶה כְּמוֹ מֹשֶׁה הָלַךְ בְּתוֹכָם. כָּתוּב (שם סג) וַיִּזְכֹּר יְמֵי עוֹלָם מֹשֶׁה עַמּוֹ. וַיִּזְכֹּר יְמֵי עוֹלָם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. מֹשֶׁה עַמּוֹ - (מכאן למדנו) שֶׁמֹּשֶׁה הָיָה שָׁקוּל כְּכָל יִשְׂרָאֵל. וְלָמַדְנוּ מִזֶּה כִּי רוֹעֵה הָעָם הוּא מַמָּשׁ הָעָם כֻּלּוֹ. אִם הוּא זוֹכֶה - כָּל הָעָם זוֹכִים, וְאִם אֵינוֹ זוֹכֶה - כָּל הָעָם לֹא זוֹכִים וְנֶעֱנָשִׁים בִּגְלָלוֹ, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>הִתְיַצְבוּ וּרְאוּ - אֵין לָכֶם לַעֲרֹךְ קְרָב, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲרֹךְ קְרָב בִּשְׁבִילְכֶם, כְּמוֹ שֶׁנֶּאֱמַר ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. בֹּא רְאֵה, בְּאוֹתוֹ לַיְלָה כִּנֵּס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַפָּמַלְיָא שֶׁלּוֹ וְדָן אֶת דִּינֵי יִשְׂרָאֵל, וְאִלְמָלֵא שֶׁהִקְדִּימוּ הָאָבוֹת עַל יִשְׂרָאֵל, לֹא הָיוּ נִצּוֹלִים מִן הַדִּין. רַבִּי יְהוּדָה אָמַר, זְכוּת יַעֲקֹב הֵגֵנָּה עַל יִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב (תהלים קכד) לוּלֵי ה' שֶׁהָיָה לָנוּ יֹאמַר נָא יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא.</p>"],[9522011606,"<p>ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. רַבִּי אַבָּא פָּתַח, (ישעיהנח) אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶךְ עֲשׂוֹת חֲפָצֶךְ בְּיוֹם קָדְשִׁי. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם לְהִדָּבֵק בָּהֶם מִכָּל שְׁאָר עַמֵּי הָעוֹלָם, וּמִתּוֹךְ אַהֲבָתָם קֵרַב אוֹתָם אֵלָיו, וְנָתַן לָהֶם תּוֹרָה, וְנָתַן לָהֶם שַׁבָּת שֶׁהִיא קֹדֶשׁ מִכָּל שְׁאָר הַיָּמִים, וּמְנוּחָה מֵהַכֹּל, וְחֶדְוָה שֶׁל הַכֹּל, וּשְׁקוּלָה שַׁבָּת כְּנֶגֶד כָּל הַתּוֹרָה, וּמִי שֶׁשּׁוֹמֵר שַׁבָּת כְּאִלּוּ שָׁמַר אֶת כָּל הַתּוֹרָה.</p>\n<p>וְקָרָאתָ לַשַּׁבָּת עֹנֶג - עִנּוּג שֶׁל הַכֹּל, עִנּוּג הַנֶּפֶשׁ וְהַגּוּף, עִנּוּג לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים. וְקָרָאתָ לַשַּׁבָּת, מַה זֶּה וְקָרָאתָ? שֶׁיַּזְמִין אוֹתָהּ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כג) מִקְרָאֵי קֹדֶשׁ, כְּלוֹמַר מְזֻמָּנִים, כְּמוֹ מִי שֶׁמַּזְמִין אוֹרֵחַ לְבֵיתוֹ. וְעַל זֶה וְקָרָאתָ לַשַּׁבָּת עֹנֶג, שֶׁיַּזְמִין אוֹתָהּ כְּמוֹ שֶׁמַּזְמִינִים אוֹרֵחַ, בְּשֻׁלְחָן מְתֻקָּן וּבְבַיִת מְתֻקָּן כָּרָאוּי בְּמַאֲכָל וּבְמִשְׁתֶּה כָּרָאוּי יוֹתֵר עַל שְׁאָר הַיָּמִים. וְקָרָאתָ לַשַּׁבָּת עֹנֶג - מִבְּעוֹד יוֹם. לִקְדוֹשׁ ה' מְכֻבָּד - זֶה יוֹם הַכִּפּוּרִים, שְׁנַיִם שֶׁהֵם אֶחָד. וְכִבַּדְתּוֹ מֵעֲשׂוֹת דְּרָכֶיךְ - כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>מִמְּצוֹא חֶפְצְךְ וְדַבֵּר דָּבָר, וַהֲרֵי נִתְבָּאֵר, מִשּׁוּם שֶׁאוֹתוֹ דָּבָר עוֹלֶה וּמְעוֹרֵר דִּבּוּר שֶׁל חֹל לְמַעְלָה. מִי שֶׁמַּזְמִין אוֹרֵחַ, צָרִיךְ לְהִשְׁתַּדֵּל בּוֹ וְלֹא בְּאַחֵר.</p>\n<p>בֹּא רְאֵה, אוֹתוֹ הַדִּבּוּר שֶׁיּוֹצֵא מִפִּי הָאָדָם, עוֹלֶה וּמְעוֹרֵר הִתְעוֹרְרוּת עֶלְיוֹנָה, אִם לְטוֹב אִם לְרַע. וּמִי שֶׁיּוֹשֵׁב בְּעֹנֶג שַׁבָּת, אָסוּר לוֹ לְעוֹרֵר דִּבּוּר שֶׁל חֹל, שֶׁהֲרֵי הוּא פּוֹגֵם פְּגָם בַּיּוֹם הַקָּדוֹשׁ. מִי שֶׁיּוֹשֵׁב בְּהִלּוּלַת הַמֶּלֶךְ, לֹא רָאוּי שֶׁיַּעֲזֹב אֶת הַמֶּלֶךְ וְיִתְעַסֵּק בְּאַחֵר.</p>\n<p>וּבְכָל יוֹם צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה וּלְעוֹרֵר הִתְעוֹרְרוּת מִמַּה שֶּׁצָּרִיךְ, וּבְשַׁבָּת בְּדִבְרֵי שָׁמַיִם וּבִקְדֻשַּׁת הַיּוֹם צָרִיךְ לְהִתְעוֹרֵר, וְלֹא בְּדָבָר אַחֵר.</p>\n<p>בֹּא רְאֵה, כָּאן כְּשֶׁקָּרַב פַּרְעֹה לַעֲרֹךְ קְרָב עִם יִשְׂרָאֵל, בְּאוֹתוֹ זְמַן לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיְּעוֹרְרוּ יִשְׂרָאֵל הִתְעוֹרְרוּת לְמַטָּה כְּלָל, שֶׁהֲרֵי הַהִתְעוֹרְרוּת הִיא לְמַעְלָה, שֶׁהֲרֵי הָאָבוֹת הִקְדִּימוּ הִתְעוֹרְרוּת זֹאת לְמַעְלָה, וּזְכוּתָם עוֹמֶדֶת לְפָנָיו, (ועוררו התעוררות זו) וְלֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּשְׂרָאֵל יִתְעוֹרְרוּ לְמַטָּה כְּלָל. (שהרי במקום של מעלה היה) זֶהוּ שֶׁכָּתוּב ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִשׁוּן. וַדַּאי תַּחֲרִישׁוּן וְלֹא תְעוֹרְרוּ דָבָר, שֶׁלֹּא צָרִיךְ לָכֶם. וְכָאן נִכְלָל הַשֵּׁם הַקָּדוֹשׁ בְּאוֹתִיּוֹת רְשׁוּמוֹת, וַהֲרֵי הִתְעוֹרְרוּ בוֹ הַחֲבֵרִים.</p>\n<p>רַבִּי יוֹסֵי וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי יְהוּדָה, וַדַּאי שָׁנִינוּ, ה' בְּכָל מָקוֹם זֶה רַחֲמִים, וְאַף עַל גַּב שֶׁעוֹרֵךְ קְרָב וְעוֹשֶׂה דִין, אוֹתוֹ דִין הוּא בְּאַהֲבָה. וְכָךְ רָאִינוּ, שֶׁכָּתוּב ה' יִלָּחֵם לָכֶם, וְלֹא נִרְאָה בְּאוֹתוֹ דִין רַחֲמִים כְּלָל, שֶׁהֲרֵי כָּתוּב לֹא נִשְׁאַר בָּהֶם עַד אֶחָד.</p>\n<p>אָמַר לוֹ, דָּבָר זֶה שָׁמַעְתִּי מֵרַבִּי שִׁמְעוֹן שֶׁאָמַר, שֶׁאֲפִלּוּ כָּאן הָיָה הַדִּין בְּרַחֲמִים, שֶׁהַיָּם כִּסָּה עֲלֵיהֶם וּמֵתוּ, וְאַחַר כָּךְ הוֹצִיא אוֹתָם הַיָּם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בִּכְבוֹדָם וְנִקְבְּרוּ בָּאָרֶץ, וְלֹא רָצְתָה הָאָרֶץ לְקַבֵּל אוֹתָם, עַד שֶׁהוֹשִׁיט לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יְמִינוֹ, וְקִבְּלָה אוֹתָם. זֶהוּ שֶׁכָּתוּב נָטִיתָ יְמִינְךְ תִּבְלָעֵמוֹ אָרֶץ, וְלָכֵן (היה) זֶה הַדִּין בְּרַחֲמִים הָיָה.</p>\n<p>וְלָכֵן לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיְּעוֹרְרוּ יִשְׂרָאֵל דָּבָר בָּעוֹלָם, שֶׁאִם יְעוֹרְרוּ יִשְׂרָאֵל דָּבָר, לֹא יְעוֹרְרוּ אֶת שֵׁם הָרַחֲמִים, וְלֹא יַעֲשֶׂה דִּין בְּרַחֲמִים. זֶהוּ שֶׁכָּתוּב ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִשׁוּן, שֶׁלֹּא תְעוֹרְרוּ דָבָר. שֶׁהֲרֵי שֵׁם הָרַחֲמִים צָרִיךְ לְעוֹרֵר עֲלֵיהֶם לַעֲשׂוֹת דִּין בְּרַחֲמִים. וְעַל זֶה בִּקֵּשׁ שֶׁלֹּא תַעֲשׂוּ פְגָם וּתְעוֹרְרוּ דָבָר אַחֵר.</p>\n<p>אָמַר לוֹ, וַהֲרֵי כָּתוּב (זכריה יד) וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם. אִם כָּךְ, זֶה דִּין שֶׁהָיָה בְּרַחֲמִים. אָמַר לוֹ, כָּךְ הָיָה וַדַּאי הַדִּין בְּרַחֲמִים, שֶׁמּוֹתָם לֹא נִמְצָא כִּשְׁאָר מוֹת בְּנֵי הָעוֹלָם, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם שֶׁלֹּא יִהְיוּ כְּמוֹת שְׁאָר בְּנֵי הָעוֹלָם שֶׁהָרְגוּ אוֹתָם, אֶלָּא בְּנַחַת בְּלֹא צַעַר. זֶהוּ דִּין בְּרַחֲמִים.</p>\n<p>וּבְכָל מָקוֹם שֵׁם זֶה הוּא דִּין בְּרַחֲמִים, פְּרָט לְמָקוֹם אֶחָד, שֶׁכָּתוּב (ישעיהמב) ה' כַּגִּבּוֹר יֵצֵא וְגוֹ'. וְכִי כַּגִּבּוֹר וְלֹא גִבּוֹר? אֶלָּא יְשַׁנֶּה לְבוּשׁוֹ וְיִלְבַּשׁ לְבוּשִׁים אֲחֵרִים. כְּאִישׁ מִלְחָמוֹת, יְשַׁנֶּה מִינוֹ.</p>\n<p>וְעִם כָּל זֶה, הַדִּין הוּא יָתֵר, אֲבָל יֵשׁ בּוֹ רַחֲמִים, כַּכָּתוּב כַּגִּבּוֹר, וְלֹא גִבּוֹר. כְּאִישׁ מִלְחָמוֹת, וְלֹא אִישׁ מִלְחָמוֹת. שֶׁוַּדַּאי אַף עַל גַּב שֶׁעוֹשֶׂה דִּין, חָס עַל מַעֲשָׂיו. וְלָכֵן ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּחַר בָּהֶם לְחֶלְקוֹ וְלִירֻשָּׁתוֹ, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>"],[9522011607,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. דָּבָר זֶה נִתְבָּאֵר בְּסִפְרָא דִצְנִיעוּתָא, וְשָׁם הוּא הַסּוֹד שֶׁלּוֹ, וַיֹּאמֶר ה' אֶל מֹשֶׁה. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (יונה א) וַיִּתְפַּלֵּל יוֹנָה אֶל ה' אֱלֹהָיו מִמְּעֵי הַדָּגָה. מַה כָּתוּב לְמַעְלָה? וַיְמַן ה' דָּג גָּדוֹל. וַיְמַן - כְּמוֹ שֶׁנֶּאֱמַר (דניאל א) וַיְמַן לָהֶם הַמֶּלֶךְ דְּבַר יוֹם בְּיוֹמוֹ. אֲשֶׁר מִנָּה אֶת מַאֲכַלְכֶם.</p>\n<p>וַיְמַן ה' אֶת יוֹנָה לַדָּג, שֶׁהוּא מָנָה, הוּא שָׁלַח אוֹתוֹ. אֶלָּא וַדַּאי אוֹתוֹ דָג הָיָה מָנָה לְיוֹנָה לִשְׁמֹר אוֹתוֹ מִשְּׁאָר דְּגֵי הַיָּם וְיִהְיֶה גָנוּז בְּתוֹכוֹ. וְכֵיוָן שֶׁהִכְנִיסוֹ לְתוֹכוֹ, רָאָה יוֹנָה בְּמֵעָיו רֹחַב שֶׁל מְקוֹם הַיָּם (רחב של מקום מעיו) כְּמוֹ הֵיכָל גָּדוֹל, וּשְׁנֵי עֵינֵי אוֹתוֹ דָג שֶׁמְּאִירִים כַּשֶּׁמֶשׁ, וְאֶבֶן טוֹבָה הָיְתָה בְּמֵעָיו שֶׁמְּאִירָה לוֹ, וְהָיָה רוֹאֶה כָּל מַה שֶּׁבַּיָּם וּבִתְהוֹמָיו.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, מַה שֶּׁכָּתוּב קָרָאתִי מִצָּרָה לִי, הֲרֵי לֹא נִרְאֶה שֶׁכָּל הָרְוָחָה הַזּוֹ הָיְתָה לוֹ? אֶלָּא וַדַּאי, כֵּיוָן שֶׁהֶרְאָה לוֹ אוֹתוֹ הַדָּג כָּל מַה שֶּׁבַּיָּם וּבִתְהוֹמָיו - מֵת, שֶׁלֹּא יָכֹל שְׁלֹשָׁה יָמִים לִסְבֹּל, וְאָז הָיְתָה לְיוֹנָה מְצוּקָה.</p>\n<p>שֶׁאָמַר רַבִּי אֶלְעָזָר, כֵּיוָן שֶׁרָאָה יוֹנָה אֶת כָּל אוֹתָהּ רְוָחָה, הָיָה שָׂמֵחַ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַה תִּרְצֶה יוֹתֵר? וְכִי לָזֶה הִכְנַסְתִּי אוֹתְךְ כָּאן?. מֶה עָשָׂה? הָרַג אֶת אוֹתוֹ דָג וּמֵת, וְכָל שְׁאָר דְּגֵי הַיָּם הָיוּ סְבִיב אוֹתוֹ דָג. זֶה נוֹשֵׁךְ אוֹתוֹ מִצַּד זֶה, וְזֶה נוֹשֵׁךְ אוֹתוֹ מִצַּד זֶה, וְאָז רָאָה יוֹנָה אֶת עַצְמוֹ בְּצָרָה. מִיָּד - וַיִּתְפַּלֵּל יוֹנָה אֶל ה'.</p>\n<p>בַּתְּחִלָּה דָּג, וְכָעֵת דָּגָה, כַּנֶּאֱמַר וְהַדָּגָה אֲשֶׁר בַּיְאֹר מֵתָה. וְאָז כָּתוּב קָרָאתִי מִצָּרָה לִי, וְלֹא כָתוּב הָיִיתִי בְצָרָה אוֹ יָשַׁבְתִּי בְצָרָה, אֶלָּא קָרָאתִי, מֵאוֹתָהּ צָרָה שֶׁהֵצִיקוּ לִי דְּגֵי הַיָּם. מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי, שֶׁהֲרֵי מֵת. וְלֹא כָתוּב מִבֶּטֶן חַי אוֹ מִבֶּטֶן דָּג, אֶלָּא שֶׁהָיָה וַדַּאי מֵת.</p>\n<p>כֵּיוָן שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ, קִבֵּל אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֶחֱיָה אֶת הַדָּג הַזֶּה, וְהוֹצִיאוֹ לַיַּבָּשָׁה לְעֵין כֹּל, שֶׁכָּתוּב וַיֹּאמֶר ה' לַדָּג וַיָּקֵא אֶת יוֹנָה. וְכֻלָּם רָאוּ אֶת מַעֲשֵׂה הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מַה כָּתוּב? וַיִּתְפַּלֵּל יוֹנָה אֶל ה' אֱלֹהָיו מִמְּעֵי הַדָּגָה, לַמָּקוֹם שֶׁהָיָה קָשׁוּר בּוֹ. מַשְׁמָע שֶׁכָּתוּב ה' אֱלֹהָיו, וְלֹא כָתוּב וַיִתְפַּלֵּל אֶל ה' וְלֹא יוֹתֵר, אֶלָּא ה' אֱלֹהָיו. אַף כָּאן, וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. אֵלַי דַּוְקָא.</p>\n<p>דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִסָּעוּ. וְיִסָּעוּ מִלְּהַרְבּוֹת בִּדְבָרִים. זֶה לֹא זְמַן תְּפִלָּה כָּעֵת. וְיִסָּעוּ, וְכִי לְאֵיזֶה מָקוֹם צִוָּה אוֹתוֹ שֶׁיִּסְעוּ, שֶׁהֲרֵי עַל הַיָּם הֵם הָיוּ שְׁרוּיִים? אֶלָּא חָזַר לְמַעְלָה, שֶׁכָּתוּב מַה תִּצְעַק אֵלָי, שֶׁהֲרֵי כֻּלָּם בְּמָקוֹם זֶה עוֹמְדִים. וְעַל זֶה וְיִסָּעוּ, יִסְעוּ מִזֶּה, שֶׁזֶּה אֵינוֹ הַזְּמַן (אלא בעתיק תלוי הדבר).</p>"],[9522011608,"<p>וְאַתָּה הָרֵם אֶת מַטְּךְ וְגוֹ'. הָרֵם אֶת מַטְּךְ, שֶׁבּוֹ רָשׁוּם הַשֵּׁם הַקָּדוֹשׁ. נְטֵה יָדְךְ בַּצַּד שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְכֵיוָן שֶׁהַמַּיִם יִרְאוּ אֶת הַשֵּׁם הַקָּדוֹשׁ, הֵם יִבְרְחוּ מִמֶּנּוּ וּמִלְּפָנָיו (לפניו). וְעַל זֶה וּנְטֵה אֶת יָדְךְ, לְצַד אֶחָד, שֶׁאֶת הַצְּדָדִים הָאֲחֵרִים שֶׁל אוֹתוֹ הַמַּטֶּה הִצְטָרֵךְ אוֹתוֹ לְמַיִם (לדברים) אֲחֵרִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, רָאִיתִי שֶׁלִּפְעָמִים הַמַּטֶּה הַזֶּה נִקְרָא מַטֵּה הָאֱלֹהִים, וְלִפְעָמִים נִקְרָא מַטֵּה מֹשֶׁה. אָמַר רַבִּי שִׁמְעוֹן (שנים היו, וכך בארנו) בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, יָפֶה אָמַר, שֶׁכֻּלָּם אֶחָד, בֵּין שֶׁתֹּאמַר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, בֵּין שֶׁתֹּאמַר שֶׁל מֹשֶׁה. וְהַמַּטֶּה הַזֶּה, לְעוֹרֵר צַד הַגְּבוּרָה. וְעַל זֶה וּנְטֵה אֶת יָדְךְ, יַד שְׂמֹאל, שֶׁהִיא מִצַּד הַגְּבוּרָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אוֹי לְאוֹתָם שֶׁלֹּא רוֹאִים וְלֹא מִסְתַּכְּלִים בַּתּוֹרָה, וְהַתּוֹרָה קוֹרֵאת לִפְנֵיהֶם בְּכָל יוֹם, (ולאיודעים) וְלֹא מַשְׁגִּיחִים. בֹּא רְאֵה, מִצַּד הַגְּבוּרָה מִתְעוֹרְרִים הַמַּיִם בָּעוֹלָם, וְיוֹצְאִים מַיִם, וְכָעֵת רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַבֵּשׁ אֶת הַמַּיִם, לָמָּה וּנְטֵה אֶת יָדְךְ, שֶׁהוּא שְׂמֹאל?</p>\n<p>אֶלָּא הָרֵם אֶת מַטְּךְ לְיַבֵּשׁ אֶת הַמַּיִם, וּנְטֵה אֶת יָדְךְ לְהָשִׁיב אֶת הַמַּיִם, לְעוֹרֵר אֶת צַד הַגְּבוּרָה וּלְהָשִׁיב הַמַּיִם עַל הַמִּצְרִים. וּמִשּׁוּם כָּךְ שְׁנֵי דְבָרִים כָּאן, שֶׁכָּתוּב הָרֵם אֶת מַטְּךְ, וּנְטֵה אֶת יָדְךְ עַל הַיָּם וּבְקָעֵהוּ.</p>\n<p>וַהֲרֵי הַתְּהוֹמוֹת הָיוּ? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה נֵס בְּתוֹךְ נֵס, כַּנֶּאֱמַר קָפְאוּ תְהֹמֹת בְּלֶב יָם. וְהָיוּ הוֹלְכִים בַּיַּבָּשָׁה בְּתוֹךְ הַיָּם. זֶהוּ שֶׁכָּתוּב וַיָּבאוּ בְנֵי יִשְׂרָאֵל בְּתוֹךְ הַיָּם בַּיַּבָּשָׁה.</p>"]]});
